var materialAdmin = angular.module("materialAdmin", [
    "ngStorage",
    "ui.router",
    "ui.bootstrap",
    "pascalprecht.translate",
    "angular-loading-bar",
    "ngResource",
    'oc.lazyLoad',
]);

materialAdmin.run([
    '$rootScope',
    '$injector',
    '$location',
    'authService',
    function ($rootScope, $injector, $location) {

        // Inicia a renovação automática do JWT.
        var authService = $injector.get('authService');

        authService.iniciar();

        // Encerra a renovação quando o usuário sair da sessão.
        $rootScope.$on('auth:logout', function () {
            authService.parar();
        });

        // Também interrompe a rotina se a aplicação for destruída.
        $rootScope.$on('$destroy', function () {
            authService.parar();
        });
    }
]);

materialAdmin.run(['$window',
    function ($window) {

        $window.fbAsyncInit = function () {

            FB.init({
                appId: '4382391205338957',
                cookie: true,
                xfbml: true,
                version: 'v22.0'
            });

            FB.AppEvents.logPageView();
        };

        (function (d, s, id) {

            var js;
            var fjs = d.getElementsByTagName(s)[0];

            if (d.getElementById(id)) {
                return;
            }

            js = d.createElement(s);
            js.id = id;
            js.src = 'https://connect.facebook.net/en_US/sdk.js';

            fjs.parentNode.insertBefore(js, fjs);

        }(document, 'script', 'facebook-jssdk'));

    }
]);


materialAdmin.service('authService', [
    '$http',
    '$interval',
    '$log',
    function ($http, $interval, $log) {
        var timer = null;
        var executando = false;

        function renovarSeNecessario() {
            if (executando) return;

            executando = true;

            return $http.post(
                'https://api.n3bot.com.br/usuarios/renovar_jwt.php',
                {},
                { withCredentials: true }
            ).then(function (response) {
                $log.info('[N3Bot JWT] Resposta:', response.data);
            }).catch(function (error) {
                $log.error(
                    '[N3Bot JWT] Erro na renovação:',
                    error.status,
                    error.data
                );
            }).finally(function () {
                executando = false;
            });
        }

        this.iniciar = function () {
            if (timer) return;

            console.log('[N3Bot JWT] Renovação automática iniciada');

            renovarSeNecessario();

            timer = $interval(function () {
                renovarSeNecessario();
            }, 60000);
        };

        this.parar = function () {
            if (timer) {
                $interval.cancel(timer);
                timer = null;
            }

            console.log('[N3Bot JWT] Renovação automática parada');
        };

        this.renovarSeNecessario = renovarSeNecessario;
    }
]);

materialAdmin.controller('TutorialVideoListaController', function ($scope, TutorialVideoService) {

    $scope.registros = [];
    $scope.onInit = function () {
        TutorialVideoService.getAll().then(function (response) {
            $scope.registros = response.data;

            angular.forEach($scope.registros, function (modulo) {
                angular.forEach(modulo.tutoriais, function (tutorial) {
                    tutorial.editLink = tutorial.link || '';
                });
            });

            updateComponentsAfterRequest();
        });
    };

    $scope.onUpdate = function (tutorial) {
        var payload = {
            id: tutorial.id,
            chave: tutorial.chave,
            link: tutorial.editLink
        };

        TutorialVideoService.update(payload).then(function () {
            updateComponentsAfterRequest();
        });
    };

});

materialAdmin.service('TutorialVideoService', function ($http, $setting) {

    this.getAll = function () {
        var request = $http({
            method: "get",
            url: $setting.api + "/tutorial_videos",
            isArray: true
        });

        return (request);
    };

    this.update = function (data) {
        var request = $http({
            method: "post",
            url: $setting.api + "/tutorial_videos/" + data.id,
            data: data
        });

        return (request);
    };

    this.getByDominio = function (revendaDominioId) {
        var request = $http({
            method: "get",
            url: $setting.api + "/tutorial_videos/dominio/" + revendaDominioId,
            isArray: true
        });

        return (request);
    };

    this.updateDominio = function (revendaDominioId, data) {
        var request = $http({
            method: "post",
            url: $setting.api + "/tutorial_videos/dominio/" + revendaDominioId,
            data: data
        });

        return (request);
    };

});


materialAdmin.config(function ($stateProvider, $urlRouterProvider) {

    $urlRouterProvider.otherwise('/blank');

    // State inicial
    $stateProvider.state('blank', {
        url: '/blank',
        templateUrl: 'sm-template.html'
    });

    // Registro dos módulos
    RouterWorkspace.build($stateProvider);
    RouterCrm.build($stateProvider);
    RouterDelivery.build($stateProvider);
    RouterHelpdesk.build($stateProvider);
    RouterLinkBio.build($stateProvider);
    RouterSales.build($stateProvider);
    RouterSms.build($stateProvider);
    RouterReleaseManager.build($stateProvider);
    RouterNovidades.build($stateProvider);
    RouterAvaliacoes.build($stateProvider);
    RouterReferralPartners.build($stateProvider);
    RouterAI.build($stateProvider);
    RouterMassCampaing.build($stateProvider);

});



