materialAdmin.controller('BackupController', function ($scope, $uibModal, ClienteService, CanalService, BackupService, $stateParams) {

    $scope.showMore = false;
    $scope.registros = [];
    $scope.canais = [];

    $scope.filtro = {};
    $scope.filtro.offset = 0;
    $scope.filtro.type = "ALL";
    $scope.filtro.status = "ALL";

    $scope.sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB', 'PB', 'EB', 'ZB', 'YB'];

    $scope.onInit = function () {
        $scope.getAll(true);
    };

    $scope.getAll = function (reset) {
        if (reset) {
            $scope.filtro.offset = 0;
        } else {
            $scope.filtro.offset += 20;
        }

        BackupService.getAll($scope.filtro).then(function (response) {
            if (reset) {
                $scope.registros = response.data;
            } else {
                $scope.registros = $scope.registros.concat(response.data);
            }

            $scope.showMore = response.data.length > 0;
        });
    }

    $scope.formatBytes = function (bytes, decimals) {
        for (var i = 0, r = bytes, b = 1024; r > b; i++) r /= b;
        return parseFloat(r.toFixed(decimals)) + " " + $scope.sizes[i];
    }

    $scope.onShowModalNovoRegistro = function () {
        $scope.novoRegistro = {};
        $scope.novoRegistro.type = 'CLIENT';

        $scope.modal = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/backups/modal-novo.html',
            scope: $scope
        });

        $scope.modal.opened.then(function () {
            updateComponentsAfterRequest();
        });
    };

    $scope.onSelectType = function () {
        $scope.canais = [];
        delete $scope.novoRegistro.canalId;

        if (!$scope.novoRegistro.cliente) {
            return;
        }

        var params = {
            clienteId: $scope.novoRegistro.cliente.id,
            excluidos: true
        }

        CanalService.getAll(params).then(function (response) {
            $scope.canais = response.data;
        });
    }

    $scope.onModalSalvar = function () {
        if (!$scope.novoRegistro.cliente) {
            return;
        }

        var data = angular.copy($scope.novoRegistro);
        data.clientId = $scope.novoRegistro.cliente.id;
        delete data.cliente;

        if (data.filterCreatedFrom) {
            data.filterCreatedFrom = data.filterCreatedFrom.getTime();
        }

        if (data.filterCreatedTo) {
            data.filterCreatedTo = data.filterCreatedTo.getTime();
        }

        BackupService.insert(data).then(function () {
            $scope.getAll(true);
            $scope.onModalClose();
        });
    };

    $scope.onModalClose = function () {
        $scope.modal.close();
    }

    $scope.onExcluir = function (backup) {
        BackupService.delete(backup.id).then(function () {
            $scope.getAll(true);
        });
    };

    $scope.onReset = function (backup) {
        BackupService.reset(backup.id).then(function () {
            $scope.getAll(true);
        });
    };

    $scope.runJob = function () {
        BackupService.runJob().then(function () {
            $scope.getAll(true);
        });
    };

    $scope.onShowLink = function (backup) {
        swal('Backup', backup.url, 'info');
    }

    $scope.getAutocompleteClientes = function (text) {
        var params = {};
        params.text = text;

        return ClienteService.getAllToOptions(params).then(function (response) {
            return response.data.map(function (item) {
                return item;
            });
        });
    };

});
;

