materialAdmin.controller('ConfiguracaoController', function ($rootScope, $scope, ConfiguracaoService) {

    $scope.configuracoes = {};
    $scope.configuracoes.notificacao = {};

    $scope.onInit = function () {
        ConfiguracaoService.getAll().then(function (response) {
            $scope.configuracoes = response.data;

            if (!$scope.configuracoes.notificacao) {
                $scope.configuracoes.notificacao = {};
            }

            if (!$scope.configuracoes.notificacao.cor) {
                $scope.configuracoes.notificacao.cor = '#555555';
            }

            updateComponentsAfterRequest();
        });
    };

    $scope.onUpdate = function (registro) {
        ConfiguracaoService.update($scope.configuracoes).then(function (response) {
            swal("Pronto!", "Configurações atualizadas com sucesso.", "success", 2000);
            updateComponentsAfterRequest();
        });
    };

});

