var usuarioUtils = {

    remover: function ($translate, UsuarioService, registro, callback) {
        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: $translate.instant("REMOVER-REGISTRO"),
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),
            closeOnConfirm: false,
            closeOnCancel: true
        }, function (isConfirm) {
            if (isConfirm) {
                UsuarioService.remover(registro.id).then(function () {
                    swal({
                        title: $translate.instant('PRONTO') + "!",
                        text: $translate.instant("REGISTRO-REMOVIDO"),
                        type: "success",
                        timer: 2000
                    }, function () {
                        callback();
                    });
                });
            }
        });
    },

    alterarStatus: function ($translate, UsuarioService, registro, callback) {
        var statusPergunta = registro.ativo ? $translate.instant('ATIVAR') : $translate.instant('INATIVAR');

        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: $translate.instant('STATUS-REGISTRO', { "status": statusPergunta }),
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),
            closeOnConfirm: false,
            closeOnCancel: true
        }, function (isConfirm) {
            if (isConfirm) {
                UsuarioService.atualizarStatus(registro).then(function () {
                    swal({
                        title: $translate.instant('PRONTO') + "!",
                        text: $translate.instant('REGISTRO-ATUALIZADO'),
                        type: "success",
                        timer: 5000
                    }, function () {
                        callback();
                    });
                });
            }
        });
    }

};
materialAdmin.controller('UsuarioListaController', function ($scope, $translate, $window, $uibModal, $localStorage, $state, UsuarioService, ClienteService, DepartamentoService, TaskRuleService, AuthTotpService) {

    $scope.listviewSearchStat = false;
    $scope.modalNovoRegistro;
    $scope.novoRegistro = {};
    $scope.novoRegistro.responsavel = {};
    $scope.registros = [];

    $scope.filtro = {};
    $scope.filtro.status = "ativos";
    $scope.filtro.perfil = "ALL";
    $scope.filtro.cargo = "ALL";
    $scope.showMore = false;

    // Cargos internos (coluna cargo_mz) - filtro/exibicao apenas para administradores com cargo de gerente
    $scope.cargos = [
        { value: "SOCIO", label: "Sócio" },
        { value: "GERENTE", label: "Gerente" },
        { value: "DESENVOLVEDOR", label: "Desenvolvedor" },
        { value: "LIDER_SUPORTE", label: "Líder de Suporte" },
        { value: "SUPORTE", label: "Suporte" },
        { value: "LIDER_VENDAS", label: "Líder de Vendas" },
        { value: "VENDEDOR", label: "Vendedor" },
        { value: "FINANCEIRO", label: "Financeiro" },
        { value: "AUXILIAR_FINANCEIRO", label: "Auxiliar Financeiro" }
    ];

    $scope.cargoLabel = function (value) {
        if (!value) {
            return "";
        }
        var cargo = $scope.cargos.find(function (c) {
            return c.value === value;
        });
        return cargo ? cargo.label : value;
    };

    // Cargos internos que podem ser trocados na edicao de um usuario ja criado.
    $scope.cargosEditaveis = ["SUPORTE", "LIDER_SUPORTE", "LIDER_VENDAS", "VENDEDOR"];

    $scope.isCargoEditavel = function (value) {
        return $scope.cargosEditaveis.indexOf(value) !== -1;
    };

    // Apenas DESENVOLVEDOR e GERENTE podem atribuir o cargo VENDEDOR (criacao e edicao).
    $scope.podeAtribuirVendedor = false;

    $scope.departamentoSelecionado = {};

    $scope.lvSearch = function () {
        this.listviewSearchStat = true;
    };

    $scope.onInit = function () {
        if ($state.params.cliente) {
            $scope.filtro.cliente = $state.params.cliente;
            $scope.getUsuarios();
        }

        DepartamentoService.getAtivos().then(function (response) {
            $scope.departamentos = response.data;
        });

        if ($scope.isAdministrador()) {
            UsuarioService.getCargoLogado().then(function (response) {
                $scope.usuarioCargo = response.data.cargo;
                $scope.podeAtribuirVendedor = $scope.usuarioCargo === "DESENVOLVEDOR" || $scope.usuarioCargo === "GERENTE";
            });
        }
    };

$scope.getUsuarios = function (pagination) {
    $scope.showMore = false;

    if (pagination) {
        $scope.filtro.offset += 20;
    } else {
        $scope.registros = [];
        $scope.filtro.offset = 0;
    }

    UsuarioService.getTodos($scope.filtro).then(function (response) {

        var dados = response.data || {};
        var usuarios = dados.clientes || [];

        // Converte os campos da API para os campos esperados pelo HTML.
        usuarios = usuarios.map(function (usuario) {

            var registro = angular.copy(usuario);

            registro.nome = registro.nome || registro.usuario || 'Sem nome';
            registro.login = registro.login || registro.usuario || '';
            registro.perfil = registro.perfil || registro.usuarioPerfil || '';
            registro.ativo = typeof registro.ativo === 'boolean'
                ? registro.ativo
                : String(registro.status || '').toLowerCase() === 'ativo';

            registro.has2FA = registro.has2FA === true || registro.twoFA === true;

            registro.cargoMz = registro.cargoMz || registro.cargo || '';

            return registro;
        });

        // Paginação.
        $scope.showMore =
            (Number(dados.offset || 0) + Number(dados.quantidade || usuarios.length))
            < Number(dados.total || 0);

        // Agrupa no formato esperado pelo HTML.
        var grupo = {
            id: 'N3BOT',
            nome: '',
            clientes: [{
                id: 'N3BOT',
                nome: '',
                usuarios: listToMatrix(usuarios, 3)
            }]
        };

        if (!pagination) {
            $scope.registros = [grupo];
        } else if ($scope.registros.length > 0) {

            var cliente = $scope.registros[0].clientes[0];

            var usuariosExistentes = cliente.usuarios.flat();
            var novosUsuarios = usuarios;

            cliente.usuarios = listToMatrix(
                usuariosExistentes.concat(novosUsuarios),
                3
            );

        } else {
            $scope.registros = [grupo];
        }

    }).catch(function (error) {
        console.error('Erro ao carregar usuários:', error);
        $scope.registros = [];
    });
};
    $scope.getSimples = () => {
        UsuarioService.getSimples().then(function (response) {
            $scope.registros = response.data;
        });
    };

    $scope.onMostarModalNovoRegistro = function () {
        $scope.novoRegistro = {
            perfil: 'SUPORTE'
        };

        $scope.modalNovoRegistro = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/usuarios/modal-novo-usuario.html?t=' + Date.now(),
            scope: $scope
        });

        $scope.modalNovoRegistro.rendered.then(function () {
            updateComponentsAfterRequest();
        });
    };

    $scope.onMostarModalEdicaoRegistro = function (registro) {
        $scope.novoRegistro = {
            id: registro.id,
            nome: registro.nome,
            login: registro.login,
            ativo: registro.ativo,
            email: registro.email,
            cargoMz: registro.cargoMz
        };

        $scope.modalNovoRegistro = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/usuarios/modal-edicao-usuario.html?t=' + Date.now(),
            scope: $scope,
            controller: function () {
                updateComponentsAfterRequest();
            }
        });
    };

    $scope.onMostarModalHorarios = function (registro) {
        $scope.usuarioId = registro.id;

        $scope.modalHorarios = $uibModal.open({
            animation: true,
            controller: 'UsuarioHorarioAtendimentoController',
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/usuarios/modal-horarios-acesso.html?t=' + new Date(),
            scope: $scope,
            size: 'xlg'
        });
    };

    $scope.onMostarModalEdicaoGestorMaster = (id) => {

        UsuarioService.findUsuarioGestorMaster(id).then((res) => {
            $scope.novoRegistro = res.data;

            $scope.modalNovoRegistro = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/usuarios/modal-edicao-gestor-master.html?t=' + Date.now(),
                scope: $scope,
                controller: function () {
                    updateComponentsAfterRequest();
                }
            });
        })

    };

    $scope.onModalAtualizar = function () {
        if (!isValidEmail($scope.novoRegistro.email)) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('E-mail inválido'),
                type: "warning"
            });

            return;
        }

        $scope.novoRegistro.emailAtendente = $scope.novoRegistro.email;
        UsuarioService.atualizar($scope.novoRegistro).then(function (response) {
            $scope.modalNovoRegistro.close();
            $scope.getUsuarios();
        });
    };

    $scope.onModalAtualizarGestorMaster = function () {
        if (!isValidEmail($scope.novoRegistro.email)) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('E-mail inválido'),
                type: "warning"
            });

            return;
        }

        $scope.novoRegistro.emailAtendente = $scope.novoRegistro.email;
        UsuarioService.atualizarGestorMaster($scope.novoRegistro.id, $scope.novoRegistro).then((response) => {
            $scope.modalNovoRegistro.close();
            $scope.onInit();
            $scope.getUsuarios();
        });
    };

    function isValidEmail(email) {
        const regex = /^[\w._%+-]+@[\w.-]+\.[a-zA-Z]{2,}$/;
        return regex.test(email);
    };

    $scope.selectChannelNewTicket = function () {
        $scope.novoAtendimentoNovoContato.canal = $scope.canais.find(function (canal) {
            return canal.chave === parseInt($scope.novoAtendimentoNovoContato.canalChave, 10);
        });
    }

    $scope.onModalInserir = function () {
        if ($scope.novoRegistro.cliente) {
            $scope.novoRegistro.clienteId = $scope.novoRegistro.cliente.id;
        }

        UsuarioService.inserir($scope.novoRegistro).then(function (response) {
            $scope.modalNovoRegistro.close();
            $scope.onInit();
        });
    };

    $scope.onResetarSenha = function (registro) {
        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: $translate.instant('RESET-SENHA-DESATIVADA'),
            type: "warning"
        });
        /*
        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: $translate.instant('RESETAR-SENHA-PERGUNTA'),
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),
            closeOnConfirm: false,
            closeOnCancel: true
        }, function (isConfirm) {
            if (isConfirm) {
                UsuarioService.resetarSenha(registro).then(function (response) {
                    swal({
                        title: "Nova senha gerada com sucesso!",
                        text: response.data.mensagem,
                        type: "success",
                        textClass: "nova-senha"
                    }, function () {
                        $scope.onInit();
                    });
                });
            }
        });
        */
    };

    $scope.onResetQrCodes = function (registro) {

        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: $translate.instant('RESETAR-QRCODES-PERGUNTA'),
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),
            closeOnConfirm: false,
            closeOnCancel: true
        }, function (isConfirm) {
            if (isConfirm) {
                AuthTotpService.disableAllQrCode(registro.id).then(function (response) {
                    swal({
                        title: "Desabilitada com sucesso!",
                        text: response.data.mensagem,
                        type: "success",
                    }, function () {
                        $scope.onInit();
                    });
                });
            }
        });
    };

    $scope.onModalCancelar = function () {
        $scope.modalNovoRegistro.close();
        $scope.novoRegistro = {};
    };

    $scope.onRemover = function (registro) {
        usuarioUtils.remover($translate, UsuarioService, registro, function () {
            $scope.onInit();
        });
    };

    $scope.removerGestorMaster = function (registro) {
        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: "Deseja mesmo excluir esse usuário?",
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('SIM'),
            cancelButtonText: $translate.instant('CANCELAR'),
            closeOnConfirm: false,
            closeOnCancel: true
        }, function (isConfirm) {
            if (isConfirm) {
                UsuarioService.removerGestorMaster(registro.id).then(res => {
                    swal({
                        title: "Sucesso!",
                        text: "Registro excluido",
                        type: "success"
                    }, function () {
                        $scope.getUsuarios();
                    });
                })
            }
        });
    };

    $scope.onAtivar = function (registro) {
        var registroAlterado = {
            id: registro.id,
            nome: registro.nome,
            login: registro.login,
            ativo: true
        };

        usuarioUtils.alterarStatus($translate, UsuarioService, registroAlterado, function () {
            $scope.onInit();
        });
    };

    $scope.onInativar = function (registro, atendendeId, atendendeNome) {
        var registroAlterado = {
            id: registro.id,
            nome: registro.nome,
            login: registro.login,
            ativo: false,
            atendenteTransferenciaId: atendendeId,
            atendenteTransferenciaNome: atendendeNome,
        };

        usuarioUtils.alterarStatus($translate, UsuarioService, registroAlterado, function () {
            if ($scope.modalDepartamentos) {
                $scope.modalDepartamentos.close();
            }
            $scope.onInit();
        });
    };

    $scope.onTransferencia = () => {
        if (!$scope.departamentoSelecionado || !$scope.departamentoSelecionado.atendenteId) {
            swal("Ops!", "Por favor selecione o atendente para transferência", "error");
            return;
        }

        const atendente = $scope.departamentoSelecionado.atendentes.find(a => a.id == $scope.departamentoSelecionado.atendenteId);

        $scope.onInativar($scope.registroSelecionado, atendente.id, atendente.nome);
    }

    $scope.verificarPendenciasUsuario = (registro) => {
    swal({
        title: $translate.instant("ATENCAO") + "!",
        text: $translate.instant("INATIVAR-USUARIO-ALERTA-PENDENCIAS"),
        type: "warning",
        showCancelButton: true,
        confirmButtonColor: "#DD6B55",
        confirmButtonText: $translate.instant("SIM"),
        cancelButtonText: $translate.instant("CANCELAR"),
        closeOnConfirm: true,
        closeOnCancel: true
    }, (isConfirm) => {
        if (isConfirm) {
            $scope.$applyAsync(() => {
                $scope.onInativar(registro);
            });
        }
    });
};

    $scope.abrirModalCodigoSuporte = function (registro) {
        $scope.usuarioSelecionado = registro;
        $scope.modalCodigoSuporte = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/usuarios/modal-codigo-suporte.html',
            scope: $scope
        });
    }

    $scope.cancelarModalCodigoSuporte = function () {
        delete $scope.usuarioSelecionado;
        $scope.modalCodigoSuporte.close();
    }

    $scope.login = function () {
        UsuarioService.authForced($scope.usuarioSelecionado).then(function (response) {
            $localStorage.token = response.data.token;
            $localStorage.deliveryMerchant = undefined;
            $localStorage.registerMachine = undefined;
            $scope.redirecionar()
        });
    };

    $scope.redirecionar = function () {
        var jwt = jwt_decode($localStorage.token);

        ClienteService.getPermissions().then(function (response) {
            $scope.permissions = response.data;

            if (jwt.usuarioPerfil === Perfil.GESTOR) {

                if ($scope.permissions.permissionMegazap) {
                    $window.location.href = "index.html#/bots/bot";
                } else if ($scope.permissions.permissionDelivery) {
                    $window.location.href = "index.html#/delivery/dashboard/manager";
                } else if ($scope.permissions.permissionSms) {
                    $window.location.href = "index.html#/sms/relatorios/historico";
                } else if ($scope.permissions.permissionLeads) {
                    $window.location.href = "index.html#/campanhas/dashboard";
                } else {
                    $window.location.href = "index.html#/sales/invoices/client";
                }

            } else if (jwt.usuarioPerfil === Perfil.SUPERVISOR_DELIVERY) {

                if ($scope.permissions.permissionDelivery) {
                    $window.location.href = "index.html#/delivery/dashboard/manager";
                }

            } else if (jwt.usuarioPerfil === Perfil.OPERADOR) {

                if ($scope.permissions.permissionDelivery) {
                    localStorage.setItem('ma-layout-status', '0');

                    if ($scope.permissions.user) {
                        if ($scope.permissions.user.permissionOrder) {
                            $window.location.href = "index.html#/delivery/orders";
                        } else if ($scope.permissions.user.permissionTableOrder) {
                            $window.location.href = "index.html#/delivery/table-orders";
                        } else if ($scope.permissions.user.permissionRegisterMachine) {
                            $window.location.href = "index.html#/delivery/pos";
                        } else {
                            $window.location.href = "index.html#/delivery/manager";
                        }
                    } else {
                        $window.location.href = "index.html#/delivery/manager";
                    }
                }

            } else if (jwt.usuarioPerfil === Perfil.GARCOM) {

                if ($scope.permissions.permissionDelivery) {
                    localStorage.setItem('ma-layout-status', '0');
                    $window.location.href = "index.html#/delivery/table-orders";
                }

            } else if (jwt.usuarioPerfil === Perfil.ATENDENTE) {

                if ($scope.permissions.permissionMegazap) {
                    $window.location.href = "index.html#/atendimentos/chat";
                }

            }

            $window.location.reload();
        });
    };

    $scope.onSelecionarDepartamento = function () {
        $scope.departamentoSelecionado.atendentes = $scope.departamentos.find((departamento) => {
            return departamento.id === parseInt($scope.departamentoSelecionado.departamentoId, 10);
        }).atendentes;

        $scope.departamentoSelecionado.atendenteId = '0';
    };

    $scope.getAutocompleteCliente = (filtro) => {
        return ClienteService.getTodosSimples(
            filtro
        ).then((response) => {
            return response.data.map(function (item) {
                return item;
            });
        });
    }

    $scope.onSelecionarCliente = () => {

        if (!$scope.novoRegistro.usuarioClientes) {
            $scope.novoRegistro.usuarioClientes = []
        }

        if ($scope.novoRegistro.usuarioClientes.find(c => c.clienteId == $scope.novoRegistro.cliente.id)) {
            $scope.novoRegistro.cliente = "";
            return
        };

        $scope.novoRegistro.usuarioClientes.push({
            id: 0,
            nome: $scope.novoRegistro.cliente.nome,
            clienteId: $scope.novoRegistro.cliente.id
        });

        $scope.novoRegistro.cliente = "";
    };

    $scope.onRemoverCliente = (cliente) => {
        if (cliente.id > 0) {
            cliente.deleted = true;
        } else {
            $scope.novoRegistro.usuarioClientes.splice($scope.novoRegistro.usuarioClientes.indexOf(cliente), 1);
        }
    }

    // $scope.onReenviarEmail = () => {
    //     UsuarioService.resendEmailResetPassword($scope.novoRegistro.id, $scope.novoRegistro.email).then(function () {
    //         swal({
    //             title: $translate.instant('PRONTO') + "!",
    //             text: $translate.instant('E-mail enviado'),
    //             type: "success",
    //             timer: 2000
    //         });
    //         $scope.modalNovoRegistro.close();
    //         $scope.onInit();
    //     });
    // }

    $scope.gerarAcesso = function (registro, modulo) {
        var config = {
            'SAEGA': {
                service: ClienteService.gerarAcessoSaega,
                baseUrl: 'https://app.saega.com.br/create-access/'
            }
        };

        var moduleConfig = config[modulo.toUpperCase()];
        if (!moduleConfig) return;

        moduleConfig.service(registro.id).then(function (response) {

            var token = response.data.token;
            var expiresAt = response.data.expiresAt;

            $scope.modalLink = $uibModal.open({
                animation: true,
                templateUrl: 'views/megazap/clientes/modal-link-acesso.html?t=' + new Date(),
                scope: $scope,
                size: 'md'
            });

            $scope.linkGerado = moduleConfig.baseUrl + token;
            $scope.expiracao = expiresAt;
            $scope.fechar = function () {
                $scope.modalLink.dismiss('cancel');
            };

            $scope.copiarTexto = function () {
                navigator.clipboard.writeText($scope.linkGerado)
                    .then(function () {
                        swal({
                            title: $translate.instant('SUCESSO'),
                            text: "Link copiado para a área de transferência!",
                            type: "success",
                            confirmButtonText: "OK"
                        });
                    })
                    .catch(function () {
                        swal({
                            title: $translate.instant('ATENCAO'),
                            text: "Não foi possível copiar o link automaticamente.",
                            type: "warning",
                            confirmButtonText: "OK"
                        });
                    });
            };

        }).catch(function (error) {
            var mensagem = "Erro ao gerar acesso.";

            if (error.data && error.data.message) {
                var match = error.data.message.match(/\{.*\}/);

                if (match) {
                    var jsonInterno = JSON.parse(match[0]);
                    mensagem = jsonInterno.message || mensagem;
                } else {
                    mensagem = error.data.message;
                }
            }

            swal({
                title: $translate.instant('ATENCAO'),
                text: mensagem,
                type: "warning",
                confirmButtonColor: "#DD6B55",
                confirmButtonText: $translate.instant('OK')
            });
        });
    };

});
