materialAdmin.service('AtendenteService', function ($http, $setting, $localStorage) {

    var baseUrl = $setting.automationApi + '/atendentes/ate.php';

    function obterEmpresaId() {
        var empresaId = '';

        try {
            empresaId = $localStorage.empresaId ||
                ($localStorage.empresa && (
                    $localStorage.empresa.empresaId ||
                    $localStorage.empresa.id
                )) ||
                '';
        } catch (e) {
            empresaId = '';
        }

        if (!empresaId) {
            try {
                var empresa = JSON.parse(
                    localStorage.getItem('empresa') || 'null'
                );

                empresaId = empresa
                    ? (empresa.empresaId || empresa.id || '')
                    : '';
            } catch (e) {
                empresaId = '';
            }
        }

        if (!empresaId) {
            empresaId = localStorage.getItem('empresaId') || '';
        }

        if (!empresaId) {
            var match = document.cookie.match(
                /(?:^|;\s*)empresaId=([^;]*)/
            );

            if (match) {
                try {
                    empresaId = decodeURIComponent(match[1]);
                } catch (e) {
                    empresaId = match[1];
                }
            }
        }

        return String(empresaId || '').trim();
    }

    function configurarDados(data) {
        var dados = angular.copy(data || {});
        var empresaId = obterEmpresaId();

        if (empresaId) {
            dados.empresa = empresaId;
            dados.empresaId = empresaId;
        }

        dados.perfil = 'ATENDENTE';
        dados.usuarioPerfil = 'ATENDENTE';
        dados.scope = 'ATENDENTE';

        return dados;
    }

    function obterId(data) {
        return String(
            typeof data === 'object' && data !== null
                ? (data.id || '')
                : (data || '')
        ).trim();
    }

    function validarId(id) {
        if (!id) {
            return Promise.reject(
                new Error('ID do atendente não informado.')
            );
        }

        return null;
    }

    var config = {
        withCredentials: true
    };

    // GET /atendentes?empresaId=N3BOT
    this.getTodos = function (filter) {
        return $http.get(baseUrl, angular.extend({}, config, {
            params: angular.extend({}, filter || {}, {
                empresaId: obterEmpresaId(),
                withCredentials: true
            })
        }));
    };

    // GET /atendentes/81?empresaId=N3BOT
    this.get = function (id) {
        id = obterId(id);

        return $http.get(
            baseUrl + '/' + encodeURIComponent(id),
            angular.extend({}, config, {
                params: {
                    empresaId: obterEmpresaId(),
                    withCredentials: true
                }
            })
        );
    };

    // GET /atendentes/simples
    this.getSimples = function () {
        return $http.get(baseUrl + '/simples', config);
        withCredentials: true
    };

    // GET /atendentes/simples/all
    this.getSimplesAll = function () {
        return $http.get(baseUrl + '/simples/all', config);
    };

    // PUT /atendentes: criar
    this.inserir = function (data) {
        return $http.put(baseUrl, configurarDados(data), config);
        withCredentials: true
    };

    // PUT /atendentes/81: atualizar
    this.atualizar = function (data) {
        var id = obterId(data);
        var erro = validarId(id);

        if (erro) {
            return erro;
        }

        return $http.put(
            baseUrl + '/' + encodeURIComponent(id),
            configurarDados(data),
            config
        );
        withCredentials: true
    };

    // PUT /atendentes/81: ativar, desativar ou alterar status
    this.atualizarStatus = function (data) {
        var id = obterId(data);
        var erro = validarId(id);

        if (erro) {
            return erro;
        }

        return $http.put(
            baseUrl + '/' + encodeURIComponent(id),
            configurarDados(data),
            config
        );
        withCredentials: true
    };

    // DELETE /atendentes/81?empresaId=N3BOT
    this.remover = function (data) {
        var id = obterId(data);
        var erro = validarId(id);

        if (erro) {
            return erro;
        }

        return $http.delete(
            baseUrl + '/' + encodeURIComponent(id),
            angular.extend({}, config, {
                params: {
                    empresaId: obterEmpresaId()
                }
            })
        );
        withCredentials: true
    };

    // Mensagens rápidas
    this.recuperarMensagensRapidas = function () {
        return $http.get(baseUrl + '/mensagens-rapidas', config);
        withCredentials: true
    };

    this.inserirMensagemRapida = function (data) {
        return $http.put(
            baseUrl + '/mensagens-rapidas',
            configurarDados(data),
            config
        );
        withCredentials: true
    };

    this.atualizarMensagemRapida = function (data) {
        return $http.put(
            baseUrl + '/mensagens-rapidas',
            configurarDados(data),
            config
        );
    };

    this.excluirMensagemRapida = function (id) {
        return $http.delete(
            baseUrl + '/mensagens-rapidas',
            angular.extend({}, config, {
                params: { id: id }
            })
        );
    };

    // PUT /atendentes/81
    this.atualizarOffline = function (id) {
        id = obterId(id);

        var erro = validarId(id);

        if (erro) {
            return erro;
        }

        return $http.put(
            baseUrl + '/' + encodeURIComponent(id),
            configurarDados({
                id: id,
                online: false
            }),
            config
        );
        withCredentials: true
    };

    // PUT /atendentes/offline
    this.atualizarTodosOffline = function () {
        return $http.put(
            baseUrl + '/offline',
            configurarDados({
                todosOffline: true
            }),
            config
        );
        withCredentials: true
    };

    // GET /atendentes/pendencias?id=81&empresaId=N3BOT
    this.getPendencias = function (id) {
        return $http.get(
            baseUrl + '/pendencias',
            angular.extend({}, config, {
                params: {
                    id: id,
                    empresaId: obterEmpresaId(),
                    withCredentials: true
                }
            })
        );
    };
});




