materialAdmin.controller('EnqueteListaController', function ($scope, $translate, $state, $uibModal, EnqueteService, ClienteService) {

    $scope.listviewSearchStat = false;
    $scope.modalNovoRegistro;
    $scope.novoRegistro = {};
    $scope.telefones = [];

    $scope.lvSearch = function () {
        this.listviewSearchStat = true;
    };

    $scope.onInit = function () {
        EnqueteService.getTodos().then(function (response) {
            $scope.registros = listToMatrix(response.data, 2);
        });

        ClienteService.getTelefones().then(function (response) {
            $scope.telefones = response.data;
        });
    };

    $scope.onMostarModalNovoRegistro = function () {
        $scope.modalNovoRegistro = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/enquetes/modal-nova-enquete.html',
            scope: $scope
        });
    };

    $scope.onModalInserir = function () {
        EnqueteService.inserir($scope.novoRegistro).then(function (response) {
            $state.go("bots.enquete_edicao", {id: response.data.id});
        });
    };

    $scope.onModalCancelar = function () {
        $scope.modalNovoRegistro.close();
        $scope.novoRegistro = {};
    };

    $scope.onRemover = function (registro) {
        enqueteUtils.remover($translate, EnqueteService, registro, function () {
            $scope.onInit();
        });
    };

    $scope.onAtivar = function (registro) {
        var registroAlterado = {
            id: registro.id,
            numero: registro.numero,
            texto: registro.texto,
            ativa: true
        };

        enqueteUtils.alterarStatus($translate, EnqueteService, registroAlterado, function () {
            $scope.onInit();
        });
    };

    $scope.onInativar = function (registro) {
        var registroAlterado = {
            id: registro.id,
            numero: registro.numero,
            texto: registro.texto,
            ativa: false
        };

        enqueteUtils.alterarStatus($translate, EnqueteService, registroAlterado, function () {
            $scope.onInit();
        });
    };

    $scope.onMostarModalAssociarTelefone = function (registro) {
        $scope.registroSelecionado = registro;
        $scope.novoTelefone = {};

        $scope.modalTelefone = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/enquetes/modal-associar-telefone.html',
            scope: $scope
        });
    };

    $scope.onModalTelefoneInserir = function () {
        var data = {
            id: $scope.novoTelefone.id,
            grupoPerguntaId: $scope.registroSelecionado.id
        };

        EnqueteService.associarTelefone(data).then(function () {
            $scope.onModalTelefoneCancelar();
            $scope.onInit();
        });
    };

    $scope.onModalTelefoneCancelar = function () {
        $scope.modalTelefone.close();
        $scope.registroSelecionado = {};
        $scope.novoTelefone = {};
    };

});

materialAdmin.controller('EnqueteEdicaoController', function ($scope, $translate, $state, FileService, $stateParams, $uibModal, EnqueteService) {

    $scope.registro = {
        ativa: true
    };
    $scope.saveImage = false;

    $scope.onInit = function () {
        EnqueteService.get($stateParams.id).then(function (response) {
            $scope.registro = response.data;

            if ($scope.registro.opcoes === undefined) {
                $scope.registro.opcoes = [];
            }

            if ($scope.registro.imagem != undefined) {
                $("span.fileinput-new").hide();
                $("span.fileinput-exists").show();
                $("a.fileinput-exists").show();
            } else {
                $("span.fileinput-new").show();
                $("span.fileinput-exists").hide();
                $("a.fileinput-exists").hide();
            }

            updateComponentsAfterRequest();
        });

        angular.element("#imagem-input")
                .on('change.bs.fileinput',
                        function (event, data) {
                            $scope.atualizarImagemRegistro(data);
                        });

        angular.element("#imagem-input")
                .on('clear.bs.fileinput',
                        function (event) {
                            $scope.atualizarImagemRegistro(null);
                        });
    };

    $scope.atualizarImagemRegistro = function (imagem) {
        if (imagem !== null) {
            $scope.saveImage = true;
            
            $scope.imagemBase64 = imagem.result;
            $scope.imagemName = imagem.name;
            
            $scope.registro.fileId = 0;

            $("span.fileinput-new").hide();
            $("span.fileinput-exists").show();
            $("a.fileinput-exists").show();                        
        } else {
            $scope.saveImage = false;
            
            $scope.imagemBase64 = undefined;
            $scope.imagemName = undefined;
            
            $scope.registro.imagem = undefined;
            $scope.registro.fileId = 0;

            $("span.fileinput-new").show();
            $("span.fileinput-exists").hide();
            $("a.fileinput-exists").hide();
        }
    };

    $scope.onSalvar = function () {
        var save = function () {
            EnqueteService.atualizar($scope.registro).then(function () {
                swal({
                    title: $translate.instant('PRONTO') + "!",
                    text: $translate.instant('REGISTRO-ATUALIZADO'),
                    type: "success",
                    timer: 2000
                }, function () {
                    $state.go("bots.enquetes");
                });
            });
        };

        if ($scope.saveImage) {
            FileService.insertBase64($scope.imagemBase64, $scope.imagemName).then(function (response) {
                $scope.saveImage = false;
                
                $scope.registro.imagem = response.data.url;
                save();
            });
        } else {
            save();
        }
    };

    $scope.onRemover = function (registro) {
        enqueteUtils.remover($translate, EnqueteService, registro, function () {
            $state.go("bots.enquetes");
        });
    };

    $scope.onModalOpcao = function (registro) {
        $scope.opcaoOriginal = registro;
        $scope.opcaoSelecionada = {};

        if (registro !== undefined) {
            $scope.opcaoSelecionada.edicao = true;
            $scope.opcaoSelecionada.id = registro.id;
            $scope.opcaoSelecionada.numero = registro.numero;
            $scope.opcaoSelecionada.texto = registro.texto;
        }

        $scope.modalOpcao = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/enquetes/modal-opcao.html',
            scope: $scope
        });
    };

    $scope.onModalSalvarOpcao = function () {
        if ($scope.opcaoSelecionada.edicao) {
            $scope.opcaoOriginal.numero = $scope.opcaoSelecionada.numero;
            $scope.opcaoOriginal.texto = $scope.opcaoSelecionada.texto;
        } else {
            $scope.registro.opcoes.push($scope.opcaoSelecionada);
        }

        $scope.onModalCancelar();
    };

    $scope.onModalCancelar = function () {
        $scope.opcaoSelecionada = {};
        $scope.opcaoOriginal = {};
        $scope.modalOpcao.close();
    };

    $scope.onRemoverOpcao = function (registro) {
        registro.excluido = true;
    };

});
;

materialAdmin.service('EnqueteService', function ($http, $setting) {

    this.getTodos = function () {
        var request = $http({
            method: "get",
            url: $setting.api + "/enquetes",
            isArray: true
        });

        return (request);
    };

    this.get = function (id) {
        var request = $http({
            method: "get",
            url: $setting.api + "/enquetes/" + id
        });

        return (request);
    };

    this.inserir = function (data) {
        var request = $http({
            method: "put",
            url: $setting.api + "/enquetes",
            data: data
        });

        return (request);
    };

    this.atualizar = function (data) {
        var request = $http({
            method: "post",
            url: $setting.api + "/enquetes/" + data.id,
            data: data
        });

        return (request);
    };

    this.atualizarStatus = function (data) {
        var request = $http({
            method: "post",
            url: $setting.api + "/enquetes/" + data.id + "/status",
            data: data
        });

        return (request);
    };

    this.remover = function (id) {
        var request = $http({
            method: "delete",
            url: $setting.api + "/enquetes/" + id
        });

        return (request);
    };

});;

materialAdmin.controller('HorariosAtendimentoController', function ($scope, $translate, $state, $uibModal, AtendenteService, DepartamentoService, ClienteService) {

    $scope.configuracoes = {};
    $scope.configuracoes.horariosAtendimento = [];

    $scope.lvSearch = function () {
        this.listviewSearchStat = true;
    };

    $scope.onInit = function () {
        $scope.getConfiguracoes();
    };

    $scope.getConfiguracoes = function () {
        ClienteService.getConfiguracoesAtendentes().then(function (response) {
            $scope.configuracoes = response.data;
            console.log($scope.configuracoes);
            if($scope.configuracoes.diasAtendimento && $scope.configuracoes.diasAtendimento.length > 0){
                $scope.configuracoes.diasAtendimento.forEach(da => {
                    if(da.horarios && da.horarios.length > 0){
                        da.horarios.forEach(h => {
                            h.acao = "ATUALIZAR"
                        })
                    }
                })
            }
            updateComponentsAfterRequest();
        });
    };

    $scope.adicionarHorario = function (horarioAtendimento) {
        if (!horarioAtendimento.horarios) {
            horarioAtendimento.horarios = [];
        }

        horarioAtendimento.horarios.push({
            acao: 'INSERIR'
        });
    };

    $scope.excluirHorario = function (horario) {
        horario.acao = 'EXCLUIR';
    };

    $scope.onSalvar = function () {
        ClienteService.updateConfiguracoesAtendentes($scope.configuracoes).then(function () {
            $scope.getConfiguracoes();
        });
    };

});
;

materialAdmin.service("BancoArquivoService", function ($http, $setting) {
    var baseUrl = $setting.api + "/banco-arquivo";

    function request(method, url, data, params) {
        return $http({
            method: method,
            url: url,
            data: data,
            params: params,
            withCredentials: true,
            headers: {
                "Content-Type": "application/json"
            }
        });
    }

    this.getAll = function (data) {
        return request("GET", baseUrl, null, data);
    };

    this.getFolders = function (data) {
        return request("GET", baseUrl + "/folders", null, data);
    };

    this.insert = function (data) {
        return request("POST", baseUrl, data);
    };

    this.put = function (data) {
        return request("PUT", baseUrl + "/" + encodeURIComponent(data.id), data);
    };

    this.delete = function (id) {
        return request("DELETE", baseUrl + "/" + encodeURIComponent(id));
    };

    this.deleteSelecionados = function (ids) {
        return request(
            "DELETE",
            baseUrl + "/selecionados/" +
                (Array.isArray(ids) ? ids : [ids]).map(encodeURIComponent).join(",")
        );
    };

    this.moverSelecionados = function (ids, folderId) {
        return request(
            "PUT",
            baseUrl + "/moveTo/" +
                (Array.isArray(ids) ? ids : [ids]).map(encodeURIComponent).join(",") +
                "/" + encodeURIComponent(folderId)
        );
    };

    this.findById = function (id) {
        return request("GET", baseUrl + "/" + encodeURIComponent(id));
    };
});




function getUrlParameter(name) {
    var params = new URLSearchParams(window.location.search);
    return params.get(name);
}


(function() {

'use strict';

// Alias the loading bar for various backwards compatibilities since the project has matured:
angular.module('angular-loading-bar', ['cfp.loadingBarInterceptor']);
angular.module('chieffancypants.loadingBar', ['cfp.loadingBarInterceptor']);


/**
 * loadingBarInterceptor service
 *
 * Registers itself as an Angular interceptor and listens for XHR requests.
 */
angular.module('cfp.loadingBarInterceptor', ['cfp.loadingBar'])
  .config(['$httpProvider', function ($httpProvider) {
          
    var interceptor = ['$q', '$cacheFactory', '$timeout', '$rootScope', '$log', 'cfpLoadingBar', function ($q, $cacheFactory, $timeout, $rootScope, $log, cfpLoadingBar) {

      /**
       * The total number of requests made
       */
      var reqsTotal = 0;

      /**
       * The number of requests completed (either successfully or not)
       */
      var reqsCompleted = 0;

      /**
       * The amount of time spent fetching before showing the loading bar
       */
      var latencyThreshold = cfpLoadingBar.latencyThreshold;

      /**
       * $timeout handle for latencyThreshold
       */
      var startTimeout;


      /**
       * calls cfpLoadingBar.complete() which removes the
       * loading bar from the DOM.
       */
      function setComplete() {
        $timeout.cancel(startTimeout);
        cfpLoadingBar.complete();
        reqsCompleted = 0;
        reqsTotal = 0;
      }

      /**
       * Determine if the response has already been cached
       * @param  {Object}  config the config option from the request
       * @return {Boolean} retrns true if cached, otherwise false
       */
      function isCached(config) {
        var cache;
        var defaultCache = $cacheFactory.get('$http');
        var defaults = $httpProvider.defaults;

        // Choose the proper cache source. Borrowed from angular: $http service
        if ((config.cache || defaults.cache) && config.cache !== false &&
          (config.method === 'GET' || config.method === 'JSONP')) {
            cache = angular.isObject(config.cache) ? config.cache
              : angular.isObject(defaults.cache) ? defaults.cache
              : defaultCache;
        }

        var cached = cache !== undefined ?
          cache.get(config.url) !== undefined : false;

        if (config.cached !== undefined && cached !== config.cached) {
          return config.cached;
        }
        config.cached = cached;
        return cached;
      }


      return {
        'request': function(config) {
            
          // Check to make sure this request hasn't already been cached and that
          // the requester didn't explicitly ask us to ignore this request:
          if (!config.ignoreLoadingBar && !isCached(config)) {
            $rootScope.$broadcast('cfpLoadingBar:loading', {url: config.url});
            if (reqsTotal === 0) {
              startTimeout = $timeout(function() {
                cfpLoadingBar.start();
              }, latencyThreshold);
            }
            reqsTotal++;
            cfpLoadingBar.set(reqsCompleted / reqsTotal);
          }
          return config;
        },

        'response': function(response) {
          if (!response || !response.config) {
            $log.error('Broken interceptor detected: Config object not supplied in response:\n https://github.com/chieffancypants/angular-loading-bar/pull/50');
            return response;
          }

          if (!response.config.ignoreLoadingBar && !isCached(response.config)) {
            reqsCompleted++;
            $rootScope.$broadcast('cfpLoadingBar:loaded', {url: response.config.url, result: response});
            if (reqsCompleted >= reqsTotal) {
              setComplete();
            } else {
              cfpLoadingBar.set(reqsCompleted / reqsTotal);
            }
          }
          return response;
        },

        'responseError': function(rejection) {
          if (!rejection || !rejection.config) {
            $log.error('Broken interceptor detected: Config object not supplied in rejection:\n https://github.com/chieffancypants/angular-loading-bar/pull/50');
            return $q.reject(rejection);
          }

          if (!rejection.config.ignoreLoadingBar && !isCached(rejection.config)) {
            reqsCompleted++;
            $rootScope.$broadcast('cfpLoadingBar:loaded', {url: rejection.config.url, result: rejection});
            if (reqsCompleted >= reqsTotal) {
              setComplete();
            } else {
              cfpLoadingBar.set(reqsCompleted / reqsTotal);
            }
          }
          return $q.reject(rejection);
        }
      };
    }];

    $httpProvider.interceptors.push(interceptor);
  }]);


/**
 * Loading Bar
 *
 * This service handles adding and removing the actual element in the DOM.
 * Generally, best practices for DOM manipulation is to take place in a
 * directive, but because the element itself is injected in the DOM only upon
 * XHR requests, and it's likely needed on every view, the best option is to
 * use a service.
 */
angular.module('cfp.loadingBar', [])
  .provider('cfpLoadingBar', function() {

    this.autoIncrement = true;
    this.includeSpinner = true;
    this.includeBar = true;
    this.latencyThreshold = 100;
    this.startSize = 0.02;
    this.parentSelector = 'body';
    this.spinnerTemplate = '<div id="loading-bar-spinner"><div class="spinner-icon"></div></div>';
    this.loadingBarTemplate = '<div id="loading-bar"><div class="bar"><div class="peg"></div></div></div>';

    this.$get = ['$injector', '$document', '$timeout', '$rootScope', function ($injector, $document, $timeout, $rootScope) {
      var $animate;
      var $parentSelector = this.parentSelector,
        loadingBarContainer = angular.element(this.loadingBarTemplate),
        loadingBar = loadingBarContainer.find('div').eq(0),
        spinner = angular.element(this.spinnerTemplate);

      var incTimeout,
        completeTimeout,
        started = false,
        status = 0;

      var autoIncrement = this.autoIncrement;
      var includeSpinner = this.includeSpinner;
      var includeBar = this.includeBar;
      var startSize = this.startSize;

      /**
       * Inserts the loading bar element into the dom, and sets it to 2%
       */
      function _start() {
        if (!$animate) {
          $animate = $injector.get('$animate');
        }

        var $parent = $document.find($parentSelector).eq(0);
        $timeout.cancel(completeTimeout);

        // do not continually broadcast the started event:
        if (started) {
          return;
        }

        $rootScope.$broadcast('cfpLoadingBar:started');
        started = true;

        if (includeBar) {
          $animate.enter(loadingBarContainer, $parent, angular.element($parent[0].lastChild));
        }

        if (includeSpinner) {
          $animate.enter(spinner, $parent, angular.element($parent[0].lastChild));
        }

        _set(startSize);
      }

      /**
       * Set the loading bar's width to a certain percent.
       *
       * @param n any value between 0 and 1
       */
      function _set(n) {
        if (!started) {
          return;
        }
        var pct = (n * 100) + '%';
        loadingBar.css('width', pct);
        status = n;

        // increment loadingbar to give the illusion that there is always
        // progress but make sure to cancel the previous timeouts so we don't
        // have multiple incs running at the same time.
        if (autoIncrement) {
          $timeout.cancel(incTimeout);
          incTimeout = $timeout(function() {
            _inc();
          }, 250);
        }
      }

      /**
       * Increments the loading bar by a random amount
       * but slows down as it progresses
       */
      function _inc() {
        if (_status() >= 1) {
          return;
        }

        var rnd = 0;

        // TODO: do this mathmatically instead of through conditions

        var stat = _status();
        if (stat >= 0 && stat < 0.25) {
          // Start out between 3 - 6% increments
          rnd = (Math.random() * (5 - 3 + 1) + 3) / 100;
        } else if (stat >= 0.25 && stat < 0.65) {
          // increment between 0 - 3%
          rnd = (Math.random() * 3) / 100;
        } else if (stat >= 0.65 && stat < 0.9) {
          // increment between 0 - 2%
          rnd = (Math.random() * 2) / 100;
        } else if (stat >= 0.9 && stat < 0.99) {
          // finally, increment it .5 %
          rnd = 0.005;
        } else {
          // after 99%, don't increment:
          rnd = 0;
        }

        var pct = _status() + rnd;
        _set(pct);
      }

      function _status() {
        return status;
      }

      function _completeAnimation() {
        status = 0;
        started = false;
      }

      function _complete() {
        if (!$animate) {
          $animate = $injector.get('$animate');
        }

        $rootScope.$broadcast('cfpLoadingBar:completed');
        _set(1);

        $timeout.cancel(completeTimeout);

        // Attempt to aggregate any start/complete calls within 500ms:
        completeTimeout = $timeout(function() {
          var promise = $animate.leave(loadingBarContainer, _completeAnimation);
          if (promise && promise.then) {
            promise.then(_completeAnimation);
          }
          $animate.leave(spinner);
        }, 500);
      }

      return {
        start            : _start,
        set              : _set,
        status           : _status,
        inc              : _inc,
        complete         : _complete,
        autoIncrement    : this.autoIncrement,
        includeSpinner   : this.includeSpinner,
        latencyThreshold : this.latencyThreshold,
        parentSelector   : this.parentSelector,
        startSize        : this.startSize
      };


    }];     //
  });       // wtf javascript. srsly
})();       //
;

materialAdmin.controller("BancoArquivoController",  function (
    $scope,
    $uibModal,
    $translate,
    $window,
    AtendenteService,
    DepartamentoService,
    BancoArquivoService,
    FileService,
    $localStorage
  ) {
    
    $scope.arquivos = [];
    $scope.loadingFiles = false;
    $scope.novo ={
        filtroDepartamento:""
    }
    $scope.departamentosFiltragem = [{ id: 0, nome: "Todos" }];
    $scope.filtro = {
        departamentoId: 0,
        nome:"",
        origem:"TODOS",
        offset:0
    }    
    $scope.selecionadoParaMover = null;

    $scope.breadcrumb = [];

    $scope.registro = {departamentos:[]};
    $scope.pastas=[];
    $scope.pastasBreadcrumb=[];

    $scope.compartilhamento = {
        departamentoId: "0"
    }
    $scope.showMore = false;
    $scope.onInit = () => {
        $scope.origensFiltro = [
            {key:'TODOS', value: $translate.instant("TODOS")},
            {key:'PESSOAL', value: $translate.instant("MEUS")},
            {key:'COMPARTILHADO', value: $translate.instant("COMPARTILHADOS")}
        ]
      $scope.carregarDepartamentos();
      $scope.getAll(false);
    };
    $scope.modoExibicao = "GRADE";
    if($localStorage.bancoArquivoModo){
        $scope.modoExibicao = $localStorage.bancoArquivoModo;
    }

    $scope.clickBreadCrumb= (idxPasta)=>{
        if(idxPasta === -1){
            $scope.breadcrumb = [];
        }else{
            $scope.breadcrumb = $scope.breadcrumb.filter((i,idx)=>idx <= idxPasta);
        }

        $scope.getAll(false);
    }

    $scope.clickBreadCrumbModal= (idxPasta)=>{
        if(idxPasta === -1){
            $scope.pastasBreadcrumb = [];
        }else  if(idxPasta === -2){
            $scope.pastasBreadcrumb.pop();
        }else{
            $scope.pastasBreadcrumb = $scope.pastasBreadcrumb.filter((i,idx)=>idx <= idxPasta);
        }

        $scope.getFolders();
    }

    $scope.getFolders = function () {
        $scope.loading = true;

        let filtro = {};

        let pastaAtual = $scope.getIdPastaAtualModal();
        if(pastaAtual !== null){
            filtro.folderId = pastaAtual;
        }

        BancoArquivoService.getFolders(filtro).then(function (response) {
            $scope.pastas = response.data;
            $scope.loading = false;
            updateComponentsAfterRequest();
        });

    };

    $scope.getAll = function (pagination) {
        $scope.loading = true;
        if (pagination) {
            $scope.filtro.offset += 20;
        } else {
            $scope.registros = [];
            $scope.filtro.offset = 0;
            $scope.showMore = false;
        }
        $scope.loading = true;
        let filtro = Object.assign($scope.filtro, {});

        let pastaAtual = $scope.getIdPastaAtual();
        if(pastaAtual !== null){
            filtro.folderId = pastaAtual;
        }else{
            delete filtro.folderId;
        }
        BancoArquivoService.getAll($scope.filtro).then(function (response) {
            if(!pagination) $scope.registros = [];
            $scope.registros = $scope.registros.concat(response.data);
            $scope.showMore = response.data.length >= 20;
            $scope.loading = false;
            updateComponentsAfterRequest();
        });

    };

    $scope.limparArquivos = () =>{
        $scope.arquivos = [];
        let fileInput = document.getElementById('fileInputBancoArquivo');
        if (fileInput) fileInput.value = null;
        $scope.registro = {departamentos:[]};
        $scope.compartilhamento.departamentoId = "0";
    }
    $scope.onClickNovoArquivo = () =>{
        
        let fileInput = document.getElementById("fileInputBancoArquivo");
        if (fileInput) {
            fileInput.removeEventListener('change', $scope.insertFile);
            fileInput.addEventListener('change', $scope.insertFile);
            fileInput.click();
        }
    }
    $scope.onCriarNovaPasta=()=>{
        let pasta = {
            fileName:$scope.registro.fileName,
            type:"FOLDER"
        }
        
        let pastaAtual = $scope.getIdPastaAtual();
        if(pastaAtual !== null){
            pasta.folderId = pastaAtual;
        }

        BancoArquivoService.insert([pasta]).then(function (response) {
            $scope.getAll(false);
            $scope.onCancelarNovaPasta();                 
        });
    }

    $scope.insertFile=()=> {
        $scope.loadingFiles = true;
        let fileInput = document.getElementById("fileInputBancoArquivo");
        let files = fileInput.files;
       
        for (const f of files) {
            $scope.readFile(f);
        }
        setTimeout(()=>{
            $scope.loadingFiles = false;
            $scope.$apply();
        }, 300);
    };

    $scope.readFile = (file) => {
        let reader = new FileReader();

        reader.readAsDataURL(file);
        reader.onload = function () {
            var limite = 50000000;

            if ($scope.arquivos.length >= 15) {
                return swal("Ops!", "Só é possível enviar até 15 arquivos por vez.", "error");
            }

            if (file.size > limite) {
                return swal("Ops!", "Envie um anexo com no máximo " + (limite / 1000000) + "mb.", "error");
            }
            let _type = "";

            if (file.type.startsWith("video")) {
                _type = 'VIDEO';
            } else if (file.type.startsWith("audio")) {
                _type = 'AUDIO';
            } else if (file.type.match("image")) {
                _type = 'IMAGEM';
            } else if (file.type.match("pdf")) {
                _type = 'PDF';
            } else {
                _type = 'ARQUIVO';
            }
            $scope.arquivos.push({ url: reader.result, type: _type, name: file.name  });

            $scope.$apply();
        };
    }

    $scope.departamentosSelecionadosTotal = () => {
        return $scope.departamentos.filter(i => i.selected === true).length;
    }

    $scope.filterDepartamento = function (departamento) {
        if ($scope.novo.filtroDepartamento === "") {
            return true;
        } else {
            return departamento.nome.toUpperCase().includes($scope.novo.filtroDepartamento.toUpperCase());
        }
    };

    
    $scope.onVisualizarImagem = function (imagem) {
        $scope.imagemSelecionada = imagem;

        $scope.modalAnexo = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/atendimentos/modal-imagem.html',
            size: 'lg',
            scope: $scope
        });
    };
    $scope.onMostrarModalPDF = function () {
        $scope.modalAnexo = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/atendimentos/modal-pdf.html',
            scope: $scope
        });
    };


    $scope.getIdPastaAtual = () =>{
        if($scope.breadcrumb.length > 0){
            return $scope.breadcrumb[$scope.breadcrumb.length-1].id;
        }else{
            return null;
        }
    }
    $scope.getPastaAtual = () =>{
        if($scope.breadcrumb.length > 0){
            return $scope.breadcrumb[$scope.breadcrumb.length-1];
        }else{
            return null;
        }
    }
    
    $scope.getIdPastaAtualModal = () =>{
        if($scope.pastasBreadcrumb.length > 0){
            return $scope.pastasBreadcrumb[$scope.pastasBreadcrumb.length-1].id;
        }else{
            return -1;
        }
    }
    $scope.getPastaAtualModal = () =>{
        if($scope.pastasBreadcrumb.length > 0){
            return $scope.pastasBreadcrumb[$scope.pastasBreadcrumb.length-1];
        }else{
            return null;
        }
    }


    $scope.isPastaAtualCompartilhada = () =>{
        if($scope.breadcrumb.length > 0){
            return $scope.breadcrumb[$scope.breadcrumb.length-1].compartilhado;
        }else{
            return false;
        }
    }

    $scope.inserirOuAtualizarArquivo = () => {
        $scope.uploadingFiles = true;

        if($scope.registro.id){
            BancoArquivoService.put($scope.registro).then(function (response) {
                $scope.onModalNovoArquivoClose();
                $scope.getAll(false);
            });
        }else{
            if($scope.arquivos && $scope.arquivos.length > 0){
                let arquivos = []
                new Promise((resolve, reject)=>{
                    let r = $scope.arquivos.length;

                    $scope.arquivos.forEach((a, i) => {
                        FileService.insertBase64(a.url, a.name).then(f => {
                            //let departamentosSelecionados = $scope.departamentos.filter(i => i.selected === true).map(i => { return { id: i.id } });
                            let data = {
                                fileUrl: f.data.url,
                                fileName: a.name,
                                type: a.type,
                                departamentos:$scope.registro.departamentos
                            }
                            let pastaAtual = $scope.getIdPastaAtual();
                            if(pastaAtual !== null){
                                data.folderId = pastaAtual;
                            }
                            arquivos.push(data);

                            if(--r == 0){
                                resolve(arquivos)
                            }
                        })
                    })
                }).then(arquivos=>{
                    BancoArquivoService.insert(arquivos).then(function (response) {
                        $scope.getAll(false);
                        $scope.onModalNovoArquivoClose();                        
                    });
                })
            }
        }
    }

    $scope.carregarDepartamentos = () =>{
        DepartamentoService.getAtivos().then((response) => {
            $scope.departamentos = response.data;
            $scope.departamentosFiltragem = $scope.departamentosFiltragem.concat(response.data);
            updateComponentsAfterRequest();
        });
    }

    $scope.onMostrarModalNovoArquivo = () => {
        $scope.limparArquivos();
    
        $scope.modalNovoArquivo = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/banco_arquivos/modal-novo-arquivo.html',
            scope: $scope,
            size:"lg"
        });       
    }

    $scope.onMostrarModalCompartilhamento= () => {
        $scope.modalNovoArquivo = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/banco_arquivos/modal-novo-arquivo.html',
            scope: $scope,
        });
    }

    $scope.onMostrarModalMoverPara = (registro) => {
        if(registro){
            for(let i = 0; i < $scope.registros.length; i++){
                if($scope.registros[i].id === registro.id){
                    $scope.registros[i].selecionado = true;
                }else{
                    delete $scope.registros[i].selecionado;
                }
            }
        }
        $scope.getFolders();
        $scope.modalMoverArquivo = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/banco_arquivos/modal-mover-arquivo.html',
            scope: $scope,
        });
    }

    $scope.onModalAnexoCancelar = function () {
        $scope.modalAnexo.close();
    };

    $scope.onModalNovoArquivoClose = () => {
        if($scope.modalNovoArquivo){
            $scope.modalNovoArquivo.close();
            $scope.limparArquivos();
        }
    };

    $scope.onModalMoverArquivoCancelar = () => {
        if($scope.modalMoverArquivo){
            $scope.modalMoverArquivo.close();
        }
    };

    $scope.onModalNovoArquivoInserir = () => {
        if(!$scope.mostrarTabelaDepartamentos() && $scope.isGestor()){
            swal(
                {
                    title: $translate.instant("ATENCAO"),
                    text: `Tem certeza que deseja inserir esse(s) arquivo(s) para todos os departamentos?`,
                    type: "warning",
                    showCancelButton: true,
                    confirmButtonColor: "#DD6B55",
                    confirmButtonText: $translate.instant("SIM"),
                    cancelButtonText: $translate.instant("CANCELAR"),
                    closeOnConfirm: true,
                    closeOnCancel: true,
                },
                function (isConfirm) {
                    if (isConfirm) {
                        $scope.inserirOuAtualizarArquivo();
                    }
    
                }
            );
        }else{
            $scope.inserirOuAtualizarArquivo();
        }        
    }

    $scope.onEditar = (registro)=>{
        BancoArquivoService.findById(registro.id).then((response) => {
            $scope.registro = response.data;
            $scope.onMostrarModalCompartilhamento();
        });
    }
    $scope.getBackgroundImageUrl = (registro)=>{
        switch (registro.type){
            case "IMAGEM":
                if(registro.fileUrl){
                    return "url('"+registro.fileUrl+"')";
                }else{
                    return "url('"+registro.url+"')";
                }
                
            default:
                return "none";
        }
    }

    $scope.onClickFileName = (registro)=>{
        switch (registro.type){
            case "PDF":
                $scope.onVisualizarPDF(registro.fileUrl);
                break;
            case "IMAGEM":
                $scope.onVisualizarImagem(registro.fileUrl);
                break;
            case "FOLDER":
                $scope.onEntrarPasta(registro);
                break;
            default:
                window.open(registro.fileUrl, '_blank').focus();            
        }
    }
    $scope.onVisualizarPDF = function (url) {
        $window.open(url, "_blank", "location=no,enableviewportscale=yes");
    };

    $scope.abrirModalNovaPasta = () =>{
        if(!$scope.modalNovaPasta ){           
            $scope.modalNovaPasta = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/banco_arquivos/modal-nova-pasta.html',
                size: 'sm',
                scope: $scope
            })
        };
    }

    $scope.onCancelarNovaPasta = () =>{
        if($scope.modalNovaPasta){
            $scope.modalNovaPasta.close();
            $scope.limparArquivos();
            delete $scope.modalNovaPasta;
        }
    }

    $scope.onEntrarPasta = (registro) =>{
        $scope.breadcrumb.push(registro);   
        $scope.getAll(false);     
    }

    $scope.onEntrarPastaModalMover = (registro) =>{
        $scope.pastasBreadcrumb.push(registro);   
        $scope.getFolders();     
    }

    $scope.onDelete = (registro) => {
        swal(
            {
                title: $translate.instant("ATENCAO"),
                text: `Tem certeza que deseja deletar o arquivo '${registro.fileName}'?`,
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: $translate.instant("SIM"),
                cancelButtonText: $translate.instant("CANCELAR"),
                closeOnConfirm: false,
                closeOnCancel: true,
            },
            function (isConfirm) {
                if (isConfirm) {
                    BancoArquivoService.delete(registro.id).then((response) => {
                        swal("Sucesso", "Arquivo deletado com sucesso!", "success");
                        $scope.getAll(false);
                    });
                }

            }
        );
    }
    

    $scope.disabledDeleteSelecionados = () =>{        
        let qtde = $scope.registros.filter(i=> i.hasOwnProperty("selecionado") && i.selecionado === true);
        if(qtde && qtde.length > 0){
            return false;
        }else{
            return true;
        }
    }

    $scope.onMoverSelecionados = () =>{
        let qtde = $scope.registros.filter(i=> i.hasOwnProperty("selecionado") && i.selecionado === true);
       
        if(qtde && qtde.length > 0){
            swal(
                {
                    title: $translate.instant("ATENCAO"),
                    text: `Tem certeza que deseja mover ${qtde.length} arquivo(s)?`,
                    type: "warning",
                    showCancelButton: true,
                    confirmButtonColor: "#DD6B55",
                    confirmButtonText: $translate.instant("SIM"),
                    cancelButtonText: $translate.instant("CANCELAR"),
                    closeOnConfirm: false,
                    closeOnCancel: true,
                },
                function (isConfirm) {
                    if (isConfirm) {
                        let pastaAtual = $scope.getIdPastaAtualModal();
                        BancoArquivoService.moverSelecionados(qtde.map(i=>i.id).join(","), pastaAtual).then((response) => {
                            swal("Sucesso", "Arquivo(s) movidos(s) com sucesso!", "success");
                            $scope.getAll(false);
                            $scope.onModalMoverArquivoCancelar();
                        });
                    }
    
                }
            );
        }
        
    }
    $scope.onDeleteSelecionados = () =>{
        let qtde = $scope.registros.filter(i=> i.hasOwnProperty("selecionado") && i.selecionado === true);
        if(qtde && qtde.length > 0){
            swal(
                {
                    title: $translate.instant("ATENCAO"),
                    text: `Tem certeza que deseja deletar ${qtde.length} arquivo(s)?`,
                    type: "warning",
                    showCancelButton: true,
                    confirmButtonColor: "#DD6B55",
                    confirmButtonText: $translate.instant("SIM"),
                    cancelButtonText: $translate.instant("CANCELAR"),
                    closeOnConfirm: false,
                    closeOnCancel: true,
                },
                function (isConfirm) {
                    if (isConfirm) {
                        BancoArquivoService.deleteSelecionados(qtde.map(i=>i.id).join(",")).then((response) => {
                            swal("Sucesso", "Arquivo(s) deletado(s) com sucesso!", "success");
                            $scope.getAll(false);
                        });
                    }
    
                }
            );
        }
        
    }
   
    $scope.atualizarCompartilhamento = () =>{
        for(let i = 0 ; i < $scope.departamentosSelecionados.length ; i++){
            let find  = $scope.departamentos.find(e=> e.id == $scope.departamentosSelecionados[i].departamentoId);
            if(find){
                if(find.selected == false){
                    $scope.departamentosSelecionados[i].acao = 'DELETAR';
                }
            }
        }
        let idsSelecionados = $scope.departamentosSelecionados.map(i=>i.departamentoId);
        for(let i = 0 ; i < $scope.departamentos.length ; i++){
            if(!idsSelecionados.includes($scope.departamentos[i].id) && $scope.departamentos[i].selected == true){
                $scope.departamentosSelecionados.push({departamentoId:$scope.departamentos[i].id, acao: 'INSERIR'})
            }
        }


    }

    $scope.onAdicionarDepartamento = function () {
        var departamento = $scope.departamentos.find(function (departamento) {
            return departamento.id === parseInt($scope.compartilhamento.departamentoId, 10);
        });

        var departamentoCopy = angular.copy(departamento);
        departamentoCopy.acao = 'INSERIR';

        $scope.registro.departamentos.push(departamentoCopy);
    };

    $scope.departamentosNaoAdicionados = () =>{
        let departamentosFiltrados = [];
        if(Array.isArray($scope.registro.departamentos) && $scope.registro.departamentos.length > 0){
            let idsIncluidos = $scope.registro.departamentos.filter(item=>item.excluido !== true).map(item=>item.id);
            $scope.departamentos.forEach(item=>{
                if(!idsIncluidos.includes(item.id)){
                    departamentosFiltrados.push(item);
                }
            })
            return departamentosFiltrados;
        }else{
            return $scope.departamentos;
        }
    }
    $scope.onDeletarDepartamento = function (departamento) {
        departamento.excluido = true;
        departamento.acao = 'EXCLUIR';
        $scope.departamentoId = "";
    };

    $scope.mostrarTabelaDepartamentos = () =>{
        let deptos = $scope.registro.departamentos.filter(d => d.excluido !== true);
        return deptos.length > 0;
    }

    $scope.limparDepartamentosSelecionados = () =>{
        for(let i = 0 ; i < $scope.departamentos.length ; i++){
            $scope.departamentos[i].selected = false;
        }
    }

    $scope.alterarModoExibicao = (modo)=>{
        $scope.modoExibicao = modo;
        $localStorage.bancoArquivoModo = modo;
    }



});





/* ========================================= */
/* ROTAS                                     */
