    $scope.startInfinityScroll = () => {
        $('#chat-interno-mensagens').scroll(function (e) {
            // console.log("$scope.controlePaginacao.mensagens.stopScrollLoading", $scope.controlePaginacao.mensagens.stopScrollLoading);
            if ($scope.controlePaginacao.mensagens.stopScrollLoading) {
                return;
            }
            // console.log("$(e.target).prop('scrollHeight')", $(e.target).prop('scrollHeight'))
            // console.log("$(e.target).prop('clientHeight')", $(e.target).prop('clientHeight'))
            // console.log("$(e.target).scrollTop()", $(e.target).scrollTop());

            // if ($(e.target).prop('scrollHeight') - $(e.target).prop('clientHeight') - $(e.target).scrollTop() < 100) {
            if ($(e.target).scrollTop() < 100) {
                $scope.recuperarMensagens(true);
            }
        });


    }

    $scope.recuperarMensagens = (scrollUp) => {
        if ($scope.isJadiOpen) {
            $scope.searchForMoreJadiMessages();
            return
        } else {
            if ($scope.chatSelecionado === null) return;
            if ($scope.controlePaginacao.mensagens.carregando) return;
            let { offset, limit } = $scope.controlePaginacao.mensagens;


            $scope.controlePaginacao.mensagens.carregando = true;

            if (scrollUp) {
                offset = $scope.mensagens.length;
            } else {
                offset = 0;
            }
            // console.log("$scope ->", $scope);
            // console.log("chatSelecinado ->", $scope.chatSelecionado);
            $scope.controlePaginacao.mensagens.stopScrollLoading = true;
            ChatInternoService.recuperarMensagens($scope.chatSelecionado.id, $scope.tab, offset, limit, true).then(function (response) {

                // noMore = response.data.length === 0;
                var elMensagens = $("#chat-interno-mensagens");
                let _scrollHeight = 0 + elMensagens.prop('scrollHeight');
                let _scrollTop = 0 + elMensagens.prop('scrollTop');

                let _data = response.data.reverse();
                if ($scope.mensagens.length > 0) {
                    // $scope.loadingMsgs = true;
                    if (scrollUp) {
                        $scope.mensagens = _data.concat($scope.mensagens);
                    } else {
                        let lastId = $scope.mensagens[$scope.mensagens.length - 1].id;
                        $scope.mensagens = $scope.mensagens.concat(_data.filter(i => i.id > lastId));
                    }

                } else {
                    $scope.mensagens = _data;
                }



                //ajustar scroll do chat

                if (!scrollUp) {
                    setTimeout(function () {
                        elMensagens.scrollTop(elMensagens.prop('scrollHeight'));
                        $scope.controlePaginacao.mensagens.carregando = false;
                        $scope.controlePaginacao.mensagens.stopScrollLoading = false;
                    }, 500);
                } else {
                    setTimeout(function () {
                        elMensagens.scrollTop(elMensagens.prop('scrollHeight') - _scrollHeight + _scrollTop);
                        $scope.controlePaginacao.mensagens.carregando = false;
                        $scope.controlePaginacao.mensagens.stopScrollLoading = false;
                    }, 300);
                }



                // $scope.loadingMsgs = false;
                updateComponentsAfterRequest();

                let fileInputChatInterno = document.getElementById("fileInputChatInterno");

                if (fileInputChatInterno) {
                    fileInputChatInterno.removeEventListener('change', insertFile);
                    fileInputChatInterno.addEventListener('change', insertFile);
                }

            });
        }
    }

    function insertFile() {
        let fileInputChatInterno = document.getElementById("fileInputChatInterno");
        let files = fileInputChatInterno.files;
        for (const f of files) {
            $scope.readFile(f);
        }
    };

