    $scope.getAll = (reset) => {
        let { offset, limit, carregando } = $scope.controlePaginacao.lista;

        if (carregando) {
            return;
        }
        $scope.controlePaginacao.lista.carregando = true;

        const chatAberto = $scope.viewMode === $scope.ViewModeEnum.OPEN;
        const promise = chatAberto
            ? ChatInternoService.recuperarAll(offset, limit, $scope.chatInternoFiltroPesquisar || "")
            : ChatInternoService.recuperarAllMinimizado();

        promise.then(function (response) {
            $scope.all = response.data;
            $scope.controlePaginacao.lista.carregando = false;

            $scope.statusAll = []

            $.each($scope.all, function (index, contato) {
                if (contato.tab === $scope.TabsEnum.CONTACTS) {
                    $scope.statusAll[contato.id] = contato;
                }
            });

            $scope.startListenerStatus();
        });
    }

