var atendimentoUtils = {
    clamp: (num, min, max) => Math.min(Math.max(num, min), max),
    debounce: (fn, delay) => {
        let timeout;
        return function (...args) {
            clearTimeout(timeout);
            timeout = setTimeout(() => fn.apply(this, args), delay);
        };
    },
}
    



