materialAdmin.controller('FbotController', function ($rootScope, $scope, $window, $translate, $uibModal, BotService, BotFacebookService, BotWhatsAppOficialService, DepartamentoService) {

    var WA_CONFIG_ID_PADRAO = '2435659333507229';

    $scope.botsFacebook = [];
    $scope.botsInstagram = [];
    $scope.botsWhatsapp = [];

    $scope.activationType;

    $scope.WA_EMBEDDED_SIGNUP_DATA = {};

    $scope.onInit = function () {

        DepartamentoService.getAtivos().then(function (response) {
            $scope.departamentos = response.data;
        });

        BotService.getToFbot().then(function (response) {
            if (response.data.botsFacebook) {
                $scope.botsFacebook = $scope.botsFacebook.concat(response.data.botsFacebook);
            }

            if (response.data.botsInstagram) {
                $scope.botsInstagram = $scope.botsInstagram.concat(response.data.botsInstagram);
            }

            if (response.data.botsWhatsapp) {
                $scope.botsWhatsapp = $scope.botsWhatsapp.concat(response.data.botsWhatsapp);
            }
        });

    };

    // FACEBOOK

    $scope.checkLoginStateFacebook = function (loginResponse) {
        if (loginResponse.status === "connected") {
            $scope.botFacebookSelecionado = {};
            $scope.botFacebookSelecionado.userAccessToken = loginResponse.authResponse.accessToken;

            BotFacebookService.iniciarBot($scope.botFacebookSelecionado).then(function () {
                window.location.reload();
            });
        } else if (loginResponse.status === "unknown") {
            return;
        } else {
            $scope.onInit();
        }
    };

    //WHATSAPP

    $scope.showModalAtivacaoWhatsAppApi = function () {
        $scope.modalEmbeddedSigup = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/fbot/modal-embedded-signup.html',
            scope: $scope
        });
    };

    $scope.setActivationType = function (value) {
        $scope.activationType = value;
    }

    $scope.setActivationImportChat = function (value) {
        $scope.activationImportChat = value;
    }

    $scope.setActivationImportContacts = function (value) {
        $scope.activationImportContacts = value;
    }

    $scope.setActivationHistoryAction = function (value) {
        $scope.activationHistoryAction = value;
    }

    $scope.onSelecionarDepartamento = function () {
        $scope.departamentoSelecionado.atendentes = $scope.departamentos.find(function (departamento) {
            return departamento.id === parseInt($scope.departamentoSelecionado.departamentoId, 10);
        }).atendentes;

        $scope.departamentoSelecionado.atendenteId = '0';
    };

    $scope.closeModalAtivacaoWhatsAppApi = function () {
        if ($scope.modalEmbeddedSigup) {
            $scope.modalEmbeddedSigup.close();
        }
    };

    $scope.isModalAtivacaoWhatsAppApiValid = function () {

        $scope.WA_EMBEDDED_SIGNUP_DATA.action.importContacts = $scope.activationImportContacts;

        if ($scope.activationImportContacts) {

            $scope.WA_EMBEDDED_SIGNUP_DATA.action.importChat = false;

            if ($scope.activationImportChat == 'false') {

                return true;
            } else if ($scope.activationImportChat == 'true') {

                $scope.WA_EMBEDDED_SIGNUP_DATA.action.importChat = true;
                $scope.WA_EMBEDDED_SIGNUP_DATA.action.importChatAction = $scope.activationHistoryAction;

                if ($scope.activationHistoryAction == 'NONE' || $scope.activationHistoryAction == 'CREATE_LEAD') {

                    return true;
                } else if ($scope.activationHistoryAction == 'CREATE_TICKET') {

                    $scope.WA_EMBEDDED_SIGNUP_DATA.action.departamentoId = $scope.departamentoSelecionado.departamentoId;
                    $scope.WA_EMBEDDED_SIGNUP_DATA.action.atendenteId = $scope.departamentoSelecionado.atendenteId;

                    if ($scope.departamentoSelecionado.departamentoId) {
                        return true;
                    }

                }
            }

        }

        return false;
    };

    $scope.showLoginFacebook = function () {
        $scope.startFBot();

        FB.login(function (response) {
            $scope.checkLoginStateFacebook(response);
        }, {
            scope: 'public_profile,email,pages_show_list,pages_messaging,pages_read_engagement,pages_manage_metadata,instagram_basic,instagram_manage_messages,business_management'
        });
    }

    $scope.getWaConfigId = function () {
        return ($rootScope.customizacao && $rootScope.customizacao.metaWaConfigId) || WA_CONFIG_ID_PADRAO;
    };

    $scope.showLoginWhatsApp = function (botWhatsappId) {
        $scope.WA_EMBEDDED_SIGNUP_DATA = {
            botWhatsappId: botWhatsappId,
            action: {}
        };

        delete $scope.activationType;
        delete $scope.activationImportChat;
        delete $scope.activationImportContacts;
        delete $scope.activationHistoryAction;

        $scope.departamentoSelecionado = {};
        $scope.startWaBot();

        FB.login(function (response) {
            if (response.status == 'connected') {
                $scope.WA_EMBEDDED_SIGNUP_DATA.code = response.authResponse.code;

                if ($scope.WA_EMBEDDED_SIGNUP_DATA.apiEmbeddedQrCode) {
                    $scope.showModalAtivacaoWhatsAppApi();
                } else {
                    $scope.register();
                }
            }
        }, {
            config_id: $scope.getWaConfigId(),
            response_type: 'code',
            override_default_response_type: true,
            extras: {
                version: 'v4',
                featureType: 'whatsapp_business_app_onboarding',
                sessionInfoVersion: '3'
            }
        });
    };

    $scope.register = function () {
        $scope.closeModalAtivacaoWhatsAppApi();

        if (!$scope.WA_EMBEDDED_SIGNUP_DATA.code) {
            return;
        }

        let data = {
            id: $scope.WA_EMBEDDED_SIGNUP_DATA.botWhatsappId,
            apiPhoneNumberId: $scope.WA_EMBEDDED_SIGNUP_DATA.phone_number_id,
            apiBusinessAccountId: $scope.WA_EMBEDDED_SIGNUP_DATA.waba_id,
            apiEmbeddedSignupCode: $scope.WA_EMBEDDED_SIGNUP_DATA.code,
            apiEmbeddedQrCode: $scope.WA_EMBEDDED_SIGNUP_DATA.apiEmbeddedQrCode,
            apiEmbeddedQrCodeHistoryAction: JSON.stringify($scope.WA_EMBEDDED_SIGNUP_DATA.action)
        }

        BotWhatsAppOficialService.register(data).then(function () {
            $window.location.reload();
        });
    }

    $scope.processEventMessageFacebook = function (data) {
        try {
            const response = JSON.parse(data);

            if (response.type === 'WA_EMBEDDED_SIGNUP') {
                if (response.event == 'FINISH' || response.event == 'FINISH_WHATSAPP_BUSINESS_APP_ONBOARDING') {
                    $scope.WA_EMBEDDED_SIGNUP_DATA = {
                        ...$scope.WA_EMBEDDED_SIGNUP_DATA,
                        ...response.data
                    };
                    $scope.WA_EMBEDDED_SIGNUP_DATA.apiEmbeddedQrCode = response.event == 'FINISH_WHATSAPP_BUSINESS_APP_ONBOARDING'
                }
            }
        } catch {

        }
    }

    $scope.deregisterWhatsAppApi = function (botWhatsapp) {
        swal({
            title: $translate.instant('ATENCAO') + "!",
            text: "Essa ação irá desabilitar a integração com nossa plataforma. " + (botWhatsapp.embeddedSingupQrCode ? "Além disso, para remover o vínculo por completo, desconecte a Plataforma Comercial em seu celular." : ""),
            type: "warning",
            showCancelButton: true,
            confirmButtonColor: "#DD6B55",
            confirmButtonText: $translate.instant('CONFIRMAR'),
            cancelButtonText: $translate.instant('CANCELAR'),
            closeOnConfirm: false,
            closeOnCancel: true
        }, function (isConfirm) {
            if (isConfirm) {
                BotWhatsAppOficialService.deregister(botWhatsapp.id).then(function () {
                    window.location.reload();
                });
            }
        });
    };

});
;

