        $scope.onRenewIdsAndUuids =
            function () {

                $scope.perguntasUUIDMap =
                    {};

                function renovar(
                    perguntas,
                    superior
                ) {

                    angular.forEach(
                        perguntas || [],
                        function (pergunta) {

                            if (!pergunta) {
                                return;
                            }

                            pergunta.UUID =
                                typeof generateUUID ===
                                "function"
                                    ? generateUUID()
                                    : (
                                        "uuid-" +
                                        Date.now() +
                                        "-" +
                                        Math.random()
                                            .toString(16)
                                            .substring(2)
                                    );

                            if (superior) {

                                pergunta.perguntaSuperiorUUID =
                                    superior.UUID;

                            } else {

                                delete pergunta.perguntaSuperiorUUID;
                            }

                            $scope.perguntasUUIDMap[
                                pergunta.UUID
                            ] = pergunta;

                            renovar(
                                pergunta.perguntas,
                                pergunta
                            );
                        }
                    );
                }

                renovar(
                    $scope.perguntasMenu.perguntas,
                    null
                );

                $scope.alteracoesNaoSalvas =
                    true;
            };


