        $scope.onSelecionarEmoji =
            function (emoji) {

                if (!emoji) {
                    return;
                }

                $scope.emojiSelecionado =
                    emoji;

                if (
                    !$localStorage.recentEmojis
                ) {

                    $localStorage.recentEmojis =
                        [];
                }

                var recentes =
                    $localStorage
                        .recentEmojis;

                var index =
                    recentes.indexOf(
                        emoji
                    );

                if (index >= 0) {
                    recentes.splice(
                        index,
                        1
                    );
                }

                recentes.unshift(
                    emoji
                );

                if (
                    recentes.length > 20
                ) {

                    recentes.length =
                        20;
                }

                $scope.emojiListControl
                    .recentEmojis =
                    recentes;

                if (
                    $scope.modalEmojis
                ) {

                    $scope.modalEmojis
                        .close(emoji);
                }
            };


