        $scope.validatePerguntas =
            function () {

                var erros = [];

                angular.forEach(
                    $scope.perguntasUUIDMap,
                    function (pergunta) {

                        if (!pergunta) {
                            return;
                        }

                        pergunta.valid =
                            $scope
                                .isPerguntaValid(
                                    pergunta
                                );

                        if (!pergunta.valid) {
                            erros.push(
                                pergunta
                            );
                        }
                    }
                );

                $scope.perguntasComErro =
                    erros;

                return erros.length === 0;
            };


        $scope.checkErrorPergunta =
            function (pergunta) {

                return (
                    pergunta &&
                    pergunta.valid === false
                );
            };


        $scope.loadPerguntasError =
            function () {

                $scope.perguntasComErro =
                    [];

                angular.forEach(
                    $scope.perguntasUUIDMap,
                    function (pergunta) {

                        if (
                            pergunta &&
                            pergunta.valid === false
                        ) {

                            $scope.perguntasComErro
                                .push(
                                    pergunta
                                );
                        }
                    }
                );

                return $scope.perguntasComErro;
            };


