        $scope.mindmapRecalcularNumeros =
            function (perguntas) {

                angular.forEach(
                    perguntas || [],
                    function (
                        pergunta,
                        index
                    ) {

                        if (!pergunta) {
                            return;
                        }

                        pergunta.numero =
                            index + 1;

                        pergunta.ordem =
                            index + 1;

                        if (
                            pergunta.perguntas
                        ) {

                            $scope
                                .mindmapRecalcularNumeros(
                                    pergunta.perguntas
                                );
                        }
                    }
                );
            };


        $scope.mindmapCanMoveUp =
            function (node) {

                var perguntas =
                    $scope
                        .getMindmapParentPerguntas(
                            node
                        );

                var index =
                    perguntas.indexOf(node);

                return index > 0;
            };


        $scope.mindmapCanMoveDown =
            function (node) {

                var perguntas =
                    $scope
                        .getMindmapParentPerguntas(
                            node
                        );

                var index =
                    perguntas.indexOf(node);

                return (
                    index >= 0 &&
                    index <
                        perguntas.length - 1
                );
            };


        $scope.mindmapMoveUp =
            function (node) {

                var perguntas =
                    $scope
                        .getMindmapParentPerguntas(
                            node
                        );

                var index =
                    perguntas.indexOf(node);

                if (index <= 0) {
                    return;
                }

                var anterior =
                    perguntas[index - 1];

                perguntas[index - 1] =
                    node;

                perguntas[index] =
                    anterior;

                $scope
                    .mindmapRecalcularNumeros(
                        perguntas
                    );

                $scope.alteracoesNaoSalvas =
                    true;
            };


        $scope.mindmapMoveDown =
            function (node) {

                var perguntas =
                    $scope
                        .getMindmapParentPerguntas(
                            node
                        );

                var index =
                    perguntas.indexOf(node);

                if (
                    index < 0 ||
                    index >=
                        perguntas.length - 1
                ) {
                    return;
                }

                var proximo =
                    perguntas[index + 1];

                perguntas[index + 1] =
                    node;

                perguntas[index] =
                    proximo;

                $scope
                    .mindmapRecalcularNumeros(
                        perguntas
                    );

                $scope.alteracoesNaoSalvas =
                    true;
            };


