materialAdmin.controller("BotsController", [
    "$scope",
    "$http",
    "$interval",
    function ($scope, $http, $interval) {

        // =====================================================
        // LISTA
        // =====================================================

        $scope.bots = [];

        $scope.filtro = {
            nome: "",
            tipo: "TODOS",
            canal: "TODOS",
            status: "ACTIVE"
        };


        // =====================================================
        // MODAL
        // =====================================================

        $scope.modalBot = {
            aberto: false,
            carregando: false,
            erro: null,
            sucesso: null,
            etapa: "criar"
        };


        // =====================================================
        // DADOS DO NOVO BOT
        // =====================================================

        $scope.novoBotDados = {
            nome: "",
            canal: "WHATSAPP",
            tipo: "CHATBOT",
            numero: "",
            status: "AGUARDANDO_CONEXAO",
            id: null,
            qrCode: null
        };


        // =====================================================
        // ABRIR MODAL
        // =====================================================

        $scope.novoBot = function () {

            $scope.novoBotDados = {
                nome: "",
                canal: "WHATSAPP",
                tipo: "CHATBOT",
                numero: "",
                status: "AGUARDANDO_CONEXAO",
                id: null,
                qrCode: null
            };

            $scope.modalBot.aberto = true;
            $scope.modalBot.carregando = false;
            $scope.modalBot.erro = null;
            $scope.modalBot.sucesso = null;
            $scope.modalBot.etapa = "criar";

        };


        // =====================================================
        // FECHAR MODAL
        // =====================================================

        $scope.fecharModalBot = function () {

            $scope.modalBot.aberto = false;

            $scope.modalBot.carregando = false;
            $scope.modalBot.erro = null;
            $scope.modalBot.sucesso = null;

        };


        // =====================================================
        // BUSCAR BOTS
        // =====================================================

        $scope.buscar = function () {

            $http.get("/api/bots.php", {
                params: {
                    canalBot: $scope.filtro.canal,
                    nome: $scope.filtro.nome,
                    status: $scope.filtro.status,
                    tipoBot: $scope.filtro.tipo
                }
            }).then(function (response) {

                var data = response.data;

                if (angular.isArray(data)) {

                    $scope.bots = data;

                } else if (
                    data &&
                    angular.isArray(data.bots)
                ) {

                    $scope.bots = data.bots;

                } else {

                    $scope.bots = [];

                }

            }, function () {

                $scope.bots = [];

            });

        };


        // =====================================================
        // ENTER NO CAMPO DE BUSCA
        // =====================================================

        $scope.enterBuscar = function ($event) {

            if (
                $event &&
                $event.which === 13
            ) {

                $scope.buscar();

            }

        };


        // =====================================================
        // STATUS
        // =====================================================

        $scope.getStatusTexto = function (status) {

            status = String(status || "").toUpperCase();

            if (
                status === "CONNECTED" ||
                status === "CONECTADO" ||
                status === "ONLINE"
            ) {
                return "Conectado";
            }

            if (
                status === "DISCONNECTED" ||
                status === "DESCONECTADO" ||
                status === "OFFLINE"
            ) {
                return "Desconectado";
            }

            if (
                status === "ACTIVE" ||
                status === "ATIVO"
            ) {
                return "Ativo";
            }

            if (
                status === "INACTIVE" ||
                status === "INATIVO"
            ) {
                return "Inativo";
            }

            if (
                status === "AGUARDANDO_CONEXAO" ||
                status === "WAITING"
            ) {
                return "Aguardando conexão";
            }

            return status || "Aguardando conexão";

        };


        $scope.getStatusClass = function (status) {

            status = String(status || "").toUpperCase();

            if (
                status === "CONNECTED" ||
                status === "CONECTADO" ||
                status === "ONLINE"
            ) {
                return "status-conectado";
            }

            if (
                status === "DISCONNECTED" ||
                status === "DESCONECTADO" ||
                status === "OFFLINE"
            ) {
                return "status-desconectado";
            }

            return "status-aguardando";

        };


        // =====================================================
        // CRIAR BOT
        // =====================================================

        $scope.criarBot = function () {

            if (
                !$scope.novoBotDados.nome ||
                !$scope.novoBotDados.nome.trim()
            ) {

                $scope.modalBot.erro =
                    "Digite o nome do bot.";

                return;

            }


            $scope.modalBot.carregando = true;
            $scope.modalBot.erro = null;


            var dados = {
                nome: $scope.novoBotDados.nome,
                canal: "WHATSAPP",
                tipo: $scope.novoBotDados.tipo
            };


            $http.post(
                "/api/bots.php",
                dados
            ).then(function (response) {

                var data = response.data || {};

                var bot = data.bot || data;


                if (bot.id !== undefined) {
                    $scope.novoBotDados.id = bot.id;
                }

                if (bot._id !== undefined) {
                    $scope.novoBotDados.id = bot._id;
                }

                if (bot.nome) {
                    $scope.novoBotDados.nome =
                        bot.nome;
                }

                if (bot.status) {
                    $scope.novoBotDados.status =
                        bot.status;
                }


                $scope.modalBot.etapa = "status";

                $scope.buscar();

            }, function (response) {

                $scope.modalBot.erro =
                    "Não foi possível criar o bot.";

                if (
                    response &&
                    response.data &&
                    response.data.erro
                ) {

                    $scope.modalBot.erro =
                        response.data.erro;

                }

            }).finally(function () {

                $scope.modalBot.carregando = false;

            });

        };


        // =====================================================
        // MOSTRAR QR CODE
        // =====================================================

        $scope.mostrarQRCode = function () {

            $scope.modalBot.erro = null;

            $scope.novoBotDados.qrCode = null;

            $scope.modalBot.etapa = "qrcode";

            $scope.buscarQRCode();

        };


        // =====================================================
        // BUSCAR QR
        // =====================================================

        $scope.buscarQRCode = function () {

            $http.get(
                "https://socket.n3bot.com.br/qr",
                {
                    headers: {
                        "ngrok-skip-browser-warning": "true",
                        "Content-Type": "application/json"
                    }
                }
            ).then(function (response) {

                var data = response.data || {};


                if (data.qr) {

                    $scope.novoBotDados.qrCode =
                        data.qr;

                }


                if (data.status) {

                    $scope.novoBotDados.status =
                        data.status;

                }


                var status =
                    String(
                        data.status || ""
                    ).toUpperCase();


                if (
                    status === "CONNECTED" ||
                    status === "CONECTADO" ||
                    status === "ONLINE"
                ) {

                    $scope.novoBotDados.qrCode =
                        null;

                    $scope.modalBot.etapa =
                        "conectado";

                    $scope.buscar();

                }

            }, function () {

                $scope.modalBot.erro =
                    "Erro ao conectar ao servidor WhatsmaterialAdmin.";

            });

        };


        // =====================================================
        // DESCONectar WHATSAPP
        // =====================================================

        $scope.desconectarWhatsApp = function () {

            if (
                !window.confirm(
                    "Deseja realmente desconectar o WhatsApp?"
                )
            ) {
                return;
            }


            $scope.modalBot.carregando = true;


            $http.post(
                "https://socket.n3bot.com.br/logout",
                {},
                {
                    headers: {
                        "ngrok-skip-browser-warning": "true",
                        "Content-Type": "application/json"
                    }
                }
            ).then(function () {

                $scope.novoBotDados.status =
                    "DESCONECTADO";

                $scope.novoBotDados.qrCode =
                    null;

                $scope.modalBot.etapa =
                    "qrcode";

                $scope.buscarQRCode();

            }, function () {

                $scope.modalBot.erro =
                    "Erro ao desconectar o WhatsmaterialAdmin.";

            }).finally(function () {

                $scope.modalBot.carregando = false;

            });

        };


        // =====================================================
        // ATUALIZA QR AUTOMATICAMENTE
        // =====================================================

        var intervaloQR = null;


        function iniciarQR() {

            if (intervaloQR) {
                return;
            }


            intervaloQR = $interval(
                function () {

                    if (
                        !$scope.modalBot.aberto
                    ) {
                        return;
                    }

                    if (
                        $scope.modalBot.etapa !==
                        "qrcode"
                    ) {
                        return;
                    }

                    $scope.buscarQRCode();

                },
                15000
            );

        }


        function pararQR() {

            if (intervaloQR) {

                $interval.cancel(
                    intervaloQR
                );

                intervaloQR = null;

            }

        }


        $scope.$watch(
            "modalBot.etapa",
            function (etapa) {

                if (
                    etapa === "qrcode"
                ) {

                    iniciarQR();

                } else {

                    pararQR();

                }

            }
        );


        $scope.$on(
            "$destroy",
            function () {

                pararQR();

            }
        );


        // =====================================================
        // INICIALIZA
        // =====================================================

        $scope.buscar();

    }
]);

materialAdmin.service('ContatoInformacaoService', function ($http, $setting) {

    this.getTodos = function (params) {
        var request = $http({
            method: "get",
            url: $setting.api + "/contato_informacoes",
            isArray: true,
            params: params
        });

        return (request);
    };

    this.getTodosPorUsuario = function (params) {
        var request = $http({
            method: "get",
            url: $setting.api + "/contato_informacoes/usuario",
            isArray: true,
            params: params
        });

        return (request);
    };

    this.getTodosSimples = function (params) {
        var request = $http({
            method: "get",
            url: $setting.api + "/contato_informacoes/simples",
            isArray: true,
            params: params
        });

        return (request);
    };

    this.getById = function (id) {
        var request = $http({
            method: "get",
            url: $setting.api + "/contato_informacoes/" + id
        });

        return (request);
    };

    this.inserir = function (data) {
        var request = $http({
            method: "put",
            url: $setting.api + "/contato_informacoes",
            data: data
        });

        return (request);
    };

    this.atualizar = function (data) {
        var request = $http({
            method: "post",
            url: $setting.api + "/contato_informacoes/" + data.id,
            data: data
        });

        return (request);
    };
 
    this.remover = function (id) {
        var request = $http({
            method: "delete",
            url: $setting.api + "/contato_informacoes/" + id
        });

        return (request);
    };

    this.requestIntegracao = (data) => {
        var request = $http({
            method: "post",
            url: `${$setting.api}/contato_informacoes/integracao`,
            data: data
        });

        return (request);
    };

    this.updateOrdering = (data) => {
        var request = $http({
            method: "PUT",
            url: `${$setting.api}/contato_informacoes/update-ordering`,
            data: data
        });

        return (request);
    };

});;
