    $scope.hasModuleAiBotActive = (registro) => {
        if (registro.tipo === 'JADI' && (!$scope.permissions.permissionBotCompletoAis && !$scope.permissions.permissionBotBasicoAis)) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: "Para associar um canal em um BOT é necessário contratar o serviço de IA.\nDeseja ir para a tela de contratação de módulos?",
                type: "warning",
                showCancelButton: true,
                confirmButtonText: $translate.instant('SIM'),
                cancelButtonText: $translate.instant('CANCELAR'),
                closeOnConfirm: true,
                closeOnCancel: true
            }, function (isConfirm) {
                if (isConfirm) {
                    $state.go('releases.priceTable-client');
                }
            });
            return false;
        }
        return true;
    }

