    $scope.onVisualizarQrcode = function (telefone) {
        FirebaseUtil.wabot.onUpdateQrCode(telefone.numero, telefone.authType);

        TelefoneService.getQrcode(telefone.telefoneId).then(function (response) {
            $scope.telefoneId = telefone.telefoneId;
            $scope.telefoneNumber = telefone.numero;
            $scope.telefoneAuthType = telefone.authType;
            $scope.telefoneQrcode = response.data.qrcode;

            $scope.modalQrcode = $uibModal.open({
                animation: true,
                keyboard: false,
                backdrop: 'static',
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/perguntas//modal-qrcode.html?t=' + Date.now(),
                scope: $scope,
                controller: function () {
                    $scope.intervalQrcode = setInterval(function () {
                        if ($scope.loadingQrCode) {
                            return;
                        }

                        $scope.loadingQrCode = true;

                        FirebaseUtil.wabot.onUpdateQrCode($scope.telefoneNumber, $scope.telefoneAuthType);

                        TelefoneService.getQrcode($scope.telefoneId).then(function (response) {
                            if (response.data.qrcode) {
                                $scope.telefoneQrcode = response.data.qrcode + "?t=" + new Date().getTime();
                            }

                            if (response.data.status === StatusTelefone.ONLINE) {
                                clearInterval($scope.intervalQrcode);
                                $scope.modalQrcode.close();
                                $scope.onInit();
                            }

                            $scope.loadingQrCode = false;
                        });
                    }, 2000);
                }
            });

        });
    };

    $scope.getQrCode = function () {

    }

    $scope.onModalQrcodeCancelar = function () {
        $scope.modalQrcode.close();
        $scope.modalQrcode = {};
        clearInterval($scope.intervalQrcode);
    }

