    $scope.onEditarBotSite = function (botSite) {
        $scope.botSiteSelecionado = botSite;

        $scope.modalBotSite = $uibModal.open({
            animation: true,
            keyboard: false,
            backdrop: 'static',
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/perguntas//modal-bot-site.html?t=' + NO_CACHE,
            scope: $scope
        });

        $scope.modalBotSite.rendered.then(function () {
            $scope.saveImage = false;

            updateComponentsAfterRequest();

            if ($scope.botSiteSelecionado.imagem != undefined) {
                $scope.onModificarImagem("bot-site", true);
            } else {
                $scope.onModificarImagem("bot-site", false);
            }

            if (!$scope.botSiteSelecionado.cor) {
                $scope.botSiteSelecionado.cor = '#BBBBBB';
            }

            angular.element("#imagem-bot-site-input")
                .on('change.bs.fileinput',
                    function (event, data) {
                        $scope.atualizarImagemBotSite(data);
                    });

            angular.element("#imagem-bot-site-input")
                .on('clear.bs.fileinput',
                    function (event) {
                        $scope.atualizarImagemBotSite(null);
                    });
        });
    };

    $scope.onModalBotSiteEnviar = function () {
        var save = function () {
            BotSiteService.atualizarCustomizacao($scope.botSiteSelecionado).then(function () {
                swal({
                    title: $translate.instant('PRONTO') + "!",
                    text: $translate.instant('REGISTRO-ATUALIZADO'),
                    type: "success",
                    timer: 2000
                }, function () {
                    $scope.onModalBotSiteCancelar();
                    $scope.onInit();
                });
            });
        };

        if ($scope.saveImage) {
            FileService.insertBase64($scope.imagemBase64, $scope.imagemName).then(function (response) {
                $scope.saveImage = false;

                $scope.botSiteSelecionado.imagem = response.data.url;
                save();
            });
        } else {
            save();
        }
    };

    $scope.onModalBotSiteCancelar = function () {
        $scope.modalBotSite.close();
        $scope.botSiteSelecionado = {};
    };

    $scope.atualizarImagemBotSite = function (imagem) {
        if (imagem !== null) {
            $scope.saveImage = true;

            $scope.imagemBase64 = imagem.result;
            $scope.imagemName = imagem.name;

            $scope.botSiteSelecionado.fileId = 0;

            $scope.onModificarImagem("bot-site", true);
        } else {
            $scope.imagemBase64 = undefined;
            $scope.imagemName = undefined;

            $scope.botSiteSelecionado.imagem = undefined;
            $scope.botSiteSelecionado.fileId = 0;

            $scope.onModificarImagem("bot-site", false);
        }
    };

    $scope.onModificarImagem = function (tipo, possuiImagem) {
        if (possuiImagem) {
            $(".fileinput-selecionar-" + tipo).hide();
            $(".fileinput-action-" + tipo).show();
        } else {
            $(".fileinput-selecionar-" + tipo).show();
            $(".fileinput-action-" + tipo).hide();
        }
    };

