    $scope.onModalSalvarEdicaoGruposEmail = function () {
        var gruposNaoDeletados = $scope.registroModalGruposEmail.gruposEmail.filter(function (item) {
            return !item.deleted;
        });

        if (gruposNaoDeletados.length > $scope.registroModalGruposEmail.limiteGrupos) {
            return swal("Ops!", "Limite de grupos de email ultrapassado", "error");
        }

        BotEmailGrupoPerguntaService.atualizarGruposEmail($scope.registroModalGruposEmail).then(function () {
            swal({
                title: $translate.instant('PRONTO') + "!",
                text: $translate.instant('REGISTRO-ATUALIZADO'),
                type: "success",
                timer: 2000,
            }, function () {
                $scope.onModalCancelarEdicaoGruposEmail();
            });
        });
    };

    $scope.onModalSalvarEdicaoGrupoEmail = function () {
        if (!$scope.registroModalGrupoEmail.email || $scope.registroModalGrupoEmail.email == "") {
            return swal("Ops!", "Digite um email para o grupo", "error");
        }

        if (!$scope.registroModalGrupoEmail.departamentoId || $scope.registroModalGrupoEmail.departamentoId == "") {
            return swal("Ops!", "Escolha um departamento para o grupo", "error");
        }

        var grupoAtualizar = $scope.registroModalGruposEmail.gruposEmail.filter(function (item) {
            return item === $scope.registroModalGrupoEmailOriginal;
        });

        if (grupoAtualizar != null && grupoAtualizar.length > 0) {
            $scope.registroModalGruposEmail.gruposEmail.splice($scope.registroModalGruposEmail.gruposEmail.indexOf($scope.registroModalGrupoEmailOriginal), 1);
        }

        var departamentoSelecionado = $scope.modalGrupoEmailDepartamentos.filter(function (item) { return item.id == $scope.registroModalGrupoEmail.departamentoId });

        $scope.registroModalGrupoEmail.departamentoNome = departamentoSelecionado[0].nome;

        $scope.registroModalGruposEmail.gruposEmail.push($scope.registroModalGrupoEmail);

        $scope.onModalCancelarEdicaoGrupoEmail();
    };

    $scope.onModalCancelarEdicaoGruposEmail = function () {
        $scope.modalGruposEmail.close();
        $scope.registroModalGruposEmail = {};
    };

    $scope.onModalCancelarEdicaoGrupoEmail = function () {
        $scope.modalEditarGrupoEmail.close();
        $scope.modalGrupoEmailDepartamentos = {};
        $scope.registroModalGrupoEmailOriginal = {};
        $scope.registroModalGrupoEmail = {};
    };

    $scope.isLimiteGruposEmailAlcancado = function () {
        var gruposNaoDeletados = $scope.registroModalGruposEmail.gruposEmail.filter(function (item) {
            return !item.deleted;
        });

        return gruposNaoDeletados.length >= $scope.registroModalGruposEmail.limiteGrupos;
    };

