    $scope.onRenomearCanal = function (canal, tipo) {
        $scope.canalSelecionado = canal;
        $scope.canalSelecionadoTipo = tipo;
        $scope.apelidoCanal = { valor: canal.apelido || "" };

        $scope.modalRenomearCanal = $uibModal.open({
            animation: true,
            templateUrl: 'views/megazap/perguntas/modal-renomear-canal.html?t=' + NO_CACHE,
            scope: $scope
        });
    };

    $scope.onModalSalvarApelido = function () {
        var apelido = $scope.apelidoCanal.valor ? $scope.apelidoCanal.valor.trim() : "";
        var canal = $scope.canalSelecionado;
        var id = $scope.canalSelecionadoTipo === 'TELEFONE' ? canal.telefoneId : canal.id;
        var serviceMap = {
            'TELEFONE': TelefoneService,
            'SITE': BotSiteService,
            'FACEBOOK': BotFacebookService,
            'INSTAGRAM': BotFacebookService,
            'TELEGRAM': BotTelegramService,
            'EMAIL': BotEmailService,
            'GBM': BotGbmGrupoPerguntaService
        };
        var service = serviceMap[$scope.canalSelecionadoTipo];

        service.atualizarApelido(id, apelido).then(function () {
            canal.apelido = apelido;
            $scope.modalRenomearCanal.close();
            swal({
                title: $translate.instant('PRONTO') + "!",
                text: $translate.instant('REGISTRO-ATUALIZADO'),
                type: "success",
                timer: 2000
            });
        });
    };

