    $scope.atendimentosRetornos = { total: 0, registros: [], ids: [] };

    $scope.atendimentoSelecionado = {};
    $scope.atendimentoSelecionado.mensagens = [];

    $scope.privateMode = false;

    $scope.sessionPrivateMode = false;

    $scope.novaMensagem = {};
    $scope.novoArquivo = {};
    $scope.drafts = {};

    var _draftsStorageKey = 'mz_chat_drafts';

    $scope.saveDraftsToStorage = function () {
        try {
            var serializable = {};
            angular.forEach($scope.drafts, function (draft, id) {
                serializable[id] = {
                    texto: draft.texto,
                    arquivos: draft.arquivos,
                    arquivosModal: draft.arquivosModal,
                    preview: draft.preview,
                    audioBase64: draft.audioBase64
                };
            });
            localStorage.setItem(_draftsStorageKey, JSON.stringify(serializable));
        } catch (e) {}
    };

    $scope.loadDraftsFromStorage = function () {
        try {
            var stored = localStorage.getItem(_draftsStorageKey);
            if (!stored) return;
            var parsed = JSON.parse(stored) || {};
            angular.forEach(parsed, function (draft, id) {
                if (draft.audioBase64) {
                    try {
                        var parts = draft.audioBase64.split(',');
                        var mimeType = parts[0].match(/:(.*?);/)[1];
                        var byteString = atob(parts[1]);
                        var ab = new ArrayBuffer(byteString.length);
                        var ia = new Uint8Array(ab);
                        for (var i = 0; i < byteString.length; i++) {
                            ia[i] = byteString.charCodeAt(i);
                        }
                        draft.audio = new Blob([ab], { type: mimeType });
                    } catch (e) {
                        delete draft.audioBase64;
                    }
                }
            });
            $scope.drafts = parsed;
        } catch (e) {}
    };

    $scope.loadDraftsFromStorage();

    $scope.clearDraftIfEmpty = function () {
        if (!$scope.atendimentoSelecionado || !$scope.atendimentoSelecionado.id) return;
        var hasText = $scope.novaMensagem && $scope.novaMensagem.mensagem && $scope.novaMensagem.mensagem.length > 0;
        var hasFiles = $scope.arquivos && $scope.arquivos.length > 0;
        var hasAudio = ($scope.novaMensagemAudio && $scope.novaMensagemAudio.blob) || $scope.audioDraftUrl;
        if (!hasText && !hasFiles && !hasAudio) {
            delete $scope.drafts[$scope.atendimentoSelecionado.id];
            $scope.saveDraftsToStorage();
        }
    };

    $scope.$watch('novaMensagem.mensagem', function (newVal) {
        if (!newVal && $scope.atendimentoSelecionado && $scope.atendimentoSelecionado.id) {
            $scope.clearDraftIfEmpty();
        }
    });

    $scope.getDraftTipoArquivo = function (draft) {
        if (draft.audio || draft.audioBase64) return 'Áudio';
        if (!draft.arquivos || !draft.arquivos.length) return '';
        var first = draft.arquivos[0];
        if (first.isImage) return 'Foto';
        if (first.isPDF) return 'PDF';
        if (first.type && first.type.indexOf('video') >= 0) return 'Vídeo';
        if (first.type && first.type.indexOf('audio') >= 0) return 'Áudio';
        return 'Arquivo';
    };

