    $scope.removerAtendimentoPendente = function (id) {
        var atendimento;

        if ($scope.atendimentosPendentes.registros) {
            var atendimento = $scope.atendimentosPendentes.registros.filter(function (a) {
                return a.id == id;
            });

            if (atendimento && atendimento.length > 0) {
                $scope.atendimentosPendentes.registros = $scope.atendimentosPendentes.registros.filter(function (a) {
                    return a.id != id;
                });
            }

        }

        //removendo do controle de ids
        if ($scope.atendimentosPendentes.ids.has(id)) {
            $scope.atendimentosPendentes.ids.delete(id);

            if ($scope.atendimentosPendentes.total > 0) {
                $scope.atendimentosPendentes.total--;
            } else {
                console.log("TOTAL ERROR PENDING");
            }
        }

        return atendimento;
    };

