    $scope.iniciarFirebaseCliente = function () {

        ClienteService.getPermissions().then(function (response) {

            if (response.data.moduloRecados) {

                //-----------------------------------
                //-- ATUALIZAR RECADOS
                //-----------------------------------

                var listenerRefreshScraps = FirebaseUtil.helpdeskTicketStatus.onRefreshScraps($scope.jwt.clienteId, function (data) {
                    $scope.recuperarRecados(true, false);
                });

                $scope.socket.listeners.push(listenerRefreshScraps);

                //-----------------------------------
                //-- NOVOS RECADOS
                //-----------------------------------

                var listenerRefreshNewScrap = FirebaseUtil.helpdeskTicketStatus.onRefreshNewScrap($scope.jwt.clienteId, function (data) {
                    $scope.recuperarRecados(true, true);
                });

                $scope.socket.listeners.push(listenerRefreshNewScrap);

            }

        });

    };

