    $scope.enviarNotificacao = function (mensagem, dados, title, icon, imagem, potencial) {
        if ($scope.isOnline()) {
            if (Notification && Notification.permission === "granted") {

                if (!icon) {
                    icon = $rootScope.customizacao.imagemMenuLateral ? $rootScope.customizacao.imagemMenuLateral : window.location.protocol + "//" + window.location.host + "/img/nova-mensagem.png";
                }

                var notification = new Notification((title ? title : $rootScope.customizacao.nome), {
                    icon: icon,
                    body: mensagem,
                    image: imagem
                });

                notification.onclick = function () {
                    if (potencial) {
                        $scope.onMostarModalPotencial(dados);
                    } else {
                        $scope.selecionarAtendimento(dados);
                    }
                };
            }
        }
    };

    $scope.tabMensagensClick = function () {
        setTimeout(function () {
            $('#chat-div').scrollTop(99999);
        }, 500);
    }

    $scope.ativarNotificacao = function () {
        Notification.requestPermission().then(function (resposta) {
            $scope.permissaoNotificacao = resposta;
            $scope.$digest();
        });
    };

    $scope.perguntarNotificacao = function () {
        return $scope.permissaoNotificacao == "default";
    };

    $scope.tocarNotificacao = function () {
        if ($scope.isOnline()) {
            if (Notification && Notification.permission === "granted") {
                document.getElementById("notificacao").play().catch(err => {
                    //swal("Ops!", "Para receber o som das notificações, primeiro você precisa interagir com a tela. Infelizmente são regras do seu navegador.", "info");
                });
            }
        }
    };

    $scope.verificarPermissaoNotificacao = (type, message, ticket, nome, imagemPerfil, image, potencial) => {
        if (!$rootScope.profile || !$rootScope.profile.confNotification) return;

        const permission = $rootScope.profile.confNotification.find(n => n.type == type)

        if (!permission) return;

        if (permission.sound) {
            $scope.tocarNotificacao();
        }

        if (permission.notification) {
            $scope.enviarNotificacao(message, ticket, nome, imagemPerfil, image, potencial);
        }
    }

    $scope.isOnline = function () {
        return $rootScope.atendente.status === 'ONLINE' || $scope.isGestor() || $scope.isSupervisorChatbot();
    };

    $scope.trocarStatusAtendente = function () {
        var status;

        if ($rootScope.atendente.status === 'ONLINE') {
            status = 'OFFLINE';
        } else {
            status = 'ONLINE';
        }

        var data = {
            online: status === 'ONLINE'
        };

        UsuarioService.atualizarOnline(data).then(function () {
            $rootScope.atendente.status = status;
        });
    };

    $scope.recuperarInformacoesAtendente = function (callback) {
        UsuarioService.getChatPerfil().then(function (response) {
            $rootScope.atendente = {
                id: response.data.id,
                isOwner: false,
                nome: response.data.nome.split(' ')[0],
                status: response.data.online ? "ONLINE" : "OFFLINE",
                url: response.data.url ? response.data.url : "img/sem-foto.png",
                departamentos: response.data.departamentos,
                clienteId: response.data.clienteId,
                avaliacaoAtendimento: response.data.avaliacaoAtendimento,
                potenciais: response.data.potenciais,
                retornos: response.data.retornos,
                mensagensProgramadas: response.data.mensagensProgramadas,
                horaFim: response.data.horaFim
            };

            if (callback) callback();

            $scope.startSocketUser();
            $scope.iniciarFirebase();
        });
    };

    $scope.socketEvents = [];
    $scope.socketEventsRunning = false;

    $scope.socketInterval = setInterval(function () {
        if ($scope.socketEventsRunning) {
            SocketUtil.addLog("PENDING EVENTS: " + $scope.socketEvents.length);
            return;
        }

        $scope.socketEventsRunning = true;

        if ($scope.socketEvents.length) {
            var waiting;

            try {
                waiting = $scope.socketEvents[0]();

                if (!waiting) {
                    $scope.$apply();
                }
            } catch (e) {
                console.error('socket-interval-error', e);
            } finally {
                if (!waiting) {
                    $scope.socketEvents.splice(0, 1);
                }
            }
        }

        $scope.socketEventsRunning = false;
    }, 500);

    $scope.clearSocketTicket = function () {

        //DETAILS

        if ($scope.socket.listenerTicketDetails) {
            $scope.socket.listenerTicketDetails.off();
            delete $scope.socket.listenerTicketDetails;
        }

        //MESSAGES

        if ($scope.socket.listenerTicketMessages) {
            $scope.socket.listenerTicketMessages.off();
            delete $scope.socket.listenerTicketMessages;
        }

    }

    $scope.startSocketTicket = function (ticketUuid) {

        $scope.clearSocketTicket();

        $scope.socket.listenerTicketDetails = SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/tickets/' + ticketUuid + '/details', (data) => {

            SocketUtil.addLog('CLIENTS.TICKETS.DETAILS: ' + JSON.stringify(data));
            let socketEvent = () => { return $scope.runSocketTicketDetails(data); }
            $scope.socketEvents.push(socketEvent);

        });

        $scope.socket.listenerTicketMessages = SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/tickets/' + ticketUuid + '/messages', (data) => {

            SocketUtil.addLog('CLIENTS.TICKETS.MESSAGES: ' + JSON.stringify(data));
            let socketEvent = () => { return $scope.runSocketTicketMessages(data); }
            $scope.socketEvents.push(socketEvent);

        });

    }

    $scope.runSocketTicketDetails = function (data) {

        switch (data.type) {

            case 'SCHEDULED_MESSAGE':

                switch (data.eventType) {

                    case 'UPDATE_ITEM':

                        if (data.scheduledMessage && data.scheduledMessage.id) {
                            const idx = $scope.atendimentoSelecionado.informacoes.mensagensProgramadas.findIndex(mp => mp.id == data.scheduledMessage.id);

                            if (idx != -1) {
                                if ((data.scheduledMessage.status == 'ACTIVE' || data.scheduledMessage.status == 'PENDING')) {
                                    $scope.atendimentoSelecionado.informacoes.mensagensProgramadas[idx] = data.scheduledMessage;
                                } else {
                                    $scope.atendimentoSelecionado.informacoes.mensagensProgramadas.splice(idx, 1);
                                }
                            }
                        }

                        break;

                }

                break;

            case 'FOLLOW_UP':

                switch (data.eventType) {

                    case 'UPDATE_ITEM':

                        if (data.followUp && data.followUp.id) {
                            const idx = $scope.atendimentoSelecionado.informacoes.retornos.findIndex(mp => mp.id == data.followUp.id);

                            if (idx != -1) {
                                if ((data.followUp.status == 'ACTIVE' || data.followUp.status == 'PENDING')) {
                                    $scope.atendimentoSelecionado.informacoes.retornos[idx] = data.followUp;
                                } else {
                                    $scope.atendimentoSelecionado.informacoes.retornos.splice(idx, 1);
                                }
                            }
                        }

                        break;

                }

                break;

            case 'CRM_TASK':

                switch (data.eventType) {

                    case 'UPDATE_ITEM':

                        var taskIn = $scope.atendimentoSelecionado?.informacoes?.tasks?.find(c => c.id === data.crmTask.crmTaskId);
                        if (taskIn) {
                            taskIn.status = data.crmTask.crmTaskStatus;
                        }

                        break;

                }

                break;

        }

    }

    $scope.runSocketTicketMessages = function (data) {

        switch (data.type) {

            case 'TICKET':
            case 'LEAD':

                //o evento só é processando quando terminar essas requisições, para não ter concorrência
                if ($scope.controlePaginacao.mensagens.carregando) {
                    console.log("waiting messages request...");
                    return true;
                }

                switch (data.eventType) {

                    case 'ADD_ITEM':

                        //verificando se tem algum atendimento selecionado e se é o mesmo da mensagem
                        if (!$scope.atendimentoSelecionado || (data.messages && $scope.atendimentoSelecionado.id != data.messages[0].painelAtendimentoId)) {
                            return;
                        }

                        if (!$scope.atendimentoSelecionado.mensagens) {
                            $scope.atendimentoSelecionado.mensagens = [];
                        }

                        //tratamento para mensagens do whatsapp com template
                        $scope.prepareTemplateData(data.messages);

                        // Valida se o botão de ir para baixo está habilitado e se ele não esta no fim da pagina
                        if ($scope.showButtonPageBottom && $scope.atendimentoSelecionado.status != 'POTENCIAL' && data.messages[0].tipo != "ATENDENTE") {

                            $scope.amountNewMessagesNotifications = ++$scope.amountNewMessagesNotifications;
                            $scope.controlePaginacao.mensagens.stopScrollDownLoading = false;


                        }

                        if (!$scope.specificSearch)
                            $scope.atendimentoSelecionado.mensagens = $scope.atendimentoSelecionado.mensagens.concat(data.messages);


                        if ($scope.isEmail()) {

                            $scope.atendimentoSelecionado.informacoes.usuario.cc = $scope.atendimentoSelecionado.mensagens[$scope.atendimentoSelecionado.mensagens.length - 1].cc;

                        } else {

                            $.each(data.messages, function (idx, file) {

                                var isImage = file.tipoMensagem === 'IMAGEM';
                                var isFile = ['DOCUMENTO', 'ARQUIVO', 'AUDIO', 'VIDEO'].includes(file.tipoMensagem);

                                if (file.tipoMensagem == 'TEMPLATE') {
                                    if (file.json && file.json.components) {
                                        let templateFiles = file.json.components.filter(c => c.type == 'HEADER' && c.parameters && c.parameters.filter(p => ['DOCUMENT', 'IMAGE', 'VIDEO'].includes(p.type)));

                                        if (templateFiles && templateFiles.length > 0) {
                                            let templateFile = templateFiles[0].parameters[0];

                                            if (templateFile) {
                                                isImage = templateFile.type === 'IMAGE';
                                                isFile = ['DOCUMENT', 'VIDEO'].includes(templateFile.type);

                                                file.nomePDF = templateFile.type === 'DOCUMENT' ? $scope.getFilenameLink(templateFile.text) : null;
                                                file.fileUrl = templateFile.text;
                                            }
                                        }
                                    }
                                }

                                if (isImage || isFile) {
                                    var newFile = {
                                        id: file.id,
                                        nome: file.nomePDF,
                                        url: file.fileUrl,
                                        dataCriacao: file.dataCriacao,
                                        tipo: file.tipo
                                    }
                                }

                                if (isImage) {

                                    if (!$scope.atendimentoSelecionado.informacoes.imagensCompartilhadas) {
                                        $scope.atendimentoSelecionado.informacoes.imagensCompartilhadas = [];
                                        $scope.previewGroup = [];
                                    }

                                    $scope.atendimentoSelecionado.informacoes.imagensCompartilhadas.push(newFile)
                                    $scope.previewGroup.push(newFile);

                                } else if (isFile) {

                                    if (!$scope.atendimentoSelecionado.informacoes.arquivosCompartilhados) {
                                        $scope.atendimentoSelecionado.informacoes.arquivosCompartilhados = [];
                                    }

                                    $scope.atendimentoSelecionado.informacoes.arquivosCompartilhados.push(newFile)

                                }

                            });

                        }

                        $scope.$apply();

                        //gambiarra pra jogar o scroll pra baixo
                        if (data.messages[0].tipo == "ATENDENTE" || (data.messages[0].tipo != "ATENDENTE" && !$scope.showButtonPageBottom)) {
                            setTimeout(function () {

                                $scope.goToBottomPage(false);
                            }, 100, false)
                        }

                        break;

                    case 'UPDATE_ITEM_STATUS':

                        //verificando se tem algum atendimento selecionado e se é o mesmo da mensagem
                        if (!$scope.atendimentoSelecionado || ($scope.atendimentoSelecionado.id != data.status.painelAtendimentoId)) {
                            return;
                        }

                        if ($scope.atendimentoSelecionado.mensagens) {
                            $.each($scope.atendimentoSelecionado.mensagens, function (i, m) {
                                if (m.id == data.status.id || m.originalId == data.status.id) {
                                    m.statusDate = data.status.date;
                                    m.status = data.status.status;
                                    m.statusMessage = data.status.message;
                                    m.uid = data.status.uid ? data.status.uid : m.uid;

                                    return;
                                }
                            });
                        }

                        break;

                    case 'UPDATE_ITEM':
                        // console.log("Chegou aquiii", data)
                        // Verificando se há atendimento selecionado e se é o mesmo da mensagem
                        if (
                            !$scope.atendimentoSelecionado ||
                            $scope.atendimentoSelecionado.id != data.messages[0].painelAtendimentoId
                        ) {
                            return;
                        }

                        if ($scope.atendimentoSelecionado.mensagens) {
                            $.each($scope.atendimentoSelecionado.mensagens, function (i, m) {
                                if (m.id == data.messages[0].id || m.originalId == data.messages[0].id) {
                                    $scope.atendimentoSelecionado.mensagens[i] = data.messages[0];
                                    return false; // quebrar o loop (como um 'break')
                                }
                            });
                        }

                        break;

                }

                break;

        }

    }

    $scope.startSocketUser = function () {

        if ($scope.onlyTicketChat) {
            return;
        }

        //FOLLOW-UPS

        let listenerFollowUps = SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/users/' + $scope.jwt.usuarioUuid + '/follow-ups', (data) => {

            SocketUtil.addLog('CLIENTS.USERS.FOLLOWUPS: ' + JSON.stringify(data));
            let socketEvent = () => { return $scope.runSocketUserFollowUps(data); }
            $scope.socketEvents.push(socketEvent);

        });

        $scope.socket.listeners.push(listenerFollowUps);

        //LEADS

        let listenerLeads = SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/users/' + $scope.jwt.usuarioUuid + '/leads', (data) => {

            SocketUtil.addLog('CLIENTS.USERS.LEADS: ' + JSON.stringify(data));
            let socketEvent = () => { return $scope.runSocketUserLeads(data) }
            $scope.socketEvents.push(socketEvent);

        });

        $scope.socket.listeners.push(listenerLeads);

        //TICKETS

        let listenerTickets = SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/users/' + $scope.jwt.usuarioUuid + '/tickets', (data) => {

            SocketUtil.addLog('CLIENTS.USERS.TICKETS: ' + JSON.stringify(data));
            let socketEvent = () => { return $scope.runSocketUserTickets(data); }
            $scope.socketEvents.push(socketEvent);

        });

        $scope.socket.listeners.push(listenerTickets);

        //DETAILS

        let listenerDetails = SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/users/' + $scope.jwt.usuarioUuid + '/details', (data) => {

            SocketUtil.addLog('CLIENTS.USERS.TICKETS: ' + JSON.stringify(data));
            let socketEvent = () => { return $scope.runSocketUserDetails(data); }
            $scope.socketEvents.push(socketEvent);

        });

        $scope.socket.listeners.push(listenerDetails);

        //ONLINE

        let listenerUserOnline = SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/users/' + $scope.jwt.usuarioUuid + '/online', (data) => {

            SocketUtil.addLog('CLIENTS.USERS.ONLINE: ' + JSON.stringify(data));
            $scope.atendente.status = data.online ? 'ONLINE' : 'OFFLINE';
            $rootScope.atendente.status = $scope.atendente.status;

            if (!data.online) {
                $scope.fecharAtendimento();
                $scope.clearSocketTicket();
            }

        });

        $scope.socket.listeners.push(listenerUserOnline);
    }

    $scope.runSocketUserFollowUps = function (data) {

        switch (data.type) {

            case 'FOLLOW_UP':

                //o evento só é processando quando terminar essas requisições, para não ter concorrência
                if ($scope.clientRealtimeDataCarregando || $scope.controlePaginacao.atendimentosRetornos.carregando || $scope.controlePaginacao.totalAtendimentosRetornos.carregando) {
                    console.log("waiting follow ups request...");
                    return true;
                }

                switch (data.eventType) {

                    case 'ADD_ITEM':

                        //verificando se já foi iniciado os registros
                        if (!$scope.atendimentosRetornos.registros) {
                            $scope.atendimentosRetornos.registros = [];
                        }

                        //verificando se o registro já está na lista
                        if ($scope.recuperarAtendimentoRetorno(data.ticket.id)) {
                            return;
                        }

                        //verificando se o id já está na lista de ids
                        if (!$scope.atendimentosRetornos.ids.has(data.ticket.id)) {

                            //adicionando na lista de ids
                            $scope.atendimentosRetornos.ids.set(data.ticket.id, data.ticket.id);

                            //verificando se o ticket está batendo com o filtro
                            if ($scope.isTicketFiltered(data.ticket)) {

                                //verificando se todos os registro estão na lista
                                if ($scope.atendimentosRetornos.total == 0 || $scope.atendimentosRetornos.total == $scope.atendimentosRetornos.registros.length) {

                                    //adicionado o ticket na lista
                                    $scope.atendimentosRetornos.registros.push(data.ticket);
                                    $scope.controlePaginacao.atendimentosRetornos.carregado = true;

                                    //ordenando a lista
                                    $scope.atendimentosRetornos.registros = $filter('orderBy')($scope.atendimentosRetornos.registros, 'dataCriacao', !$scope.controlePaginacao.atendimentosRetornos.orderByAsc);

                                }

                            }

                            //iterando no controle de totais
                            $scope.atendimentosRetornos.total++;

                            //atualizando o dashboard de métricas
                            $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 3, 1);

                        }

                        //controle para caso o usuário clique na notificação de followup
                        data.ticket.isFollowUpFromNotification = true;

                        //enviando notificação
                        $scope.verificarPermissaoNotificacao("FOLLOW_UP", $translate.instant('CHAT-NOVO-ATENDIMENTO-RETORNO'), data.ticket)

                        break;

                    case 'REMOVE_ITEM':

                        //verificando se o id já está na lista de ids
                        if (!$scope.atendimentosRetornos.ids.has(data.ticket.id)) {
                            return;
                        }

                        //removendo o atendimento
                        $scope.removerAtendimentoRetorno(data.ticket.id);

                        //atualizando o dashboard de métricas
                        $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 3, -1);

                        //verificando se é o atendimento selecionado
                        if ($scope.atendimentoSelecionado.id == data.ticket.id) {

                            //se estiver entre os ativos carregados, só tirar a flag
                            //caso o ticket esteja ativo mas fora da página, o REMOVE_ITEM do ACTIVE chegará depois e fechará
                            if ($scope.recuperarAtendimentoAtivo(data.ticket.id)) {

                                delete $scope.atendimentoSelecionado.isFollowUp;

                            } else {

                                //caso contrário, é realmente para remover
                                $scope.fecharAtendimento();
                                $scope.clearSocketTicket();
                            }
                        }

                        break;
                }

        }

    }

    $scope.runSocketUserLeads = function (data) {

        switch (data.type) {

            case 'LEAD':

                //o evento só é processando quando terminar essas requisições, para não ter concorrência
                if ($scope.clientRealtimeDataCarregando || $scope.controlePaginacao.atendimentosPotenciais.carregando || $scope.controlePaginacao.totalAtendimentosPotenciais.carregando) {
                    console.log("waiting leads request...");
                    return true;
                }

                switch (data.eventType) {

                    case 'ADD_ITEM':

                        //verificando se já foi iniciado os registros
                        if (!$scope.atendimentosPotenciais.registros) {
                            $scope.atendimentosPotenciais.registros = [];
                        }

                        //verificando se o registro já está na lista
                        if ($scope.recuperarAtendimentoPotencial(data.lead.id)) {
                            return;
                        }

                        //verificando se o id já está na lista de ids
                        if (!$scope.atendimentosPotenciais.ids.has(data.lead.id)) {

                            //adicionando na lista de ids
                            $scope.atendimentosPotenciais.ids.set(data.lead.id, data.lead.id);

                            //verificando se o lead está batendo com o filtro
                            if ($scope.isLeadFiltered(data.lead)) {

                                //verificando se todos os registro estão na lista
                                if ($scope.atendimentosPotenciais.total == 0 || $scope.atendimentosPotenciais.total == $scope.atendimentosPotenciais.registros.length) {

                                    //adicionado o lead na lista
                                    $scope.atendimentosPotenciais.registros.push(data.lead);
                                    $scope.controlePaginacao.atendimentosPotenciais.carregado = true;

                                    //ordenando a lista
                                    $scope.atendimentosPotenciais.registros = $filter('orderBy')($scope.atendimentosPotenciais.registros, 'dataCriacao', !$scope.controlePaginacao.atendimentosPotenciais.orderByAsc);

                                }

                            }

                            //iterando no controle de totais
                            $scope.atendimentosPotenciais.total++;

                            //atualizando o dashboard de métricas
                            $scope.clientRealtimeData.metrics.leads++;

                        }

                        //enviando notificação
                        $scope.verificarPermissaoNotificacao("LEAD", $translate.instant('CHAT-NOVO-ATENDIMENTO-POTENCIAL'), data.lead, null, null, null, true);

                        break;

                    case 'REMOVE_ITEM':

                        //verificando se o id já está na lista de ids
                        if (!$scope.atendimentosPotenciais.ids.has(data.lead.id)) {
                            return;
                        }

                        //removendo o atendimento
                        $scope.removerAtendimentoPotencial(data.lead.id);

                        //atualizando o dashboard de métricas
                        $scope.clientRealtimeData.metrics.leads--;

                        //verificando se possuem registros para serem listados, pra lista não ficar vazia
                        if ($scope.controlePaginacao.atendimentosPotenciais.carregado && $scope.atendimentosPotenciais.total > 0 && $scope.atendimentosPotenciais.total > $scope.atendimentosPotenciais.registros.length) {
                            $scope.recuperarProximoAtendimentoPotencial();
                        }

                        //verificando se o atendimento removido é o que está selecionado
                        if ($scope.atendimentoSelecionado.id == data.lead.id) {
                            $scope.fecharAtendimento();
                            $scope.clearSocketTicket();
                        }

                        break;

                }

                break;

        }

    }

    $scope.runSocketUserTickets = function (data) {

        switch (data.type) {

            case 'NEW_MESSAGES':

                //o evento só é processando quando terminar essas requisições, para não ter concorrência
                if ($scope.clientRealtimeDataCarregando || $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregando || $scope.controlePaginacao.totalAtendimentosAtivosNovasMensagens.carregando) {
                    console.log("waiting new messages tickets request...");
                    return true;
                }

                switch (data.eventType) {

                    case 'ADD_ITEM':

                        //verificando se é mensagem do atendimento selecionado
                        //só enviar lê as mensagens se for atendente
                        if ($scope.isAtendente() && $scope.atendimentoSelecionado.id == data.ticket.id) {
                            AtendimentoService.updateMensagensNaoLidas(data.ticket.id);
                            $timeout(function () {
                                $scope.sessionExpiredMode = false;
                            }, 1000);
                            return;
                        }

                        //verificando se já foi iniciado os registros
                        if (!$scope.atendimentosNovasMensagens.registros) {
                            $scope.atendimentosNovasMensagens.registros = [];
                        }

                        //verificando se o registro já está na lista
                        var atendimento = $scope.recuperarAtendimentoNovasMensagens(data.ticket.id);

                        if (atendimento) {
                            if (atendimento.mensagensNaoVisualizadas < 0) {
                                atendimento.mensagensNaoVisualizadas = 0;
                            }

                            atendimento.mensagensNaoVisualizadas++;
                            atendimento.dataUltimaMensagem = data.ticket.dataUltimaMensagem;

                            $scope.ordenarAtendimentosNovasMensagens();

                            //sincroniza dataUltimaMensagem na lista de ativos e reordena
                            //necessário pois para mensagens de arquivo o evento ACTIVE.UPDATE_ITEM pode não ser disparado
                            var atendimentoAtivo = $scope.recuperarAtendimentoAtivo(data.ticket.id);
                            if (atendimentoAtivo && data.ticket.dataUltimaMensagem) {
                                atendimentoAtivo.dataUltimaMensagem = data.ticket.dataUltimaMensagem;
                                $scope.ordenarAtendimentosAtivos();
                            }
                        } else {

                            //verificando se o ticket está batendo com o filtro
                            if ($scope.isTicketFiltered(data.ticket)) {

                                //verificando se todos os registro estão na lista
                                if ($scope.atendimentosNovasMensagens.total == 0 || $scope.atendimentosNovasMensagens.total == $scope.atendimentosNovasMensagens.registros.length) {

                                    //adicionando a quantidade de mensagens não lidas inicial
                                    data.ticket.mensagensNaoVisualizadas = 1;

                                    //adicionado o ticket na lista
                                    $scope.atendimentosNovasMensagens.registros.push(data.ticket);
                                    $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado = true;

                                    //ordenando a lista
                                    $scope.ordenarAtendimentosNovasMensagens();

                                }

                                //iterando no controle de totais
                                $scope.atendimentosNovasMensagens.total++;

                                //atualizando o título da aba do navegador
                                $scope.changeTitle();
                            }

                            //atualizando o dashboard de métricas
                            $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 0, 1);

                        }

                        //verificando se a mensagem é de um contato ou de outro atendente
                        //podem vir mensagens do próprio gestor/supervisor para ele mesmo, ai não deve notificar
                        if (!data.message.agentId || data.message.agentId != $scope.jwt.usuarioId) {

                            let body;
                            let image;

                            if (data.message.type === 'TEXTO') {

                                if (data.ticket.emailId) {
                                    body = $translate.instant('CHAT-NOVO-EMAIL');
                                } else {
                                    body = data.message.message;
                                }

                            } else if (data.message.type === 'IMAGEM') {

                                image = data.message.url;
                                body = undefined;

                            } else {

                                body = $translate.instant('CHAT-NOVA-MENSAGEM');

                            }

                            //enviando notificação
                            $scope.verificarPermissaoNotificacao("TICKET_ACTIVE", body, data.ticket, data.ticket.nome, data.ticket.imagemPerfil, image);

                        }

                        break;

                    case 'REMOVE_ITEM':

                        //removendo o atendimento
                        $scope.removerAtendimentoNovasMensagens(data.ticket.id);

                        //atualizando o dashboard de métricas
                        $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 0, -1);

                        //verificando se possuem registros para serem listados, pra lista não ficar vazia
                        if ($scope.atendimentosNovasMensagens.total > 0 && $scope.atendimentosNovasMensagens.total > $scope.atendimentosNovasMensagens.registros.length) {
                            $scope.recuperarProximoAtendimentoNovasMensagens();
                        }

                        break;

                }

                break;

            case 'ACTIVE':

                //o evento só é processando quando terminar essas requisições, para não ter concorrência
                if ($scope.clientRealtimeDataCarregando || $scope.controlePaginacao.atendimentosAtivos.carregando || $scope.controlePaginacao.totalAtendimentosAtivos.carregando) {
                    console.log("waiting active tickets request...");
                    return true;
                }

                switch (data.eventType) {

                    case 'ADD_ITEM':

                        //verificando se já foi iniciado os registros
                        if (!$scope.atendimentosAtivos.registros) {
                            $scope.atendimentosAtivos.registros = [];
                        }

                        //verificando se o registro já está na lista
                        if ($scope.recuperarAtendimentoAtivo(data.ticket.id)) {
                            return;
                        }

                        //verificando se o ticket está batendo com o filtro
                        if ($scope.isTicketFiltered(data.ticket)) {

                            //adicionado o ticket na lista (sempre, independente de paginação)
                            $scope.atendimentosAtivos.registros.push(data.ticket);
                            $scope.controlePaginacao.atendimentosAtivos.carregado = true;

                            //ordenando a lista
                            $scope.ordenarAtendimentosAtivos();

                            //iterando no controle de totais
                            $scope.atendimentosAtivos.total++;

                        }

                        //atualizando o dashboard de métricas
                        $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 1, 1);

                        //caso o atendimento tenha sido iniciado, não deverá ser notificado
                        if (($scope.isAtendente() && data.ticket.startedById) || (data.ticket.startedById == $scope.jwt.usuarioId)) {

                            //selecionando o atendimento
                            $scope.selecionarAtendimento(data.ticket);

                        } else {

                            if (!data.fromUpdateItem) {

                                //enviando notificação
                                $scope.verificarPermissaoNotificacao("TICKET_ACTIVE", $translate.instant('CHAT-NOVO-ATENDIMENTO-ATIVO'), data.ticket)

                            }

                        }

                        break;

                    case 'REMOVE_ITEM':

                        //removendo o atendimento
                        $scope.removerAtendimentoAtivo(data.ticket.id);

                        //atualizando o dashboard de métricas
                        $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 1, -1);

                        //verificando se possuem registros para serem listados, pra lista não ficar vazia
                        if ($scope.controlePaginacao.atendimentosAtivos.carregado && $scope.atendimentosAtivos.total > 0 && $scope.atendimentosAtivos.total > $scope.atendimentosAtivos.registros.length) {
                            $scope.recuperarProximoAtendimentoAtivo();
                        }

                        //verificando se o atendimento removido é o que está selecionado
                        if ($scope.atendimentoSelecionado.id == data.ticket.id) {
                            $scope.fecharAtendimento();
                            $scope.clearSocketTicket();
                        }

                        break;

                    case 'UPDATE_ITEM_ADD_UNREAD_MESSAGES':

                        //verificando se é mensagem do atendimento selecionado
                        if ($scope.isAtendente() && $scope.atendimentoSelecionado.id == data.ticket.id) {
                            return;
                        }

                        var atendimento = $scope.recuperarAtendimentoAtivo(data.ticket.id);

                        if (atendimento) {
                            if (atendimento.mensagensNaoVisualizadas < 0) {
                                atendimento.mensagensNaoVisualizadas = 0;
                            }

                            atendimento.mensagensNaoVisualizadas++;
                        }

                        break;

                    case 'UPDATE_ITEM_CLEAR_UNREAD_MESSAGES':

                        var atendimento = $scope.recuperarAtendimentoAtivo(data.ticket.id);

                        if (atendimento) {
                            atendimento.mensagensNaoVisualizadas = 0;
                        }

                        break;

                    case 'UPDATE_ITEM':

                        //OK - nova mensagem do contato
                        //OK - nova mensagem do participante
                        //TODO - crud de tag
                        //TODO - fixado
                        //TODO - atualização do nome
                        //TODO - atualização da foto                        

                        var atendimento = $scope.recuperarAtendimentoAtivo(data.ticket.id);

                        if (atendimento) {

                            //apenas atualiza o registro
                            atendimento.dataUltimaMensagem = data.ticket.dataUltimaMensagem;
                            $scope.ordenarAtendimentosAtivos();

                        } else {

                            //adiciona o item na lista

                            let addItemData = { ...data };
                            addItemData.eventType = 'ADD_ITEM';
                            addItemData.fromUpdateItem = true;

                            //verificar o impacto
                            $scope.runSocketUserTickets(addItemData);

                        }

                        break;

                }

                break;

            case 'PENDING':

                //o evento só é processando quando terminar essas requisições, para não ter concorrência
                if ($scope.clientRealtimeDataCarregando || $scope.controlePaginacao.atendimentosPendentes.carregando || $scope.controlePaginacao.totalAtendimentosPendentes.carregando) {
                    console.log("waiting pending tickets request...");
                    return true;
                }

                switch (data.eventType) {

                    case 'ADD_ITEM':

                        //verificando se já foi iniciado os registros
                        if (!$scope.atendimentosPendentes.registros) {
                            $scope.atendimentosPendentes.registros = [];
                        }

                        //verificando se o registro já está na lista
                        if ($scope.recuperarAtendimentoPendente(data.ticket.id)) {
                            return;
                        }

                        //verificando se o id já está na lista de ids
                        if (!$scope.atendimentosPendentes.ids.has(data.ticket.id)) {

                            //adicionando na lista de ids
                            $scope.atendimentosPendentes.ids.set(data.ticket.id, data.ticket.id);

                            //verificando se o ticket está batendo com o filtro
                            if ($scope.isTicketFiltered(data.ticket)) {

                                //adicionado o ticket na lista (sempre, independente de paginação)
                                $scope.atendimentosPendentes.registros.push(data.ticket);
                                $scope.controlePaginacao.atendimentosPendentes.carregado = true;

                                //ordenando a lista, caso esteja desc
                                $scope.ordenarAtendimentosPendentes();

                                //iterando no controle de totais
                                $scope.atendimentosPendentes.total++;

                            }

                            //atualizando o dashboard de métricas
                            $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 2, 1);

                        }

                        //enviando notificação
                        $scope.verificarPermissaoNotificacao("TICKET_PENDING", $translate.instant('CHAT-NOVO-ATENDIMENTO-PENDENTE'), data.ticket)

                        break;

                    case 'REMOVE_ITEM':

                        //verificando se o id já está na lista de ids
                        if (!$scope.atendimentosPendentes.ids.has(data.ticket.id)) {
                            return;
                        }

                        //removendo o atendimento
                        $scope.removerAtendimentoPendente(data.ticket.id);

                        //atualizando o dashboard de métricas
                        $scope.setMetrics(data.ticket.departamentoId, data.ticket.atendenteId, 2, -1);

                        //verificando se possuem registros para serem listados, pra lista não ficar vazia
                        if ($scope.controlePaginacao.atendimentosPendentes.carregado && $scope.atendimentosPendentes.total > 0 && $scope.atendimentosPendentes.total > $scope.atendimentosPendentes.registros.length) {
                            $scope.recuperarProximoAtendimentoPendente();
                        }

                        //verificando se é uma exclusão de iniciar o atendimento
                        if (data.ticket.startedById != $scope.jwt.usuarioId) {

                            //verificando se o atendimento removido é o que está selecionado
                            if ($scope.atendimentoSelecionado.id == data.ticket.id) {
                                $scope.fecharAtendimento();
                                $scope.clearSocketTicket();
                            }

                        }

                        break;

                }

                break;

        }

    }

    $scope.runSocketUserDetails = function (data) {

        switch (data.type) {

            case 'AGENT_STATUS':

                switch (data.eventType) {

                    case 'REMOVE_ITEM':

                        if (data.agentStatus) {
                            data.agentStatus.online ? $scope.clientRealtimeData.metrics.agentsOnline++ : $scope.clientRealtimeData.metrics.agentsOnline--;
                        }

                        break;
                }

                break;

        }

    }

    $scope.ordenarAtendimentosAtivos = function () {
        var field = $scope.permissions.ticketActiveOrderBy == 'CREATE_DATE' ? 'dataCriacao' : 'dataUltimaMensagem';
        var orderBy = ($scope.controlePaginacao.atendimentosAtivos.orderByAsc ? '' : '-') + field;

        $scope.atendimentosAtivos.registros = $filter('orderBy')($scope.atendimentosAtivos.registros, ['fixado', orderBy]);
    }

    $scope.ordenarAtendimentosNovasMensagens = function () {
        var field = $scope.permissions.ticketActiveOrderBy == 'CREATE_DATE' ? 'dataCriacao' : 'dataUltimaMensagem';
        $scope.atendimentosNovasMensagens.registros = $filter('orderBy')($scope.atendimentosNovasMensagens.registros, field, !$scope.controlePaginacao.atendimentosAtivosNovasMensagens.orderByAsc);
    }

    $scope.ordenarAtendimentosPendentes = function () {
        var field = $scope.permissions.ticketActiveOrderBy == 'CREATE_DATE' ? 'dataCriacao' : 'dataUltimaMensagem';
        $scope.atendimentosPendentes.registros = $filter('orderBy')($scope.atendimentosPendentes.registros, field, !$scope.controlePaginacao.atendimentosPendentes.orderByAsc);
    }

    $scope.iniciarFirebase = function () {
        if ($scope.onlyTicketChat) {
            return;
        }

        $scope.iniciarFirebaseCliente();
    };

    $scope.getFilenameLink = function (link) {
        if (!link || link == "") {
            return link;
        }

        let splittedLink = link.split("/");

        if (splittedLink.length > 1) {
            let splittedFilename = splittedLink[splittedLink.length - 1].split("\.");

            if (splittedFilename.length > 1) {
                return splittedLink[splittedLink.length - 1];
            }
        }

        return null;
    };

    $scope.isTicketFiltered = (ticket) => {
        let filter = $scope.getFilter();
        let isFiltered = true;

        //filtros específicos

        if (isFiltered && filter.atendenteId) isFiltered = ticket.atendenteId == filter.atendenteId;
        if (isFiltered && filter.canal) isFiltered = ticket.canal.toUpperCase().indexOf(filter.canal.toUpperCase()) > -1; //TODO - trocar por botId
        if (isFiltered && filter.nome && ticket.nome) isFiltered = ticket.nome.toUpperCase().indexOf(filter.nome.toUpperCase()) > -1;
        if (isFiltered && filter.contato) isFiltered = ticket.contatoTelefone.toUpperCase().indexOf(filter.contato.toUpperCase()) > -1;
        if (isFiltered && filter.departamentosId) isFiltered = filter.departamentosId.some(d => d == ticket.departamentoId);
        if (isFiltered && filter.tags && ticket.tags) isFiltered = filter.tags.some(t => ticket.tags.some(tt => tt == t));

        //filtro genérico

        if (isFiltered && filter.filtro) isFiltered = ticket.canal.toUpperCase().indexOf(filter.filtro) > -1 || ticket.nome.toUpperCase().indexOf(filter.filtro) > -1 || ticket.contatoTelefone.toUpperCase().indexOf(filter.filtro) > -1 || ticket.departamentoNome.toUpperCase().indexOf(filter.filtro) > -1;

        return isFiltered;
    }

    $scope.isLeadFiltered = (lead) => {
        let filter = $scope.getFilter();
        let isFiltered = true;

        //filtros específicos

        if (isFiltered && filter.canal) isFiltered = lead.telefoneCliente == filter.canal
        if (isFiltered && filter.nome) isFiltered = lead.usuario == filter.nome;
        if (isFiltered && filter.contato) isFiltered = lead.telefoneUsuario == filter.contato;

        //filtro genérico

        if (isFiltered && filter.filtro) isFiltered = lead.usuario.toUpperCase().indexOf(filter.filtro) > -1 || lead.telefoneUsuario.toUpperCase().indexOf(filter.filtro) > -1;

        return isFiltered;
    }

    $scope.recuperarRecados = function (reset, enviarNotificacao) {
        if ($scope.onlyTicketChat) {
            return;
        }

        if ($scope.controlePaginacao.recados.carregando) {
            return;
        }

        $scope.controlePaginacao.recados.carregando = true;

        if (reset) {
            $scope.controlePaginacao.recados.offset = 0;
        } else {
            $scope.controlePaginacao.recados.offset = $scope.recados.registros.length;
        }

        var filtro = {
            offset: $scope.controlePaginacao.recados.offset,
            limit: $scope.controlePaginacao.recados.limit
        };

        RecadoService.getAguardando(filtro).then(function (response) {
            if (reset) {
                $scope.recados = response.data;

                if (enviarNotificacao && $scope.recados.total > 0) {
                    $scope.verificarPermissaoNotificacao("SCRAP", $translate.instant('CHAT-NOVO-RECADO'))
                }
            } else {
                $scope.recados.total = response.data.total;
                $scope.recados.registros = $scope.recados.registros.concat(response.data.registros);
            }

            $scope.controlePaginacao.recados.carregando = false;
        });
    };

    $scope.startInfinityScroll = function () {

        //RECADOS
        $('#recados').scroll(function (e) {
            if ($scope.controlePaginacao.recados.stopScrollLoading) {
                return;
            }

            if ($(e.target).scrollLeft() > $(e.target).prop('scrollWidth') - 500) {
                $scope.recuperarRecados(false, false);
            }
        });

        //ATENDIMENTOS ATIVOS NOVAS MENSAGENS
        $('#atendimentos-ativos-novas-mensagens').scroll(function (e) {
            if ($scope.controlePaginacao.atendimentosAtivosNovasMensagens.stopScrollLoading) {
                return;
            }

            if ($(e.target).prop('scrollHeight') - $(e.target).prop('clientHeight') - $(e.target).scrollTop() < 100) {
                $scope.recuperarAtendimentosAtivosNovasMensagens(false);
            }
        });

        //ATENDIMENTOS ATIVOS        
        $('#atendimentos-ativos').scroll(function (e) {
            if ($scope.controlePaginacao.atendimentosAtivos.stopScrollLoading) {
                return;
            }

            if ($(e.target).prop('scrollHeight') - $(e.target).prop('clientHeight') - $(e.target).scrollTop() < 100) {
                $scope.recuperarAtendimentosAtivos(false);
            }
        });

        //ATENDIMENTOS PENDENTES
        $('#atendimentos-pendentes').scroll(function (e) {
            if ($scope.controlePaginacao.atendimentosPendentes.stopScrollLoading) {
                return;
            }

            if ($(e.target).prop('scrollHeight') - $(e.target).prop('clientHeight') - $(e.target).scrollTop() < 100) {
                $scope.recuperarAtendimentosPendentes(false);
            }
        });

        //ATENDIMENTOS POTENCIAIS
        $('#atendimentos-potenciais').scroll(function (e) {
            if ($scope.controlePaginacao.atendimentosPotenciais.stopScrollLoading) {
                return;
            }

            if ($(e.target).prop('scrollHeight') - $(e.target).prop('clientHeight') - $(e.target).scrollTop() < 100) {
                $scope.recuperarAtendimentosPotenciais(false);
            }
        });


        let previousScrollTop = 0; // Armazena a posição anterior do scroll
        const debounce = (fn, delay) => {
            let timeout;
            return function (...args) {
                clearTimeout(timeout);
                timeout = setTimeout(() => fn.apply(this, args), delay);
            };
        };

        $scope.showButtomBottom = (currentScrollTop, contentHeight, scrollHeight) => {

            if ($scope.controlePaginacao.mensagens.scrollLoadingAutomatic)
                return;

            var pixelScrolledToUp = 50;
            var totalScrolledToUp = currentScrollTop + contentHeight + pixelScrolledToUp;

            if (totalScrolledToUp <= scrollHeight) {
                $scope.showButtonPageBottom = true;
            } else {
                $scope.amountNewMessagesNotifications = 0;
                $scope.showButtonPageBottom = false;

            }
            $scope.$apply();

        }


        $scope.goToBottomPage = (animation = true) => {
            $scope.showButtonPageBottom = false;
            $scope.amountNewMessagesNotifications = 0;
            $scope.controlePaginacao.mensagens.scrollLoadingAutomatic = true;

            var $contentCenter = $(".content-center");

            var scrollTop = $contentCenter.prop('scrollHeight');

            if (!animation) {
                $contentCenter.scrollTop(scrollTop);
                return;
            }

            $contentCenter.animate({ scrollTop: scrollTop }, 800, function () {
                if ($scope.atendimentoSelecionado.status != 'POTENCIAL' && $scope.specificSearch)
                    $scope.selecionarAtendimento($scope.atendimentoSelecionado);

                $scope.specificSearch = false;
            });
        }


        const handleScroll = (e) => {

            const $contentCenter = $(".content-center");
            const currentScrollTop = $(e.target).scrollTop(); // Posição atual do scroll
            const scrollHeight = $contentCenter[0].scrollHeight;
            const contentHeight = $contentCenter.height();

            if ($scope.controlePaginacao.mensagens.scrollLoadingAutomatic) {
                $scope.controlePaginacao.mensagens.scrollLoadingAutomatic = false;
                previousScrollTop = currentScrollTop;
                return;
            }

            $scope.showButtomBottom(currentScrollTop, contentHeight, scrollHeight);

            if (currentScrollTop < 900 && !$scope.controlePaginacao.mensagens.stopScrollLoading && !$scope.controlePaginacao.mensagens.carregando) {
                if ($scope.atendimentoSelecionado.status != 'POTENCIAL') {
                    $scope.showButtonPageBottom = true;
                }

                $scope.recuperarMensagens(true);
            }

            if (currentScrollTop > previousScrollTop && currentScrollTop + contentHeight >= scrollHeight - 900) {
                $scope.recuperarMensagens(false, 0, false, false, false, true);
            }

            previousScrollTop = currentScrollTop; // Atualiza a posição anterior do scroll
        };

        // Adiciona debounce para melhorar o desempenho
        $('#atendimento-mensagens').on('scroll', (debounce(handleScroll, 100)));

        //Contatos Favoritos
        $('#contato-container').scroll((e) => {

            switch ($scope.abaContatos) {
                case 'ATENDENTE':
                    if ($scope.controlePaginacao.agenda.favoritos.stopScrollLoading || $scope.controlePaginacao.agenda.favoritos.carregando) {
                        return;
                    }
                    break
                case 'DEPARTAMENTO':
                    if ($scope.controlePaginacao.agenda.contatos.stopScrollLoading || $scope.controlePaginacao.agenda.contatos.carregando) {
                        return;
                    }
                    break
                case 'BOT':
                    if ($scope.controlePaginacao.agenda.bots.stopScrollLoading || $scope.controlePaginacao.agenda.bots.carregando) {
                        return;
                    }
                    break
            }

            if ($(e.target).prop('scrollHeight') - $(e.target).prop('clientHeight') - $(e.target).scrollTop() < 100) {
                $scope.getAgenda(false, $scope.abaContatos);
            }
        });

    };

    $scope.trocarAbaAtendimentos = function (aba) {
        if ($scope.abaAtendimentos != aba) {
            $scope.abaAtendimentos = aba;

            switch ($scope.abaAtendimentos) {
                case 'NOVAS_MENSAGENS':
                    if (!$scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado) {
                        //$scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado = true;
                        $scope.recuperarAtendimentosAtivosNovasMensagens(true)
                    }
                    break;
                case 'ATIVOS':
                    if (!$scope.controlePaginacao.atendimentosAtivos.carregado) {
                        //$scope.controlePaginacao.atendimentosAtivos.carregado = true;
                        $scope.recuperarAtendimentosAtivos(true)
                    }
                    break;
                case 'PENDENTES':
                    if (!$scope.controlePaginacao.atendimentosPendentes.carregado) {
                        //$scope.controlePaginacao.atendimentosPendentes.carregado = true;
                        $scope.recuperarAtendimentosPendentes(true);
                    }
                    break;
                case 'POTENCIAIS':
                    if (!$scope.controlePaginacao.atendimentosPotenciais.carregado) {
                        //$scope.controlePaginacao.atendimentosPotenciais.carregado = true;
                        $scope.recuperarAtendimentosPotenciais(true);
                    }
                    break;
                case 'RETORNOS':
                    if (!$scope.controlePaginacao.atendimentosRetornos.carregado) {
                        //$scope.controlePaginacao.atendimentosRetornos.carregado = true;
                        $scope.recuperarAtendimentosRetornos(true)
                    }
                    break;
            }

        } else {
            switch ($scope.abaAtendimentos) {
                case 'ATIVOS':
                    $scope.controlePaginacao.atendimentosAtivos.orderByAsc = !$scope.controlePaginacao.atendimentosAtivos.orderByAsc;

                    if ($scope.controlePaginacao.atendimentosAtivos.carregado && $scope.atendimentosAtivos.registros.length === $scope.atendimentosAtivos.total) {
                        var oderBy = $scope.controlePaginacao.atendimentosAtivos.orderByAsc ? '' : '-';
                        $scope.atendimentosAtivos.registros = $filter('orderBy')($scope.atendimentosAtivos.registros, ['fixado', oderBy + 'dataCriacao'],);
                    } else {
                        $scope.recuperarAtendimentosAtivos(true)
                    }

                    break;
                case 'PENDENTES':
                    $scope.controlePaginacao.atendimentosPendentes.orderByAsc = !$scope.controlePaginacao.atendimentosPendentes.orderByAsc;

                    if ($scope.controlePaginacao.atendimentosPendentes.carregado && $scope.atendimentosPendentes.registros.length === $scope.atendimentosPendentes.total) {
                        $scope.ordenarAtendimentosPendentes();
                    } else {
                        $scope.recuperarAtendimentosPendentes(true);
                    }

                    break;
                case 'POTENCIAIS':
                    $scope.controlePaginacao.atendimentosPotenciais.orderByAsc = !$scope.controlePaginacao.atendimentosPotenciais.orderByAsc;

                    if ($scope.controlePaginacao.atendimentosPotenciais.carregado && $scope.atendimentosPotenciais.registros.length === $scope.atendimentosPotenciais.total) {
                        $scope.atendimentosPotenciais.registros = $filter('orderBy')($scope.atendimentosPotenciais.registros, 'dataCriacao', !$scope.controlePaginacao.atendimentosPotenciais.orderByAsc);
                    } else {
                        $scope.recuperarAtendimentosPotenciais(true);
                    }

                    break;
            }
        }
    };

    $scope.recuperarTotalAtendimentosAtivosNovasMensagens = function () {
        if ($scope.controlePaginacao.totalAtendimentosAtivosNovasMensagens.carregando) {
            return;
        }

        $scope.controlePaginacao.totalAtendimentosAtivosNovasMensagens.carregando = true;

        AtendimentoService.getAtendimentosAtivos($scope.getFilter(), $scope.controlePaginacao.atendimentosAtivosNovasMensagens.offset, true, $scope.controlePaginacao.atendimentosAtivosNovasMensagens.orderByAsc, true).then(function (response) {
            $scope.atendimentosNovasMensagens.total = response.data.total;
            $scope.changeTitle();

            $scope.controlePaginacao.totalAtendimentosAtivosNovasMensagens.carregando = false;
        });
    }

    $scope.recuperarAtendimentosAtivosNovasMensagens = function (reset, fromFirebase) {
        if ($scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregando) {
            return;
        }

        if (!reset && $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado && $scope.atendimentosNovasMensagens.registros.length === $scope.atendimentosNovasMensagens.total) {
            return;
        }

        $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregando = true;

        if (reset) {
            $scope.controlePaginacao.atendimentosAtivosNovasMensagens.offset = 0;
        } else if (!fromFirebase) {
            $scope.controlePaginacao.atendimentosAtivosNovasMensagens.offset = $scope.atendimentosNovasMensagens.registros.length;
        }

        AtendimentoService.getAtendimentosAtivos($scope.getFilter(), $scope.controlePaginacao.atendimentosAtivosNovasMensagens.offset, true, $scope.controlePaginacao.atendimentosAtivosNovasMensagens.orderByAsc).then(function (response) {
            if (reset) {
                $scope.atendimentosNovasMensagens.registros = response.data.registros;
            } else {
                if (response.data.registros && response.data.registros.length > 0) {
                    $scope.atendimentosNovasMensagens.registros = $scope.atendimentosNovasMensagens.registros.concat(response.data.registros);
                }
            }

            $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregando = false;

            $scope.changeTitle();
        });
    };

    $scope.changeTitle = function () {
        if ($scope.atendimentosNovasMensagens.registros && $scope.atendimentosNovasMensagens.total > 0) {
            document.title = "(" + $scope.atendimentosNovasMensagens.total + ") " + $scope.customizacao.nome;
        } else {
            document.title = $scope.customizacao.nome;
        }
    };

