    $scope.getMensagensFiltradas = function (reset) {
        if ($scope.mensagemFiltroTexto.length < 3) {
            return;
        }

        $scope.showMaisMensagensFiltradas = false;
        $scope.showCarregandoMensagensFiltradas = true;

        if (reset) {
            $scope.mensagensFiltradas = [];
            $scope.mensagemFiltroOffset = 0;
        } else {
            $scope.mensagemFiltroOffset += 20;
        }

        AtendimentoService.getMensagensFiltradas($scope.atendimentoSelecionado.id, $scope.mensagemFiltroTexto, $scope.mensagemFiltroOffset).then(function (response) {
            $scope.mensagensFiltradas = $scope.mensagensFiltradas.concat(response.data);
            $scope.showMaisMensagensFiltradas = response.data.length == 20;
            $scope.showCarregandoMensagensFiltradas = false;
        });
    };

