    $scope.getTypeFilterPagination = (appendOnTop, appendOnDown, bothFilter) => {

        if (bothFilter) {
            //Caso tenha feito uma pesquisa com both, fez uma busca por uma mensagem especifica e o chat tras algumas mensagens antes e após; 
            $scope.specificSearch = true;
            return $scope.paginationDownUpEnum = 'BOTH'
        }

        if (appendOnDown)
            return $scope.paginationDownUpEnum = 'DOWN'


        return $scope.paginationDownUpEnum = 'UP'

    }

    //a consulta de mensagens ordena e pagina por (data_criacao, id), então essa é a chave
    //que o front tem que usar para ordenar e para escolher o cursor da paginação
    const compararMensagensPorChave = function (a, b) {
        const dataA = a.dataCriacao || 0;
        const dataB = b.dataCriacao || 0;

        return dataA !== dataB ? dataA - dataB : a.id - b.id;
    };

    $scope.recuperarMensagens = function (appendOnTop, ultimaMensagemId, callback, originalId, originalIdOrigem, appendOnDown, bothFilter) {

        if ($scope.controlePaginacao.mensagens.carregando || $scope.atendimentoSelecionado.id === undefined) {
            return;
        }

        var $mensagens = $('#atendimento-mensagens');
        let oldScroll = $mensagens.prop('scrollHeight');

        $scope.controlePaginacao.mensagens.carregando = true;
        $scope.controlePaginacao.mensagens.appendOnTop = appendOnTop;

        let ultimaMensagemDataCriacao = 0;
        if (!ultimaMensagemId && originalId == undefined) {
            ultimaMensagemId = !appendOnTop && $scope.atendimentoSelecionado.mensagens.length ? $scope.atendimentoSelecionado.mensagens[$scope.atendimentoSelecionado.mensagens.length - 1].id : 0;
        }

        if (!appendOnTop) {
            $scope.controlePaginacao.mensagens.offset = 0;
        }

        var logica = function (response, scrolingDown) {

            if ($scope.atendimentoSelecionado.mensagens.length === 0 && response.data.length < $scope.controlePaginacao.mensagens.limit) {
                $scope.controlePaginacao.mensagens.carregando = false;
                $scope.controlePaginacao.mensagens.stopScrollLoading = true;
            }

            $scope.controlePaginacao.mensagens.offset += response.data.length;

            if (response.data.length > 0) {
                let novasMensagens = [...response.data].sort(compararMensagensPorChave);

                //descartando o que já está na tela para não duplicar mensagem em nenhum cenário
                const idsCarregados = new Set($scope.atendimentoSelecionado.mensagens.map(m => m.id));
                novasMensagens = novasMensagens.filter(m => !idsCarregados.has(m.id));

                // Tratamento para mensagens template
                $scope.prepareTemplateData(novasMensagens);

                if (appendOnTop) {
                    $scope.atendimentoSelecionado.mensagens = novasMensagens.concat($scope.atendimentoSelecionado.mensagens);

                    if (!callback) {
                        $scope.controlePaginacao.mensagens.carregando = false;
                        $scope.controlePaginacao.mensagens.stopScrollLoading = false;

                        if ($mensagens.scrollTop() == 0) {
                            $timeout(() => {
                                let lastMessageDiv = document.getElementById(`msg-${ultimaMensagemId}`);

                                if (lastMessageDiv) {
                                    lastMessageDiv.scrollIntoView();
                                } else {
                                    let newScroll = $mensagens.prop('scrollHeight');
                                    $mensagens.scrollTop(newScroll - oldScroll);
                                }
                            }, 100);
                        }

                    }
                } else {
                    $scope.atendimentoSelecionado.mensagens = $scope.atendimentoSelecionado.mensagens.concat(novasMensagens);

                    if (!callback) {
                        $scope.controlePaginacao.mensagens.carregando = false;

                        $timeout(function () {
                            $scope.controlePaginacao.mensagens.scrollLoadingAutomatic = true;

                            if (!appendOnDown)
                                $mensagens.scrollTop($mensagens.prop('scrollHeight'));

                            $scope.controlePaginacao.mensagens.stopScrollLoading = false;
                            $scope.$apply();
                        }, 100, false);
                    }
                }

                if ($scope.isEmail() && $scope.atendimentoSelecionado.mensagens) {
                    $scope.previewGroup = [];
                    var i = 0;

                    for (var mensagem of $scope.atendimentoSelecionado.mensagens) {
                        if (mensagem.anexos) {
                            for (var anexo of mensagem.anexos) {
                                anexo.id = ++i;
                                $scope.previewGroup.push({ id: anexo.id, url: anexo.url })
                            }
                        }
                    }
                }

                $scope.controlePaginacao.mensagens.stopScrollLoading = false;
            } else if (response.data.length <= 0) {
                if (appendOnTop && !callback) {
                    $scope.controlePaginacao.mensagens.stopScrollLoading = true;

                    $timeout(function () {
                        $scope.controlePaginacao.mensagens.scrollLoadingAutomatic = false;
                    }, 200, false);
                }

                $scope.controlePaginacao.mensagens.carregando = false;
            }

            let fileInput = document.getElementById("fileInput");

            if (fileInput) {
                fileInput.removeEventListener('change', insertFile);
                fileInput.addEventListener('change', insertFile);
            }

            if (callback) {
                callback();
            }

            if (response.data.length < $scope.controlePaginacao.mensagens.limit) {
                if (scrolingDown) {
                    $scope.controlePaginacao.mensagens.stopScrollDownLoading = true;
                }
            }
        };

        if ($scope.atendimentoSelecionado.status == 'POTENCIAL') {
            ContatoService.getMensagens($scope.atendimentoSelecionado.id, ultimaMensagemId, $scope.controlePaginacao.mensagens.offset, $scope.controlePaginacao.mensagens.limit, originalId).then(function (response) {
                try {
                    logica(response, appendOnDown);
                } finally {
                    $scope.controlePaginacao.mensagens.carregando = false;
                }
            }, function (err) {
                if (err.data.data && err.data.data.code === 'INVALID_AGENT') {
                    $scope.removerAtendimentoPendente($scope.atendimentoSelecionado.id);
                }

                $scope.fecharAtendimento();
                $scope.controlePaginacao.mensagens.carregando = false;
            });
        } else {

            let filtroMensagemId = ultimaMensagemId;

            if ($scope.atendimentoSelecionado.mensagens.length > 0) {
                //o cursor tem que ser a mensagem extrema pela MESMA chave da consulta (data_criacao, id).
                //usando só o menor/maior id, mensagens gravadas fora da ordem de id (imagens em sequência
                //entram depois, porque o arquivo é baixado antes de gravar, mas mantêm a data original)
                //fazem o filtro não avançar e a API devolve as mesmas mensagens indefinidamente
                const mensagemCursor = $scope.atendimentoSelecionado.mensagens.reduce((extremo, atual) => {
                    const diferenca = compararMensagensPorChave(atual, extremo);
                    return appendOnDown ? (diferenca > 0 ? atual : extremo) : (diferenca < 0 ? atual : extremo);
                }, $scope.atendimentoSelecionado.mensagens[0]);

                originalIdOrigem = 0;
                originalId = 0;

                //os dois filtros vão juntos e da mesma mensagem: a API compara a tupla (data_criacao, id),
                //o que garante que a paginação sempre avança mesmo com mensagens na mesma data de criação
                filtroMensagemId = mensagemCursor.id;
                ultimaMensagemDataCriacao = mensagemCursor.dataCriacao || 0;
            }

            let paginationDownUpEnum = $scope.getTypeFilterPagination(appendOnTop, appendOnDown, bothFilter);

            AtendimentoService.getMensagensPagination($scope.atendimentoSelecionado.id, filtroMensagemId, ultimaMensagemDataCriacao, $scope.controlePaginacao.mensagens.offset,
                $scope.controlePaginacao.mensagens.limit, originalId, originalIdOrigem, paginationDownUpEnum)
                .then(function (response) {
                    try {
                        logica(response, appendOnDown);
                    } finally {
                        $scope.controlePaginacao.mensagens.carregando = false;
                    }
                }, function (err) {
                    if (err.data.data && err.data.data.code === 'INVALID_AGENT') {
                        $scope.removerAtendimentoPendente($scope.atendimentoSelecionado.id);
                    }

                    $scope.fecharAtendimento();
                    $scope.controlePaginacao.mensagens.carregando = false;
                });
        }
    };

    function insertFile() {
        let files = fileInput.files;
        for (const f of files) {
            $scope.readFile(f);
        }
    };

    $scope.selectPreviousEmojiTab = () => {
        $scope.selectEmojiTab($scope.emojiListControl.activeTab - 1);
    }

    $scope.selectNextEmojiTab = () => {
        $scope.selectEmojiTab($scope.emojiListControl.activeTab + 1);
    }

    $scope.selectEmojiTab = (index) => {
        index = index < 0
            ? 0
            : index > $scope.emojiList.length - 1
                ? $scope.emojiList.length - 1
                : index;

        $scope.emojiListControl.activeTab = index
        $scope.emojiListControl.emojis = $scope.emojiList[index].emojis;
    }

    $scope.toggleEmojiList = () => $scope.emojiListControl.opened = !$scope.emojiListControl.opened;

    $scope.getEmojiList = () => {
        if (!$localStorage.recentEmojis) {
            $localStorage.recentEmojis = []
        } else {
            $scope.emojiListControl.recentEmojis = $localStorage.recentEmojis;
        }
        const data = $resource("data/emoji.json").get()
        data.$promise.then(res => {
            let emojis = res.emojis;
            let emojiList = emojis.reduce((groups, item) => ({
                ...groups,
                [item.category]: [...(groups[item.category] || []), item]
            }), {});

            $scope.emojiList = [];
            Object.keys(emojiList).forEach(c => {
                $scope.emojiList.push({ name: c, icon: emojiList[c][0].emoji, emojis: emojiList[c] })
            })

            $scope.selectEmojiTab(0);
        })
    }

    $scope.onSelecionarEmoji = (emoji) => {
        $scope.novaMensagem.mensagem ? $scope.novaMensagem.mensagem += emoji : $scope.novaMensagem.mensagem = emoji;

        if ($localStorage.recentEmojis.some(a => a == emoji)) {
            $localStorage.recentEmojis.splice($localStorage.recentEmojis.findIndex(a => a == emoji), 1)
        }

        $localStorage.recentEmojis = [emoji, ...$localStorage.recentEmojis];

        if ($localStorage.recentEmojis.length > 40) {
            $localStorage.recentEmojis = $localStorage.recentEmojis.slice(0, 50)
        }

        $scope.emojiListControl.recentEmojis = $localStorage.recentEmojis;
    }

    $scope.atualizarAtendimentos = function (ignoreTotais) {
        if ($scope.onlyTicketChat) {
            return;
        }

        $scope.atendimentosNovasMensagens.registros = [];
        $scope.atendimentosAtivos.registros = [];
        $scope.atendimentosPendentes.registros = [];
        $scope.atendimentosRetornos.registros = [];
        $scope.atendimentosPotenciais.registros = [];

        switch ($scope.abaAtendimentos) {
            case 'NOVAS_MENSAGENS':

                $scope.recuperarAtendimentosAtivosNovasMensagens(true);

                if (!ignoreTotais) {
                    $scope.recuperarTotalAtendimentosAtivosNovasMensagens();
                    $scope.recuperarTotalAtendimentosAtivos();
                    $scope.recuperarTotalAtendimentosPendentes();
                    $scope.recuperarTotalAtendimentosRetornos();

                    if ($rootScope.atendente.potenciais === true) {
                        $scope.recuperarTotalAtendimentosPotenciais();
                    }
                }

                $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado = true;
                $scope.controlePaginacao.atendimentosAtivos.carregado = false;
                $scope.controlePaginacao.atendimentosPendentes.carregado = false;
                $scope.controlePaginacao.atendimentosRetornos.carregado = false;
                $scope.controlePaginacao.atendimentosPotenciais.carregado = false;

                break;
            case 'ATIVOS':

                $scope.recuperarAtendimentosAtivos(true);

                if (!ignoreTotais) {
                    $scope.recuperarTotalAtendimentosAtivosNovasMensagens();
                    $scope.recuperarTotalAtendimentosAtivos();
                    $scope.recuperarTotalAtendimentosPendentes();
                    $scope.recuperarTotalAtendimentosRetornos();

                    if ($rootScope.atendente.potenciais === true) {
                        $scope.recuperarTotalAtendimentosPotenciais();
                    }
                }

                $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado = false;
                $scope.controlePaginacao.atendimentosAtivos.carregado = true;
                $scope.controlePaginacao.atendimentosPendentes.carregado = false;
                $scope.controlePaginacao.atendimentosRetornos.carregado = false;
                $scope.controlePaginacao.atendimentosPotenciais.carregado = false;

                break;
            case 'PENDENTES':

                $scope.recuperarAtendimentosPendentes(true);

                if (!ignoreTotais) {
                    $scope.recuperarTotalAtendimentosAtivosNovasMensagens();
                    $scope.recuperarTotalAtendimentosAtivos();
                    $scope.recuperarTotalAtendimentosPendentes();
                    $scope.recuperarTotalAtendimentosRetornos();

                    if ($rootScope.atendente.potenciais === true) {
                        $scope.recuperarTotalAtendimentosPotenciais();
                    }
                }

                $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado = false;
                $scope.controlePaginacao.atendimentosAtivos.carregado = false;
                $scope.controlePaginacao.atendimentosPendentes.carregado = true;
                $scope.controlePaginacao.atendimentosRetornos.carregado = false;
                $scope.controlePaginacao.atendimentosPotenciais.carregado = false;

                break;
            case 'POTENCIAIS':

                if ($rootScope.atendente.potenciais === true) {
                    $scope.recuperarAtendimentosPotenciais(true);
                }

                if (!ignoreTotais) {
                    $scope.recuperarTotalAtendimentosAtivosNovasMensagens();
                    $scope.recuperarTotalAtendimentosAtivos();
                    $scope.recuperarTotalAtendimentosPendentes();
                    $scope.recuperarTotalAtendimentosRetornos();

                    if ($rootScope.atendente.potenciais === true) {
                        $scope.recuperarTotalAtendimentosPotenciais();
                    }
                }

                $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado = false;
                $scope.controlePaginacao.atendimentosAtivos.carregado = false;
                $scope.controlePaginacao.atendimentosPendentes.carregado = false;
                $scope.controlePaginacao.atendimentosRetornos.carregado = false;
                $scope.controlePaginacao.atendimentosPotenciais.carregado = true;

                break;
            case 'RETORNOS':

                $scope.recuperarAtendimentosRetornos();

                if (!ignoreTotais) {
                    $scope.recuperarTotalAtendimentosAtivosNovasMensagens();
                    $scope.recuperarTotalAtendimentosAtivos();
                    $scope.recuperarTotalAtendimentosPendentes();
                    $scope.recuperarTotalAtendimentosRetornos();

                    if ($rootScope.atendente.potenciais === true) {
                        $scope.recuperarTotalAtendimentosPotenciais();
                    }
                }

                $scope.controlePaginacao.atendimentosAtivosNovasMensagens.carregado = true;
                $scope.controlePaginacao.atendimentosAtivos.carregado = false;
                $scope.controlePaginacao.atendimentosPendentes.carregado = false;
                $scope.controlePaginacao.atendimentosRetornos.carregado = true;
                $scope.controlePaginacao.atendimentosPotenciais.carregado = false;

                break;
        }
    };

    $scope.recuperarMensagensRapidas = function (pagination) {
        if (pagination) {
            $scope.mensagensRapidasFiltro.offset += 20;
        } else {
            $scope.allMensagensRapidas = [];
            $scope.mensagensRapidasFiltro.offset = 0;
        }

        var params = {
            offset: $scope.mensagensRapidasFiltro.offset
        };

        if ($scope.mensagensRapidasFiltro.search && $scope.mensagensRapidasFiltro.search.trim() != "") {
            params.search = $scope.mensagensRapidasFiltro.search.trim();
        }

        MensagensRapidasService.getAllAtendimento(params).then((response) => {
            $scope.allMensagensRapidas = pagination ? $scope.allMensagensRapidas.concat(response.data) : response.data;
            $scope.mostrarMaisMensagensRapidas = response.data.length >= 20;
        });
    };

    var buscarMensagensRapidasModalDebounced = atendimentoUtils.debounce(function () {
        $scope.recuperarMensagensRapidas();
    }, 300);

    $scope.onFiltroMensagensRapidasModalChange = function () {
        buscarMensagensRapidasModalDebounced();
    };

    $scope.onMostrarMensagenRapidas = function () {
        $scope.mostrarMensagensRapidas = !$scope.mostrarMensagensRapidas;
    };

    $scope.onExcluirMensagemRapida = function (mensagem) {
        AtendenteService.excluirMensagemRapida(mensagem.id).then(function (response) {
            $scope.recuperarMensagensRapidas();
        });
    };

    $scope.onSelecionarMensagemRapida = function (mensagem) {
        if (mensagem.tipo == 'SINGLE') {
            $scope.mensagemRapidaSelecionada = null;

            let novaMensagem = angular.copy(mensagem);

            if ($scope.novaMensagem.ccAux) {
                novaMensagem.ccAux = $scope.novaMensagem.ccAux;
            }

            if ($scope.novaMensagem.destinatario) {
                novaMensagem.destinatario = $scope.novaMensagem.destinatario;
            }

            $scope.novaMensagem = novaMensagem;

            $scope.replaceContactName($scope.novaMensagem);
            $scope.replaceAgentNameName($scope.novaMensagem);

            $scope.mostrarMensagensRapidas = false;

            $(".content-footer textarea").focus();

            $scope.onCancelarModalMensagensRapidas();
            $scope.onCancelarModalVisualizarMensagemRapida();
        } else if (mensagem.tipo == 'GROUPED') {
            let jsonMensagens = JSON.parse(mensagem.mensagem);

            jsonMensagens.forEach((msg) => {
                if (msg.type === "TEXT" && msg.atendimentoMensagem?.tipo === "TEXTO") {
                    let texto = msg.atendimentoMensagem.mensagem;

                    let temp = { mensagem: texto };

                    $scope.replaceContactName(temp);
                    $scope.replaceAgentNameName(temp);

                    msg.atendimentoMensagem.mensagem = temp.mensagem;
                }

                if (Array.isArray(msg.components)) {
                    msg.components.forEach((comp) => {
                        if (comp.type === "BODY" && comp.text) {
                            let tempComponent = { mensagem: comp.text };

                            $scope.replaceContactName(tempComponent);
                            $scope.replaceAgentNameName(tempComponent);

                            comp.text = tempComponent.mensagem;
                        }
                    });
                }
            });

            $scope.showPreviewSendingMessages(jsonMensagens);
        }
    };

    $scope.replaceContactName = function (registro) {
        if (!registro) return;

        let mensagem = registro.mensagem || "";
        mensagem = String(mensagem);

        const nome = ($scope.atendimentoSelecionado?.informacoes?.usuario?.usuarioNome || "")
            .substring(0, 100);

        mensagem = mensagem.replaceAll("{{nome}}", nome)
            .replaceAll("{{name}}", nome)
            .replaceAll("{{nombre}}", nome)
            .replaceAll("{{contact.name}}", nome);

        registro.mensagem = mensagem;
    };

    $scope.replaceAgentNameName = function (registro) {
        registro.mensagem = registro.mensagem.replaceAll("{{agent.name}}", $rootScope.atendente.nome.substring(0, 100));
    }

    $scope.onAdicionarMensagemRapida = function (registro) {
        var data = null;

        if (registro) {
            data = {
                mensagem: registro.mensagem,
                palavraChave: registro.palavraChave,
            };
        } else if ($scope.novaMensagem.mensagem && $scope.novaMensagem.mensagem.length > 0) {
            data = {
                mensagem: $scope.novaMensagem.mensagem
            };
        }

        if (data != null) {
            AtendenteService.inserirMensagemRapida(data).then(function () {
                $scope.recuperarMensagensRapidas();
                $scope.replaceContactName($scope.novaMensagem);

                if (registro) {
                    $scope.onCancelarModalEditarMensagemRapida();
                }

            });
        }
    };

    $scope.onAtualizarMensagemRapida = function (registro) {
        AtendenteService.atualizarMensagemRapida(registro).then(function () {
            $scope.recuperarMensagensRapidas();
            $scope.replaceContactName($scope.novaMensagem);
            $scope.onCancelarModalEditarMensagemRapida();
        });
    };

