    $scope.atualizarRetornos = () => {
        TaskRuleService.getAllAtendimento($scope.atendimentoSelecionado.id, 'FOLLOW_UP').then((response) => {
            $scope.atendimentoSelecionado.informacoes.retornos = response.data;
        });
    };

    $scope.isRetornoAntigo = (retorno) => {
        return retorno.followUpAt < new Date().getTime();
    }

    $scope.filtrarRetornos = (retornos, antigo) => {
        if (!retornos) {
            return retornos;
        }

        if (antigo) {
            return retornos.filter(r => $scope.isRetornoAntigo(r))
        } else {
            return retornos.filter(r => !$scope.isRetornoAntigo(r))
        }

    }

    $scope.updateStateMicrofone = function (result) {
        if (result.state === 'granted') {
            $scope.permissaoMicrofone = true;
        } else if (result.state === 'prompt') {
            $scope.permissaoMicrofone = undefined;
        } else if (result.state === 'denied') {
            $scope.permissaoMicrofone = false;
        }

        $scope.$apply();
    };

    $scope.onMostarModalAudio = function () {
        if ($localStorage.webview) {
            $scope.postMessageRecordAudio($scope.atendimentoSelecionado.id)
        } else {
            $scope.permissaoMicrofone = undefined;

            if (!navigator.mediaDevices && !navigator.getUserMedia && !navigator.webkitGetUserMedia &&
                !navigator.mozGetUserMedia && !navigator.msGetUserMedia) {
                alert('User Media API not supported.');
                return;
            }

            $scope.mediaRecorder;
            $scope.novaMensagemAudio = {
                uid: generateUUID() + '_web',
                atendimentoId: $scope.atendimentoSelecionado.id,
                gravando: false
            }

            if ($scope.mediaRecorder) {
                $scope.mediaRecorder.init = true;
                $scope.stopAudio();
            }

            $scope.modalNovoAudio = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/atendimentos/modal-audio.html',
                scope: $scope,
                keyboard: false
            });
        }
    };

    $scope.getUserMedia = function () {
        var constraints = {};
        constraints["audio"] = true;

        if (navigator.mediaDevices) {
            return navigator.mediaDevices.getUserMedia(constraints);
        }

        var legacyApi = navigator.getUserMedia || navigator.webkitGetUserMedia ||
            navigator.mozGetUserMedia || navigator.msGetUserMedia;

        if (legacyApi) {
            return new Promise(function (resolve, reject) {
                legacyApi.bind(navigator)(constraints, resolve, reject);
            });
        }
    }

    $scope.novaMensagemAudio = {
        gravando: false,
        blob: null
    };

    $scope.modelAudio = false;
    $scope.audioDraftUrl = null;

    $scope.aplicarScopeAudio = function () {
        if ($scope.$$phase || $rootScope.$$phase) {
            return;
        }

        $scope.$apply();
    };

    $scope.onErroGravacaoAudio = function (err) {
        $scope.modelAudio = false;
        $scope.audioDraftUrl = null;
        $scope.novaMensagemAudio = {
            gravando: false,
            blob: null
        };

        if ($scope.mediaRecorder) {
            $scope.stopAudio();
            $scope.mediaRecorder = null;
        }

        var _erro = err && err.name ? err.name : '';
        var _texto;

        if (_erro === 'NotAllowedError' || _erro === 'PermissionDeniedError' || _erro === 'SecurityError') {
            $scope.permissaoMicrofone = false;
            _texto = "Permissão de microfone negada. Libere o acesso ao microfone nas configurações do navegador e tente novamente.";
        } else if (_erro === 'NotFoundError' || _erro === 'DevicesNotFoundError') {
            _texto = "Nenhum microfone foi encontrado neste dispositivo.";
        } else if (_erro === 'NotReadableError' || _erro === 'TrackStartError') {
            _texto = "O microfone está sendo usado por outro programa. Feche-o e tente novamente.";
        } else {
            _texto = "Não foi possível iniciar a gravação de áudio. Tente novamente, por favor.";
        }

        swal("Ops!", _texto, "error");
        $scope.aplicarScopeAudio();
    };

    $scope.iniciarGravacaoAudio = function () {
        $scope.audioDraftUrl = null;

        var _promise;

        try {
            _promise = $scope.getUserMedia();
        } catch (e) {
            _promise = null;
        }

        if (!_promise || !_promise.then) {
            $scope.onErroGravacaoAudio({ name: 'NotSupportedError' });
            return null;
        }

        return _promise;
    };

    $scope.startAudio = function () {
        var _promise = $scope.iniciarGravacaoAudio();

        if (!_promise) {
            return;
        }

        _promise
            .then(stream => {
                $scope.modelAudio = true;
                $scope.novaMensagemAudio.gravando = true;
                $scope.permissaoMicrofone = true;

                $scope.mediaRecorder = new MediaRecorder(stream);

                $scope.mediaRecorder.addEventListener("dataavailable", event => {
                    if ($scope.mediaRecorder.state === "inactive") {
                        $scope.novaMensagemAudio.blob = event.data;
                        $scope.audioDraftUrl = window.URL.createObjectURL($scope.novaMensagemAudio.blob);

                        if ($scope._pendingAtendimentoSwitch) {
                            var _pending = $scope._pendingAtendimentoSwitch;
                            $scope._pendingAtendimentoSwitch = null;
                            $scope.$apply(function () {
                                $scope.selecionarAtendimento(_pending);
                            });
                        } else {
                            $scope.$apply();
                        }
                    }
                });

                $scope.mediaRecorder.start();
                $scope.$apply();
            }, err => {
                $scope.onErroGravacaoAudio(err);
            });
    };

    $scope.startAudioMobile = function () {
        var _promise = $scope.iniciarGravacaoAudio();

        if (!_promise) {
            return;
        }

        _promise
            .then(stream => {
                $scope.modelAudio = true;
                $scope.novaMensagemAudio.gravando = true;
                $scope.permissaoMicrofone = true;

                $scope.mediaRecorder = new MediaRecorder(stream);

                $scope.mediaRecorder.addEventListener("dataavailable", event => {
                    if ($scope.mediaRecorder.state === "inactive") {
                        $scope.novaMensagemAudio.blob = event.data;
                        $scope.audioDraftUrl = window.URL.createObjectURL($scope.novaMensagemAudio.blob);

                        if ($scope._pendingAtendimentoSwitch) {
                            var _pending = $scope._pendingAtendimentoSwitch;
                            $scope._pendingAtendimentoSwitch = null;
                            $scope.$apply(function () {
                                $scope.selecionarAtendimento(_pending);
                            });
                        } else {
                            $scope.$apply();
                        }
                    }
                });

                $scope.mediaRecorder.start();
                $scope.$apply();
            }, err => {
                $scope.onErroGravacaoAudio(err);
            });
    };

    $scope.stopAudio = function () {
        $scope.novaMensagemAudio.gravando = false;

        if ($scope.mediaRecorder) {
            try {
                if ($scope.mediaRecorder.state !== "inactive") {
                    $scope.mediaRecorder.stop();
                }

                if ($scope.mediaRecorder.stream) {
                    $scope.mediaRecorder.stream.getTracks().forEach(track => {
                        track.stop();
                    });
                }
            } catch (e) {
                console.error('Erro ao parar a gravação de áudio', e);
            }
        }
    };

    $scope.onModalAudioCancelarMobile = function (clearDraft) {
        $scope.modelAudio = false;
        $scope.audioDraftUrl = null;

        if ($scope.novaMensagemAudio.gravando) {
            $scope.stopAudio();
        }

        $scope.novaMensagemAudio = {
            gravando: false,
            blob: null
        };

        if ($scope.modalNovoAudio) {
            $scope.modalNovoAudio.close();
        }

        if (clearDraft) $scope.clearDraftIfEmpty();
    };

    $scope.onModalAudioCancelar = function (clearDraft) {
        $scope.modelAudio = false;
        $scope.audioDraftUrl = null;

        if ($scope.novaMensagemAudio.gravando) {
            $scope.stopAudio();
        }

        $scope.novaMensagemAudio = {
            gravando: false,
            blob: null
        };

        if ($scope.modalNovoAudio) {
            $scope.modalNovoAudio.close();
        }

        if (clearDraft) $scope.clearDraftIfEmpty();
    };

    $scope.onFalhaEnvioAudio = function (mostrarAlerta) {
        $scope.enviandoAudio = false;

        if (mostrarAlerta) {
            swal("Ops!", "Não foi possível enviar o áudio. Tente novamente, por favor.", "error");
        }

        $scope.aplicarScopeAudio();
    };

    $scope.onEnviarAudio = function () {
        if ($scope.novaMensagemAudio.gravando) {
            return;
        }

        if ($scope.enviandoAudio) {
            return;
        }

        if (!$scope.novaMensagemAudio.blob) {
            $scope.onModalAudioCancelar();
            $scope.onModalAudioCancelarMobile();
            return;
        }

        $scope.enviandoAudio = true;
        let audioFileName = $scope.isInstagram() ? 'audio.aac' : 'a5ca0b5894324f8bb54bb9fffad29d1e.wav';

        var _upload = FileService.insertBlob($scope.novaMensagemAudio.blob, audioFileName);

        if (!_upload || !_upload.then) {
            $scope.onFalhaEnvioAudio(false);
            return;
        }

        _upload.then(function (response) {
            $scope.novaMensagemAudio.mensagem = response.data.url;
            $scope.novaMensagemAudio.tipo = "AUDIO";

            if ($scope.messageToReply) {
                if ($scope.privateMode) {
                    var mensagens = [{
                        mensagem: $scope.novaMensagemAudio.mensagem,
                        tipo: $scope.novaMensagemAudio.tipo,
                        refUid: $scope.messageToReply.originalUid ? $scope.messageToReply.originalUid : $scope.messageToReply.uid,
                        categoria: "PRIVATE_MESSAGE"
                    }];
                } else {
                    var mensagens = [{
                        mensagem: $scope.novaMensagemAudio.mensagem,
                        tipo: $scope.novaMensagemAudio.tipo,
                        refUid: $scope.messageToReply.originalUid ? $scope.messageToReply.originalUid : $scope.messageToReply.uid
                    }];
                }
            } else {
                if ($scope.privateMode) {
                    var mensagens = [{
                        mensagem: $scope.novaMensagemAudio.mensagem,
                        tipo: $scope.novaMensagemAudio.tipo,
                        categoria: "PRIVATE_MESSAGE"
                    }];
                } else {
                    var mensagens = [{
                        mensagem: $scope.novaMensagemAudio.mensagem,
                        tipo: $scope.novaMensagemAudio.tipo
                    }];
                }
            }

            $scope.onEnviarMensagemAudio(mensagens, $scope.atendimentoSelecionado.id);
        }, function () {
            $scope.onFalhaEnvioAudio(true);
        });
    };

    $scope.onEnviarMensagemAudio = (mensagens, atendimentoId) => {
        AtendimentoService.enviarMensagemAtendente(atendimentoId, mensagens).then(function () {
            delete $scope.drafts[atendimentoId];
            $scope.saveDraftsToStorage();
            //$scope.onModalCancelar();
            $scope.onModalAudioCancelar();
            $scope.onModalAudioCancelarMobile();
            $scope.enviandoAudio = false;
            $scope.cancelarResponderMensagem();
        }, function () {
            $scope.onFalhaEnvioAudio(true);
        });
    }

