    $scope.selecionarArquivoCampoInformacao = function (campo) {
        $scope.campoSegmentacaoArquivoSelecionado = campo;
        setTimeout(function () {
            $('#inputCampoSegmentacao' + campo.contatoInformacaoId).trigger('click');
        })
    };

    $scope.atualizarArquivoCampoInformacao = function (files) {
        if (!files || !files.length) {
            return;
        }

        let reader = new FileReader();
        let file = files[0];

        reader.readAsDataURL(file);
        reader.onload = function () {
            FileService.insertBase64(reader.result, file.name).then(f => {
                $scope.campoSegmentacaoArquivoSelecionado.valorOriginal = f.data.url;
                $scope.campoSegmentacaoArquivoSelecionado.valorUrl = f.data.url;

                $scope.atualizarContato($scope.campoSegmentacaoArquivoSelecionado);
            });
        };
    }

    $scope.removerArquivoContatoInformacao = function (campo) {
        $('#inputCampoSegmentacao' + campo.contatoInformacaoId)[0].value = '';
        delete campo.valorOriginal;
        delete campo.valorUrl;
        $scope.atualizarContato(campo);
    }

    $scope.atualizarContato = (campo) => {
        if (campo.integracao) {
            if (campo.integracaoLista) {
                let item = campo.integracaoLista.find(l => l.id == campo.valorIntegracao);
                campo.valorOriginal = item ? item.value : null;
            } else {
                campo.valorIntegracao = campo.valorOriginal;
            }
        }

        const campoId = campo.contatoInformacaoId;

        $scope.atualizarCampoSegmentacaoDependente(campoId);

        var usuario = {
            whatsUsuarioId: $scope.atendimentoSelecionado.informacoes.usuario.usuarioId,
            nome: $scope.atendimentoSelecionado.informacoes.usuario.usuarioNome,
            informacoesAdicionais: $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais
        };

        $scope.isValidandoCampoSegmentacao = true;
        if ($scope.atendimentoSelecionado.status == 'POTENCIAL') {
            ContatoService.atualizarCampoSegmentacao(usuario.whatsUsuarioId, usuario)
                .then(res => {
                    $scope.recuperarCampoSegmentacaoIntegracao(campoId)

                    if (!campoId) {
                        $scope.potencialSelecionadoLista.usuario = usuario.nome
                    }
                });
        } else {
            AtendimentoService.atualizarUsuario($scope.atendimentoSelecionado.id, usuario)
                .then(res => {
                    $scope.recuperarCampoSegmentacaoIntegracao(campoId);

                    if (!campoId) {
                        $scope.atendimentoSelecionadoLista.nome = usuario.nome
                    }
                })
                .catch(err => {
                    if (err.status === 403) {
                        let mensagem = err.data.message;
                        if (mensagem.includes("PERMISSAO-CAMPO-SEGMENTACAO")) {
                            let campo = mensagem.split("|")[1];
                            $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais = $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.filter(c => c.nome !== mensagem.split("|")[1])
                            swal({
                                title: "Campo retirado do departamento",
                                text: "Você não tem mais permissão para ver/editar o campo '" + campo + "'",
                                type: "error"
                            });
                        }
                    }

                });;
        }
    };

    $scope.atualizarCampoSegmentacaoDependente = (id, clear) => {
        if (!$scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais) {
            return;
        }

        let campo = $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.find(i => i.contatoInformacaoId == id);

        if (!campo) {
            return;
        }

        if (clear) {
            campo.valorIntegracao = null;
            campo.valorOriginal = null;
            campo.integracaoLista = null;
        }

        if (campo.dependentes && campo.dependentes.length > 0) {
            campo.dependentes.forEach(d => {
                $scope.atualizarCampoSegmentacaoDependente(d.contatoInformacaoIdFilho, true);
            })
        }
    }

    $scope.recuperarCampoSegmentacaoIntegracao = (id) => {
        if ($scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais) {
            const camposSegmentacao = id
                ? $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.filter(i => i.dependencias.some(d => d.contatoInformacaoIdPai == id))
                : $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais;

            $.each(camposSegmentacao, (index, campo) => {
                if (campo.integracao) {
                    // Listar os itens caso não haja dependencias
                    let buscar = !campo.dependencias || campo.dependencias.length == 0;

                    // Se houver, verificar se já estão preenchidos
                    if (!buscar) {
                        const dependenciasIds = campo.dependencias.map(d => d.contatoInformacaoIdPai);
                        const informacoes = $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.filter(i => dependenciasIds.some(di => di == i.contatoInformacaoId) && i.valorOriginal);
                        buscar = informacoes.length == dependenciasIds.length;
                    }

                    if (buscar) {
                        let { informacoesAdicionais, ...ticket } = $scope.atendimentoSelecionado.informacoes.usuario;
                        const payload = JSON.stringify({
                            ticket: ticket,
                            fields: $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais
                        })

                        const data = {
                            endpoint: campo.integracaoUrl,
                            token: campo.token,
                            payload
                        };

                        ContatoInformacaoService.requestIntegracao(data).then(res => {
                            const data = res.data;

                            if (data.list) {
                                campo.integracaoLista = data.list;
                                const item = data.list.find(l => l.id === data.value);

                                if (data.value && (!campo.valorIntegracao || campo.valorIntegracao.trim() == "") && item) {
                                    campo.valorIntegracao = data.value;
                                    campo.valorOriginal = item.value;
                                }



                            } else if (data.value && (!campo.valorIntegracao || campo.valorIntegracao.trim() == "")) {
                                campo.valorIntegracao = data.value;
                                campo.valorOriginal = data.value;
                            }
                        })
                    }

                }
            });
        }
    }

