    $scope.atualizarImagemMensagem = function (files) {
        var imagem;

        if (files) {
            imagem = files[0];
            var limite = 50000000;

            if ($scope.isWhatsappApi()) {
                limite = 5000000;
            }

            if ($scope.isInstagram()) {
                limite = 8000000;
            }

            if ($scope.isFacebook()) {
                limite = 25000000;
            }

            if (imagem.size > limite) {
                swal("Ops!", $translate.instant('ENVIE-MENSAGEM-COM-NO-MAXIMO') + " " + (limite / 1000000) + "MB.", "error");
                $('#imagem-input img').removeAttr('src');
                imagem = null;
            }
        }

        if (imagem !== null) {
            $scope.novoArquivo.mensagem = imagem.result;
            $scope.novoArquivo.nome = imagem.name;

            $("span.fileinput-new").hide();
            $("span.fileinput-exists").show();
            $("a.fileinput-exists").show();
        } else {
            $scope.novoArquivo = {};

            $("span.fileinput-new").show();
            $("span.fileinput-exists").hide();
            $("a.fileinput-exists").hide();
        }
    };

    $scope.onModalAnexoCancelar = function () {
        $scope.modalAnexo.close();
        $scope.novoArquivo = {};
    };

