    $scope.onMostarModalPotencial = function (clientePotencial) {
        if (!$scope.isOnline()) {
            swal({
                title: "Ops!",
                text: $translate.instant('ALERTA-NECESSARIO-ESTAR-ONLINE'),
                type: "error"
            });

            return;
        }


        if ($scope.controlePaginacao.mensagens.carregando) {
            return;
        }

        $scope.potencialSelecionadoLista = clientePotencial;
        $scope.clearSocketTicket();

        $scope.showOtherPage = false;
        $state.go("atendimentos.chat");
        $scope.showCenterContent();
        $scope.resetTextArea();
        $scope.controlePaginacao.mensagens.stopScrollLoading = true;
        $scope.showButtonPageBottom = false;
        $scope.specificSearch = false;

        $scope.atendimentoSelecionado = {
            id: clientePotencial.id,
            status: 'POTENCIAL',
            informacoes: {
                usuario: {
                    id: clientePotencial.id,
                    usuarioId: clientePotencial.id,
                    imagemPerfil: clientePotencial.imagemPerfil,
                    usuarioNome: clientePotencial.usuario,
                    whatsapp: clientePotencial.origem === 'WHATSAPP' ? clientePotencial.telefoneCliente : null,
                    facebook: clientePotencial.origem === 'FACEBOOK' ? clientePotencial.telefoneCliente : null,
                    instagram: clientePotencial.origem === 'INSTAGRAM' ? clientePotencial.telefoneCliente : null,
                    telegram: clientePotencial.origem === 'TELEGRAM' ? clientePotencial.telefoneCliente : null,
                    site: clientePotencial.origem === 'SITE' ? clientePotencial.telefoneCliente : null,
                    gbm: clientePotencial.origem === 'GOOGLE_BUSINESS_MESSAGES' ? clientePotencial.telefoneCliente : null,
                    usuarioTelefone: clientePotencial.telefoneUsuario,
                    informacoesAdicionais: [],
                    grupoInfo: clientePotencial.grupoInfo
                },
                anotacoes: []
            },
            mensagens: []
        };

        ContatoService.getAnotacoes(clientePotencial.id).then(function (resp) {
            $scope.atendimentoSelecionado.informacoes.anotacoes = resp.data;
        });

        ContatoService.getCamposSegmentacao(clientePotencial.id).then(function (resp) {
            $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais = resp.data;
            updateComponentsAfterRequest();
        });

        ContatoService.getIndicadores(clientePotencial.id).then(function (resp) {
            $scope.atendimentoSelecionado.informacoes.totalAtendimentos = resp.data.totalAtendimentos;
            $scope.atendimentoSelecionado.informacoes.totalMensagens = resp.data.totalMensagens;
        });

        $scope.recuperarMensagens(false);
        $scope.getWebhooks();
    };

