    // FUNÇÃO PARA COPIAR TEXTO
    $scope.copyToClipboard = function (text) {
        var textarea = document.createElement("textarea");
        textarea.value = text;
        document.body.appendChild(textarea);
        textarea.select();
        document.execCommand("copy");
        document.body.removeChild(textarea);

        $scope.showCopyMessage = true;

        setTimeout(function () {
            $scope.$apply(function () {
                $scope.showCopyMessage = false;
            });
        }, 5000);
    };

    $scope.onCriarAtendimentoPotencial = function () {
        if ($scope.isAtendente() && $scope.departamentosUsuario.length === 1) {
            $scope.departamentoSelecionado = $scope.departamentosUsuario[0];
            $scope.departamentoSelecionado.departamentoId = $scope.departamentoSelecionado.id.toString();
            $scope.departamentoSelecionado.atendenteId = $scope.getUsuarioId();

            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('DESEJA-REALMENTE-CRIAR-ATENDIMENTO-POTENCIAL'),
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: $translate.instant('SIM'),
                cancelButtonText: $translate.instant('CANCELAR'),
                closeOnConfirm: true,
                closeOnCancel: true
            }, function (isConfirm) {
                if (isConfirm) {
                    $scope.onCriarAtendimento();
                }
            });
        } else {
            $scope.modalPotencial = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/atendimentos/modal-potencial.html',
                scope: $scope
            });
        }
    }

    $scope.onCriarAtendimento = function () {
        $scope.controlePaginacao.mensagens.stopScrollLoading = true;

        var atendimento = {
            departamentoId: $scope.departamentoSelecionado.departamentoId,
            atendenteId: $scope.departamentoSelecionado.atendenteId,
            followUp: $scope.atendimentoSelecionado.isFollowUp
        };

        if ($scope.atendimentoSelecionado.status == 'POTENCIAL') {
            atendimento.whatsUsuarioId = $scope.atendimentoSelecionado.id
        } else {
            atendimento.whatsUsuarioId = $scope.atendimentoSelecionado.informacoes.usuario.usuarioId;
            atendimento.atendimentoId = $scope.atendimentoSelecionado.id;
        }

        if (!atendimento.departamentoId) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('CHAT-INFORME-DEPARTAMENTO'),
                type: "error",
                timer: 5000,
                function() { }
            });

            return;
        }

        ContatoService.criarAtendimento(atendimento).then(function (response) {
            if (response.data.distribuido) {
                swal("Atenção!", $translate.instant('ATENDIMENTO-CRIADO-DISTRIBUIDO-ATENDENTE') + " " + response.data.atendente + ".", "info");
            } else {
                if (response && response.data) {
                    $scope.selecionarAtendimentoById(response.data.id);
                }
            }

            $scope.onModalCancelar();
            $scope.fecharModalPotencial();
            $scope.showLeftMenu()
        });
    };

