    $scope.criarAtendimentoPeloRecado = function () {
        var novoAtendimento = {
            departamentoId: $scope.departamentoSelecionado.departamentoId,
            atendenteId: $scope.departamentoSelecionado.atendenteId
        };

        if (!novoAtendimento.departamentoId) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('CHAT-INFORME-DEPARTAMENTO'),
                type: "error",
                timer: 5000,
                function() { }
            });
            return;
        }

        RecadoService.abrirAtendimento($scope.recadoSelecionado.id, novoAtendimento).then(function (response) {
            if (response.data.distribuido) {
                swal("Atenção!", $translate.instant('ATENDIMENTO-CRIADO-DISTRIBUIDO-ATENDENTE') + " " + response.data.atendente + ".", "info");
            }

            $scope.departamentoSelecionado = {};

            $scope.fecharModalRecado();
            $scope.onModalCancelar();

            $scope.recados = $scope.recados.filter(r => r.id !== $scope.recadoSelecionado.id);
        });
    };

    $scope.finalizarRecado = function (recado) {
        RecadoService.finalizar(recado.id).then(function (response) {
            $scope.fecharModalRecado();
            $scope.recados = $scope.recados.filter(r => r.id !== recado.id);
        });
    };

    $rootScope.onClickCriarAtendimentoContatoCompartilhado = (contact) => {
        if (contact.phones && contact.phones.length > 0) {

            if (contact.phones.length == 1) {
                let name = contact.name.formattedName;
                let phone = contact.phones[0].phone;
                $scope.onMostrarModalCriarAtendimentoContatoCompartilhado(name, phone);
            } else {
                $scope.onMostrarInformacaoContatoCompartilhado(contact);
            }
        } else {
            swal("Ops", "Não há um número de telefone associado a esse contato", "error")
        }
    }

    $rootScope.onMostrarModalCriarAtendimentoContatoCompartilhado = (nome, telefone) => {
        let canal = $scope.canais.find(c => c.numero == $scope.atendimentoSelecionado.informacoes.usuario.whatsapp)

        $scope.novoAtendimentoNovoContato = {
            canalChave: canal.chave.toString(),
            telefone,
            nome
        };
        $scope.selectChannelNewTicket();
        $scope.departamentoSelecionado = {};
        $scope.onMostratModalCriarAtendimento();
    }

    $rootScope.onMostrarModalCriarAtendimentoNovoContato = function () {
        $scope.novoAtendimentoNovoContato = {};
        $scope.departamentoSelecionado = {};
        $scope.onMostratModalCriarAtendimento();
    };

    $rootScope.onMostrarModalSettings = function () {
        AtendimentoService.getSettings().then(function (response) {
            $scope.ticketSettings = response.data;

            $scope.modalSettings = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/atendimentos/modal-settings.html?t=' + Date.now(),
                scope: $scope
            });

            $scope.modalSettings.rendered.then(() => {
                updateComponentsAfterRequest();
            });
        });
    };

    $rootScope.onModalSettingsSalvar = function () {
        AtendimentoService.saveSettings($scope.ticketSettings).then(function () {
            swal({
                title: $translate.instant('PRONTO') + "!",
                text: $translate.instant('CONFIGURACOES-SALVAS-COM-SUCESSO'),
                type: "success",
                timer: 2000
            });
            $scope.onModalSettingsCancelar();
        });
    };

    $rootScope.onModalSettingsCancelar = function () {
        $scope.modalSettings.close();
    };

    $rootScope.onMostratModalCriarAtendimento = () => {
        if ($scope.departamentosUsuario.length === 1) {
            $scope.departamentoSelecionado = $scope.departamentosUsuario[0];
            $scope.departamentoSelecionado.departamentoId = $scope.departamentoSelecionado.id.toString();
            $scope.onSelecionarDepartamento();
        }

        $scope.modalCriarAtendimentoNovoContato = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/atendimentos/modal-criar-atendimento-novo-contato.html?t=' + Date.now(),
            scope: $scope
        });

        $scope.modalCriarAtendimentoNovoContato.rendered.then(() => {
            var input = document.querySelector("#novoAtendimentoNovoContatoTelefone");
            $scope.itl = window.intlTelInput(input, {
                initialCountry: $localStorage.preferredCountry ? $localStorage.preferredCountry : "br",
                preferredCountries: ["br", "us", "es"],
                separateDialCode: true
            });

            input.addEventListener("countrychange", () => {
                const countryData = $scope.itl.getSelectedCountryData();
                if (countryData) {
                    $localStorage.preferredCountry = countryData.iso2 ? countryData.iso2 : "br";
                }
            });

            if ($scope.novoAtendimentoNovoContato.telefone) {
                $scope.itl.setNumber($scope.novoAtendimentoNovoContato.telefone)
            }

            updateComponentsAfterRequest();
        });
    }

    $rootScope.onFecharModalCriarAtendimentoNovoContato = function () {
        $scope.modalCriarAtendimentoNovoContato.close();
    };

    $rootScope.onModalCriarAtendimentoNovoContato = () => {
        $scope.controlePaginacao.mensagens.stopScrollLoading = true;

        if ($scope.novoAtendimentoNovoContato.canal.canal === 'WA-MESSENGER' || ($scope.novoAtendimentoNovoContato.canal.canal === 'TELEGRAM')) {

            $scope.novoAtendimentoNovoContato.telefone = PhoneUtil.getNumeroInternacional($scope.itl);

            if (!$scope.telefoneValido($scope.novoAtendimentoNovoContato.telefone)) {
                return;
            }
        }

        var data = {
            nome: $scope.novoAtendimentoNovoContato.nome,
            telefone: $scope.novoAtendimentoNovoContato.telefone,
            email: $scope.novoAtendimentoNovoContato.email,
            canalTipo: $scope.novoAtendimentoNovoContato.canal.canal,
            canalId: $scope.novoAtendimentoNovoContato.canal.id,
            assuntoEmail: $scope.novoAtendimentoNovoContato.assuntoEmail,
            departamentoId: $scope.departamentoSelecionado.departamentoId,
            atendenteId: $scope.departamentoSelecionado.atendenteId
        };

        if (data.canalTipo === 'EMAIL') {
            data = { ...data, ccAux: $scope.novoAtendimentoNovoContato.ccAux };
        }

        if (!data.nome) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('CHAT-VERIFIQUE-NOME'),
                type: "error",
                timer: 5000,
                function() { }
            });

            return;
        }

        if (!data.canalId) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('CHAT-VERIFIQUE-CANAL'),
                type: "error",
                timer: 5000,
                function() { }
            });

            return;
        }

        if (!data.departamentoId) {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: $translate.instant('CHAT-VERIFIQUE-DEPARTAMENTO'),
                type: "error",
                timer: 5000,
                function() { }
            });

            return;
        }

        AtendimentoService.criarAtendimentoNovoContato(data)
            .then(function (response) {

                if (response.data.distribuido) {
                    swal(
                        "Atenção!",
                        $translate.instant('ATENDIMENTO-CRIADO-DISTRIBUIDO-ATENDENTE') + " " + response.data.atendente + ".",
                        "info"
                    );
                }

                $scope.novoAtendimentoNovoContato = {};

                if ($scope.modalCriarAtendimentoNovoContato) {
                    $scope.modalCriarAtendimentoNovoContato.close();
                }

                $scope.departamentoSelecionado = {};
                $scope.fecharAgenda();

                if ($scope.modalInformacaoContatoCompartilhado) {
                    $scope.modalInformacaoContatoCompartilhado.close();
                }

                if (response && response.data) {
                    $scope.selecionarAtendimentoById(response.data.id);
                }

            })
            .catch(function (error) {

                if (
                    error.data &&
                    error.data.message &&
                    error.data.message.includes("Esse contato já está em atendimento") &&
                    $scope.isAtendente()
                ) {

                    const match = error.data.message.match(/Protocolo:\s*(\d+)/);
                    const protocolo = match ? match[1] : null;

                    if (!protocolo) {
                        console.error("Protocolo não encontrado na mensagem");
                        return;
                    }

                    swal({
                        title: "Cliente já está em atendimento",
                        text: error.data.message + "\n\nDeseja solicitar para participar do atendimento?",
                        type: "warning",
                        showCancelButton: true,
                        confirmButtonText: "Sim, solicitar",
                        cancelButtonText: "Cancelar",
                        closeOnConfirm: true
                    }, function (isConfirm) {

                        if (isConfirm) {

                            AtendimentoService
                                .solicitarParticipacao($scope.jwt.usuarioId, protocolo)
                                .then(function () {
                                    swal({
                                        title: "Solicitação enviada",
                                        text: "O atendente responsável foi notificado.",
                                        type: "success",
                                        timer: 2500,
                                        showConfirmButton: false
                                    });
                                })
                                .catch(function (error) {
                                    swal({
                                        title: "Erro",
                                        text: error.data.message,
                                        type: "error"
                                    });
                                });
                        }
                    });
                }
            });

    };

    $scope.trocarIdioma = function (lang) {
        $scope.lang = lang;
        $localStorage.lang = lang;
        $locale.id = lang;
        $translate.use($localStorage.lang);
    };

    $scope.onKeyDownMensagem = (e) => {
        var msg = $scope.novaMensagem.mensagem;
        if (!e) return;

        if (e.key == "Enter" && !e.shiftKey) {
            var ua = navigator.userAgent;
            if (!/Android|webOS|iPhone|iPad|iPod|BlackBerry|IEMobile|Opera Mini|Mobile|mobile|CriOS/i.test(ua)) {
                e.preventDefault();
                e.stopPropagation();
                $scope.enviarMensagem();
            }
        }

        let condition = e.key == "Tab";

        if (condition && (msg == '/private' || msg == '/p' || msg == '/message' || msg == '/m')) {
            $scope.togglePrivateMode(msg == '/private' || msg == '/p' ? true : false);
            $scope.novaMensagem.mensagem = "";
            return;
        }

        if (msg && msg.startsWith("/")) {
            condition = condition || e.key == "ArrowUp" || e.key == "ArrowDown";
        }

        if (condition) {
            e.stopPropagation();
            e.preventDefault();
        }
    }

    $scope.openTabMensagemRapidas = () => {
        $scope.novaMensagem.mensagem = "/";
        $scope.onKeyPressMensagem();
        $scope.getTextareaNovaMensagem().focus();
    }

    $scope.focarMensagemRapidaSelecionada = function () {
        if ($scope.mensagemRapidaSelecionada) {
            const msgRapSelecionada = document.getElementById(`msgrap-${$scope.mensagemRapidaSelecionada.id}`);
            if (msgRapSelecionada) {
                msgRapSelecionada.focus();
            }
        }
    };

    $scope.preservarFocusNovaMensagem = function () {
        var activeElement = document.activeElement;

        if (activeElement && activeElement.closest && activeElement.closest(".content-mensagens-rapidas")) {
            $scope.getTextareaNovaMensagem().focus();
        }
    };

    $scope.mensagensRapidasAutocompleteOffset = 0;
    $scope.temMaisMensagensRapidasAutocomplete = false;
    $scope.carregandoMaisMensagensRapidasAutocomplete = false;

    var getMensagensRapidasAutocompleteParams = function (offset) {
        var msg = $scope.novaMensagem.mensagem || "";
        var search = msg.startsWith("/") ? msg.substring(1).trim() : "";
        var tabIndex = $scope.mensagemRapidaControl.activeTab;
        var deptId = $scope.atendimentoSelecionado && $scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario
            ? $scope.atendimentoSelecionado.informacoes.usuario.departamentoId
            : null;

        var params = { offset: offset || 0 };

        if (search) {
            params.search = search;
        }

        if (deptId) {
            params.departamentoId = deptId;
        }

        if (tabIndex == 2) {
            params.access = "MINE";
        } else if (tabIndex == 3) {
            params.access = "SHARED";
        }

        return params;
    };

    var debouncedBuscarMensagensRapidasAutocomplete = atendimentoUtils.debounce(function (selectFirst) {
        var msg = $scope.novaMensagem.mensagem || "";

        if (!msg.startsWith("/")) {
            return;
        }

        $scope.mensagensRapidasAutocompleteOffset = 0;

        var params = getMensagensRapidasAutocompleteParams(0);
        var requestId = ++$scope.mensagemRapidaRequestId;

        MensagensRapidasService.getAllAtendimento(params).then((response) => {
            if (requestId !== $scope.mensagemRapidaRequestId) {
                return;
            }

            $scope.filtroMensagensRapidas = response.data;
            $scope.temMaisMensagensRapidasAutocomplete = response.data.length >= 20;

            if (selectFirst) {
                $scope.mensagemRapidaSelecionada = $scope.filtroMensagensRapidas.length > 0 ? $scope.filtroMensagensRapidas[0] : null;
                $scope.focarMensagemRapidaSelecionada();
            }

            $scope.preservarFocusNovaMensagem();
        });
    }, 250);

    $scope.buscarMensagensRapidasAutocomplete = function (selectFirst) {
        debouncedBuscarMensagensRapidasAutocomplete(selectFirst);
    };

    $scope.carregarMaisMensagensRapidasAutocomplete = function () {
        if ($scope.carregandoMaisMensagensRapidasAutocomplete || !$scope.temMaisMensagensRapidasAutocomplete) {
            return;
        }

        var msg = $scope.novaMensagem.mensagem || "";

        if (!msg.startsWith("/")) {
            return;
        }

        $scope.carregandoMaisMensagensRapidasAutocomplete = true;

        var novoOffset = $scope.mensagensRapidasAutocompleteOffset + 20;
        var params = getMensagensRapidasAutocompleteParams(novoOffset);
        var requestId = $scope.mensagemRapidaRequestId;

        MensagensRapidasService.getAllAtendimento(params).then((response) => {
            $scope.carregandoMaisMensagensRapidasAutocomplete = false;

            if (requestId !== $scope.mensagemRapidaRequestId) {
                return;
            }

            $scope.mensagensRapidasAutocompleteOffset = novoOffset;
            $scope.filtroMensagensRapidas = $scope.filtroMensagensRapidas.concat(response.data);
            $scope.temMaisMensagensRapidasAutocomplete = response.data.length >= 20;
        }, function () {
            $scope.carregandoMaisMensagensRapidasAutocomplete = false;
        });
    };

    $scope.onKeyPressMensagem = (e) => {
        if ($scope.modalAberto) {
            console.log("modal aberto")
            return
        }

        if (!$scope.novaMensagem.mensagem) {
            $scope.resetTextArea();
            $scope.mostrarMensagensRapidas = false;
            $scope.mensagemRapidaSelecionada = null;
            return;
        }

        var msg = $scope.novaMensagem.mensagem;

        if (msg.startsWith("/")) {
            $scope.mostrarMensagensRapidas = true;

            if (e && e.key === "Tab") {
                $scope.mensagemRapidaControl.activeTab = $scope.mensagemRapidaControl.activeTab + 1;
                $scope.mensagemRapidaControl.activeTab = $scope.mensagemRapidaControl.activeTab > 3 ? 1 : $scope.mensagemRapidaControl.activeTab;
            }

            if (!e) {
                $scope.buscarMensagensRapidasAutocomplete(false);
                return;
            } else if (e.key == "ArrowUp" || e.key == "ArrowDown") {
                const idx = $scope.filtroMensagensRapidas.indexOf($scope.mensagemRapidaSelecionada);
                const len = $scope.filtroMensagensRapidas.length - 1;

                $scope.mensagemRapidaSelecionada = e.key == "ArrowUp"
                    ? $scope.filtroMensagensRapidas[atendimentoUtils.clamp(idx - 1, 0, len)]
                    : $scope.filtroMensagensRapidas[atendimentoUtils.clamp(idx + 1, 0, len)];

                $scope.focarMensagemRapidaSelecionada();
            } else if (e.key === "Escape" || e.key === "Enter") {
                $scope.mostrarMensagensRapidas = false;
            } else {
                $scope.buscarMensagensRapidasAutocomplete(true);
            }

            $scope.getTextareaNovaMensagem().focus();

        } else {
            $scope.mostrarMensagensRapidas = false;
            $scope.mensagemRapidaSelecionada = null;
        }

        var scrollHeight = $scope.getTextareaNovaMensagem().get(0).scrollHeight;

        if (scrollHeight > 120) {
            scrollHeight = 120;
        }

        let footerHeight = 54;
        let removeMargin = 0;

        if ($scope.messageToReply) {
            footerHeight += 150;
            removeMargin = 150;
        }

        const pixelsHeight = footerHeight + (scrollHeight - 28);
        const pixelsHeightFooter = footerHeight + (scrollHeight - 30 - removeMargin);
        const scrollHeightContainer = scrollHeight + 15;

        let addMargin = 0;

        if (scrollHeight > 50) {
            addMargin = 18;

            var $textareaContainer = $('.container-textarea-msg');
            $textareaContainer.css('height', scrollHeightContainer + 'px');

            $scope.getTextareaNovaMensagem().css('height', scrollHeight + "px");
            if ($scope.privateMode) {
                $('.content-center').css('height', 'calc(100% - ' + (pixelsHeight + 68) + "px)");
            } else {
                $('.content-center').css('height', 'calc(100% - ' + (pixelsHeight + addMargin) + "px)");
            }
            $('.content-footer').css('height', (pixelsHeightFooter + addMargin) + "px");
        } else if ($scope.privateMode) {
            var $textareaContainer = $('.container-textarea-msg');
            $textareaContainer.css('height', scrollHeightContainer + 'px');

            $scope.getTextareaNovaMensagem().css('height', scrollHeight + "px");
            $('.content-center').css('height', 'calc(100% - ' + (pixelsHeight + 68) + "px)");
        }
    };

    $scope.getTextareaNovaMensagem = function () {
        if (!$(".mobile #novaMensagem").is(":hidden")) {
            return $('.mobile #novaMensagem');
        } else {
            return $('.mobile-hide #novaMensagem');
        }
    }

    $scope.resetTextArea = function () {
        let footerHeight = 45;

        var $textareaContainer = $('.container-textarea-msg');
        $textareaContainer.css('height', footerHeight + 'px');

        $scope.getTextareaNovaMensagem().css('height', "30px");
        if ($scope.messageToReply) {
            $('.content-center').css('height', "calc(100% - 220px)");
        } else {
            $('.content-center').css('height', "");
        }
        $('.content-footer').css('height', "");
        $('.content-emoji-list').css('bottom', "70px");

        setTimeout(function () {
            $scope.getTextareaNovaMensagem().focus();
        }, 500);

        if ($scope.privateMode) {
            let footerHeight = 45;

            var $textareaContainer = $('.container-textarea-msg');
            $textareaContainer.css('height', footerHeight + 'px');

            $scope.getTextareaNovaMensagem().css('height', "30px");
            if ($scope.messageToReply) {
                $('.content-center').css('height', "calc(100% - 275px)");
            } else {
                $('.content-center').css('height', "calc(100% - 125px)");
            }
            $('.content-footer').css('height', "");
            $('.content-emoji-list').css('bottom', "70px");
        }

        $scope.novaMensagem = {};
    };

    $scope.isMapsLink = function (message) {
        return message && message.indexOf("https://maps.google.com/?q") === 0;
    };

    $scope.isVoiceCall = (message) => {
        return message && message.type == 'voice_call';
    };

    $scope.isCallPermissionRequest = (message) => {
        return message && message.type == 'call_permission_request';
    };

    $scope.isButtonType = (message) => {
        return message && (message.type == 'button' || message.type == 'voice_call' || message.type == 'call_permission_request');
    };

    $scope.isButtonListType = (message) => {
        return message && message.type == 'list';
    };

