    $scope.onPaste = function (e) {
        const items = (e.clipboardData || e.originalEvent.clipboardData).files;

        for (const f of items) {
            $scope.readFile(f);
        }
    };

    $scope.showReplyMessage = function (mensagemPrincipal) {
        const ref = mensagemPrincipal.ref;

        if (!ref) return;

        const originalId = ref.originalId || ref.refId;
        const origem = mensagemPrincipal.origem;

        if ($scope.atendimentoSelecionado.status !== 'POTENCIAL') {
            $scope.showButtonPageBottom = true;
        }

        $scope.controlePaginacao.mensagens.stopScrollDownLoading = false;

        let $originalMessage;
        if (origem) {
            $originalMessage = $('#msg-' + originalId + '-' + origem);
        } else {
            $originalMessage = $('#msg-' + originalId);
        }

        let refImage = $scope.imagensAgrupadas.find(i => i.id == originalId);
        if (refImage != null) {
            return $scope.onVisualizarGrupoImagem(refImage);
        }

        if ($originalMessage.length) {
            $scope.controlePaginacao.mensagens.stopScrollLoading = true;
            $scope.animateReplyMessage(originalId, false, originalId, origem);
        } else {
            $scope.atendimentoSelecionado.mensagens = [];
            $scope.atendimentoSelecionado.loadingReplyMessage = true;

            const callback = function () {
                $scope.atendimentoSelecionado.loadingReplyMessage = false;
                $scope.controlePaginacao.mensagens.carregando = false;

                $timeout(function () {
                    const imagemRecarregada = $scope.imagensAgrupadas.find(i => i.id == originalId);
                    if (imagemRecarregada) {
                        return $scope.onVisualizarGrupoImagem(imagemRecarregada);
                    }

                    $scope.animateReplyMessage(originalId, true, 0, origem);
                }, 100);
            };

            $scope.recuperarMensagens(
                true,
                originalId,
                callback,
                originalId,
                origem,
                true,
                true
            );
        }
    };

    $scope.animateReplyMessage = function (id, requested, times, origem) {

        var $contentCenter = $("#atendimento-mensagens");
        var $originalMessage;

        if (origem) {
            $originalMessage = $('#msg-' + id + '-' + origem);
        } else {
            $originalMessage = $('#msg-' + id);
        }

        if (!$originalMessage.length) {
            if (times == 10) {
                $scope.controlePaginacao.mensagens.carregando = false;
                $scope.controlePaginacao.mensagens.stopScrollLoading = false;
                $scope.controlePaginacao.mensagens.scrollLoadingAutomatic == false;
                return;
            }

            setTimeout(function () {
                $scope.animateReplyMessage(id, requested, times + 1, origem);
            }, 500);

            return;
        }

        var scrollTop = $contentCenter.scrollTop() - (($originalMessage.position().top * -1)) - ($contentCenter.height() / 2);

        var showEffect = function () {
            setTimeout(function () {
                //Colocar o false devido a chamada para api ao efetuar 
                $scope.controlePaginacao.mensagens.stopScrollLoading = true;
                if (origem) {
                    $originalMessage = $('#msg-' + id + '-' + origem);
                } else {
                    $originalMessage = $('#msg-' + id);
                }

                $originalMessage.addClass("msg-focus");

                setTimeout(function () {
                    if (origem) {
                        $originalMessage = $('#msg-' + id + '-' + origem);
                    } else {
                        $originalMessage = $('#msg-' + id);
                    }

                    $originalMessage.removeClass("msg-focus");

                    $scope.controlePaginacao.mensagens.carregando = false;
                    $scope.controlePaginacao.mensagens.stopScrollLoading = false;
                }, 700);

            });
        };

        if (requested) {
            $scope.controlePaginacao.mensagens.scrollLoadingAutomatic = true;
            previousScrollTop = scrollTop;
        } else {
            previousScrollTop = $contentCenter.scrollTop();
        }

        $contentCenter.animate({ scrollTop: scrollTop }, 600, function () {
            showEffect();
        });

    };

    $scope.tratarTexto = function (texto, ignoreLink) {
        if (ignoreLink === "REF") {
            ignoreLink = false;
            if (texto.startsWith("{\"type\":\"")) {
                var parsedText = JSON.parse(texto);

                var extractedText = parsedText.body.text;

                texto = extractedText
            }
        }

        if (!ignoreLink && !$scope.isEmail() && texto) {
            texto = texto.replace(/(https?:\/\/[\w\.:%\+~#=\-\?\/]+)/g, '<a href="$1" target="_blank">$1</a>');

            // Menções (@Nome / @numero) são tratadas pela diretiva `mz-mentions` diretamente
            // no DOM (bypassa o ngSanitize e liga o clique no próprio elemento).

            if ($scope.isWhatsappApi() || $scope.isWhatsappWeb()) {
                var linkPlaceholders = [];
                texto = texto.replace(/<a\s[^>]*>.*?<\/a>/g, function(match) {
                    var placeholder = '\x00LINK' + linkPlaceholders.length + '\x00';
                    linkPlaceholders.push(match);
                    return placeholder;
                });

                texto = texto.replace(/\*(?!\*)\s*([^*]+?)\s*\*(?!\*)/g, '<b>$1</b>');
                texto = texto.replace(/(?<!\w)_([^_\n]+?)_(?!\w)/g, '<i>$1</i>');

                linkPlaceholders.forEach(function(link, i) {
                    texto = texto.replace('\x00LINK' + i + '\x00', link);
                });
            }
        }

        try {
            const data = JSON.parse(texto);

            if (data.type == 'button' && data.body) {
                texto = data.body.text;
            }
        } catch (e) { }

        if (texto) {
            texto = texto.replaceAll('\\n', '<br/>');
        }

        if ($scope.isEmail()) {
            var htmlEmail = texto;

            try {
                htmlEmail = $scope.ocultarMensagemCitada(texto);
            } catch (e) {
                console.error('Falha ao tratar mensagem de e-mail:', e);
            }

            return $sce.trustAsHtml(htmlEmail);
        }

        return texto;
    }

    $scope.getEmailSrcdoc = function (mensagem) {
        if (!mensagem) {
            return '';
        }

        if (!mensagem.hasOwnProperty('emailSrcdocCache') || mensagem.emailSrcdocFonte !== mensagem.mensagem) {
            mensagem.emailSrcdocFonte = mensagem.mensagem;
            mensagem.emailSrcdocCache = $scope.tratarTexto(mensagem.mensagem);
        }

        return mensagem.emailSrcdocCache;
    };

    $scope.ocultarMensagemCitada = function (texto) {
        if (!window.DOMParser || !window.XMLSerializer)
            return texto;

        var parser = new DOMParser();
        var XMLS = new XMLSerializer();

        var selectors = [
            "div[class='gmail_quote']", // Gmail quoted msg
            "div[id*='yahoo_quoted']", // Yahoo quoted msg
            "div[id$='divRplyFwdMsg']", // Outlook quoted msg
        ]

        // incluir jquery no iframe
        texto = "<script src='https://code.jquery.com/jquery-3.6.0.min.js'></script>" + texto;

        var msg = parser.parseFromString(texto, 'text/html');

        var msgCitada = $(msg.querySelectorAll(selectors.join(", ") + ", " + selectors.join(" ~ *, ") + " ~ *"));

        if (msgCitada) {
            var ellipsisButton = "<div style='cursor:pointer' class='m-t-10 m-b-10' onclick='$(this).children().first().next().toggle();' title='" + $translate.instant('MOSTRAR-OCULTAR-CONTEUDO') + "'><img src='img/email-ellipsis.png'></div>";
            msgCitada.wrapAll(ellipsisButton).wrapAll("<div style='display: none;'></div>");

        }

        return XMLS.serializeToString(msg);
    }

    $scope.findGroupMemberByName = function (nome) {
        var info = $scope.atendimentoSelecionado && $scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario;
        var participantes = (info && info.grupoInfo && info.grupoInfo.participantes) || [];

        if (!nome || !participantes.length) {
            return null;
        }

        var alvo = nome.toLowerCase();

        return participantes.find(function (p) { return p.nome && p.nome.toLowerCase() === alvo; })
            || participantes.find(function (p) { return p.nome && p.nome.toLowerCase().indexOf(alvo) === 0; })
            || participantes.find(function (p) { return p.nome && p.nome.toLowerCase().indexOf(alvo) !== -1; })
            || null;
    };

    $scope.iniciarConversaMencao = function (token) {
        if (!token) {
            return;
        }

        if (!$scope.atendimentoSelecionado || !$scope.atendimentoSelecionado.informacoes || !$scope.atendimentoSelecionado.informacoes.usuario) {
            return;
        }

        var numero;
        var nome;

        if (/^\d{10,15}$/.test(token)) {
            numero = token;
            nome = '+' + token;
        } else {
            var membro = $scope.findGroupMemberByName(token);

            if (!membro) {
                swal("Ops!", $translate.instant('MEMBRO-GRUPO-NAO-ENCONTRADO'), "info");
                return;
            }

            numero = ('' + membro.id).replace(/\D/g, '');
            nome = membro.nome || ('+' + numero);
        }

        if (!numero) {
            swal("Ops!", $translate.instant('MEMBRO-GRUPO-NAO-ENCONTRADO'), "info");
            return;
        }

        var canal = ($scope.canais || []).find(function (c) {
            return c.numero == $scope.atendimentoSelecionado.informacoes.usuario.whatsapp;
        });

        if (!canal) {
            swal("Ops!", $translate.instant('CHAT-VERIFIQUE-CANAL'), "error");
            return;
        }

        $rootScope.onMostrarModalCriarAtendimentoContatoCompartilhado(nome, '+' + numero);
    };

    $(document).off('click.mentionPhone').on('click.mentionPhone', 'a.mention-phone', function (e) {
        e.preventDefault();

        var token = ($(this).text() || '').replace(/^\s*@/, '').trim();

        if (!token) {
            return;
        }

        if ($scope.$$phase || $rootScope.$$phase) {
            $scope.iniciarConversaMencao(token);
        } else {
            $scope.$apply(function () {
                $scope.iniciarConversaMencao(token);
            });
        }
    });

    $scope.prepararZonaDeImagem = () => {
        let chatElement = angular.element("#atendimento-mensagens");
        let imagePreviewElement = angular.element("#image-preview");
        let fileDropOverlayElement = angular.element("#file-drop-overlay");
        let fileDropAreaElement = angular.element("#file-drop-area");

        document.onkeydown = function (evt) {
            if (evt.key == "Escape") {
                $scope.closePreview();
                $scope.$apply();
            }
        };

        document.onclick = function () {
            $('#file-drop-overlay').css('display', "none");
        }

        fileDropOverlayElement.on("dragend", function (e) {
            $('#file-drop-overlay').css('display', "none");
        });

        fileDropAreaElement.on("dragend", function (e) {
            $('#file-drop-overlay').css('display', "none");
        });

        chatElement.on("dragend", function (e) {
            $('#file-drop-overlay').css('display', "none");
        });

        imagePreviewElement.on("dragend", function (e) {
            $('#file-drop-overlay').css('display', "none");
        });

        //---- -----

        chatElement.on("dragenter", function (e) {
            $('#file-drop-overlay').css('display', "flex");
        });

        imagePreviewElement.on("dragenter", function (e) {
            $('#file-drop-overlay').css('display', "flex");
        });

        fileDropOverlayElement.on("dragleave", function (e) {
            e.preventDefault();
            e.stopPropagation();
            if (e.relatedTarget.id !== 'file-drop-overlay' && e.relatedTarget.id !== 'file-drop-area') {
                $('#file-drop-overlay').css('display', "none");
            }
        })

        fileDropAreaElement.on("dragover", function (e) {
            e.preventDefault();
            e.stopPropagation();
        })

        fileDropAreaElement.on("dragenter", function (e) {
            e.preventDefault();
            e.stopPropagation();
        });

        fileDropAreaElement.on("drop", function (e) {
            e.preventDefault();
            e.stopPropagation();
            $('.file-drop-overlay').css('display', "none");
            if (e.originalEvent.dataTransfer) {
                if (e.originalEvent.dataTransfer.files.length > 0) {
                    for (const f of e.originalEvent.dataTransfer.files) {
                        $scope.readFile(f);
                    }
                    $scope.$apply();
                }
            }
            return false;
        });
    }

