    $scope.isAnexoImagem = function (anexo) {
        if (!anexo || !anexo.url) {
            return false;
        }
        return (anexo.url.endsWith(".jpg") || anexo.url.endsWith(".jpeg") || anexo.url.endsWith(".png") || anexo.url.endsWith(".gif") || anexo.url.endsWith(".svg"));
    };

    $scope.isAnexoPdf = function (anexo) {
        if (!anexo || !anexo.url) {
            return false;
        }
        return anexo.url.endsWith(".pdf");
    };

    $scope.templatePossuiTagBody = function () {
        if ($scope.emailTemplateSelecionado && $scope.emailTemplateSelecionado.id) {
            return $scope.emailTemplateSelecionado.template.includes("{{body}}");
        } else if ($scope.atendimentoSelecionado && $scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.config && $scope.atendimentoSelecionado.informacoes.config.botEmailTemplatePadrao) {
            return $scope.atendimentoSelecionado.informacoes.config.botEmailTemplatePadrao.includes("{{body}}");
        }
    };

