    $scope.onModalPreVisualizarMensagem = function (templateSelecionado, exibirBotaoEnviar) {
        var mensagem = {};

        if ($scope.templatePossuiTagBody()) {
            $scope.replaceContactName($scope.novaMensagem);
        }

        if ($scope.novaMensagem) {
            mensagem = angular.copy($scope.novaMensagem);
        }

        if (templateSelecionado) {
            mensagem.emailTemplateIdSelecionado = templateSelecionado.id;
        }

        AtendimentoService.substituirTagsEmail($scope.atendimentoSelecionado.id, mensagem).then(result => {
            $scope.modalPreVisualizarMensagem = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/atendimentos/modal-pre-visualizar-mensagem.html?t=' + new Date(),
                size: 'lg',
                scope: $scope,
                controller: function () {
                    $scope.modalPreVisualizarMensagem.templateBotaoSelecionar = templateSelecionado;
                    $scope.modalPreVisualizarMensagem.exibirBotaoEnviar = exibirBotaoEnviar;
                    $scope.modalPreVisualizarMensagem.rendered.then(function () {
                        const html = result.data;
                        const iframe = document.createElement('iframe');
                        const blob = new Blob([html], { type: 'text/html' });
                        iframe.src = window.URL.createObjectURL(blob);
                        iframe.style.width = '100%';
                        iframe.style.height = '75%';
                        iframe.style.border = 'solid 1px #DDD';

                        $("#html-content").append(iframe);
                    });
                }
            });
        });
    };

    $scope.onCancelarModalPreVisualizarMensagem = function () {
        if ($scope.modalPreVisualizarMensagem) {
            $scope.modalPreVisualizarMensagem.close();
            $scope.modalPreVisualizarMensagem = null;
        }
    };

    $scope.exibirTemplateSemBody = function () {
        var mensagem = {};

        if ($scope.novaMensagem) {
            mensagem = angular.copy($scope.novaMensagem);
        }

        if ($scope.emailTemplateSelecionado) {
            mensagem.emailTemplateIdSelecionado = $scope.emailTemplateSelecionado.id;
        }

        AtendimentoService.substituirTagsEmail($scope.atendimentoSelecionado.id, mensagem).then(result => {
            const html = result.data;
            const iframe = document.createElement('iframe');
            const blob = new Blob([html], { type: 'text/html' });
            iframe.src = window.URL.createObjectURL(blob);
            iframe.style.width = '100%';
            iframe.style.height = '75%';
            iframe.style.border = 'solid 1px #DDD';

            $("#html-content-template").html(iframe);
        });
    };

