    $scope.getJoinedCCMessage = (cc, to, onlyName, forMe) => {
        let mailsToJoin = [];

        if (forMe) {
            mailsToJoin.push("para mim");
        } else if (to != null && to != "") {
            mailsToJoin.push(to);
        } else {
            mailsToJoin.push($scope.atendimentoSelecionado.informacoes.usuario.usuarioTelefone);
        }

        if (cc != null && cc.length > 0) {
            cc.forEach((p) => {
                if (p.name != null && p.name != "") {
                    mailsToJoin.push(p.name);
                } else if (p.email != null && p.email != "") {
                    mailsToJoin.push(onlyName != null ? p.email.split("@")[0] : p.email);
                }
            });
        }

        return mailsToJoin.join(", ");
    };

    $scope.getEmailMessageDetails = (message, forMe) => {
        let from = {};
        let to = {};
        let ccArray = [];

        if (forMe) {
            from.email = message.emailFrom != null ? message.emailFrom : $scope.atendimentoSelecionado.informacoes.usuario.usuarioTelefone;
            to.name = "mim";
        } else {
            to.email = message.emailFrom != null ? message.emailFrom : $scope.atendimentoSelecionado.informacoes.usuario.usuarioTelefone;
            from.name = "mim";
        }

        if (message.cc != null && message.cc.length > 0) {
            message.cc.forEach((p) => {
                ccArray.push({
                    "name": p.name,
                    "email": p.email
                });
            });
        }

        return {
            "forMe": forMe,
            "from": from,
            "to": to,
            "cc": ccArray
        };
    };


    // --- Templates de Mensagens --- //

    $scope.onMostarModalEscolhaTemplate = (telefone, departamentoId, onlyCallPermissionRequest) => {

        $scope.templateFiltro = { name: '' };
        $scope.templatesList = [];
        $scope.templateCurrentPage = 0;
        $scope.templateLimit = 20;
        $scope.loadingTemplates = false;
        $scope.hasMoreTemplates = false;
        $scope.selectedTemplateId = null;
        $scope.loadingTemplateDetails = false;
        $scope.previaTemplate = null;
        $scope.previaTemplateGeral = null;

        $scope.fetchTemplates = (append) => {
            $scope.loadingTemplates = true;
            var params = {
                module: 'HELPDESK',
                active: true,
                page: $scope.templateCurrentPage
            };
            if ($scope.templateFiltro.name) {
                params.name = $scope.templateFiltro.name;
            }
            WaTemplateService.getAllPagedByDepartment(telefone, departamentoId, params).then((response) => {
                if (append) {
                    $scope.templatesList = $scope.templatesList.concat(response.data);
                } else {
                    $scope.templatesList = response.data;
                }
                $scope.sortTemplates();
                $scope.hasMoreTemplates = response.data.length >= $scope.templateLimit;
                $scope.loadingTemplates = false;
            }).catch((error) => {
                console.error('Error fetching templates:', error);
                $scope.loadingTemplates = false;
            });
        };

        $scope.searchTemplates = () => {
            $scope.templateCurrentPage = 0;
            $scope.selectedTemplateId = null;
            $scope.previaTemplate = null;
            $scope.fetchTemplates(false);
        };

        $scope.loadMoreTemplates = () => {
            if ($scope.loadingTemplates || !$scope.hasMoreTemplates) return;
            $scope.templateCurrentPage++;
            $scope.fetchTemplates(true);
        };

        $scope.sortTemplates = () => {
            $scope.templatesList.sort((a, b) => {
                if (a.favorite && !b.favorite) return -1;
                if (!a.favorite && b.favorite) return 1;
                var nameA = (a.name || a.whatsappName || '').toLowerCase();
                var nameB = (b.name || b.whatsappName || '').toLowerCase();
                return nameA.localeCompare(nameB);
            });
        };

        $scope.toggleFavoriteTemplate = ($event, tmpl) => {
            $event.stopPropagation();
            var promise = tmpl.favorite
                ? WaTemplateService.unfavoriteTemplate(telefone, tmpl.id)
                : WaTemplateService.favoriteTemplate(telefone, tmpl.id);

            promise.then(() => {
                tmpl.favorite = !tmpl.favorite;
                $scope.sortTemplates();
            }).catch((error) => {
                console.error('Error toggling favorite:', error);
            });
        };

        $scope.replaceNamedVariablesInComponents = (components) => {
            if (!components) return;
            var nomeContato = '';
            var nomeAtendente = '';
            var protocolo = '';
            try { nomeContato = $scope.atendimentoSelecionado.informacoes.usuario.usuarioNome || ''; } catch (e) { }
            try { nomeAtendente = $rootScope.atendente.nome || ''; } catch (e) { }
            try { protocolo = $scope.atendimentoSelecionado.id || ''; } catch (e) { }

            components.forEach(component => {
                if (component.text) {
                    component.text = component.text
                        .replace(/\{\{nome_contato\}\}/g, nomeContato)
                        .replace(/\{\{nome_atendente\}\}/g, nomeAtendente)
                        .replace(/\{\{protocolo_atendimento\}\}/g, protocolo);
                }
            });
        };

        $scope.selecionarTemplate = (tmpl) => {
            $scope.selectedTemplateId = tmpl.id;
            $scope.loadingTemplateDetails = true;
            $scope.previaTemplate = null;

            WaTemplateService.getByIdWa(telefone, tmpl.id).then((response) => {
                var fullTemplate = response.data;
                fullTemplate.whatsappTemplateId = fullTemplate.id;
                fullTemplate.name = fullTemplate.whatsappName || tmpl.whatsappName;
                $scope.replaceNamedVariablesInComponents(fullTemplate.components);
                $scope.prepararComponentes(fullTemplate.components);
                $scope.visualizarTemplate(fullTemplate, true);
                $scope.loadingTemplateDetails = false;
            }).catch((error) => {
                console.error('Error fetching template details:', error);
                $scope.loadingTemplateDetails = false;
                swal("Erro!", "Não foi possível carregar o template", "error");
            });
        };

        $scope.selecionarTemplateById = (id) => {
            var tmpl = $scope.templatesList.find(t => t.id == id);
            if (tmpl) $scope.selecionarTemplate(tmpl);
        };

        $scope.fetchTemplates(false);

        $scope.modalAberto = true;
        $scope.modalEditarTemplates = $uibModal.open({
            animation: true,
            backdrop: 'static',
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/atendimentos/modal-escolha-template.html?t=' + Date.now(),
            scope: $scope,
            windowClass: 'custom-modal-alt mobile-fullscreen',
            controller: () => {

                $scope.prepararComponentes = (components) => {

                    if (components && components.length > 0) {
                        components.forEach(component => {
                            if (!component.parameters) {
                                component.parameters = [];
                            }

                            let qtParameters = 0;

                            if (component.type == 'BUTTONS') {
                                component.buttons.forEach(b => {
                                    if (b.type == 'URL') {
                                        qtParameters = $scope.getStringParameters(b.url);

                                        for (let i = 0; i < qtParameters; i++) {
                                            if (!b.parameters) { b.parameters = [] }

                                            if (!b.parameters[i]) {
                                                b.parameters[i] = { type: 'TEXTO', text: '', parameter: i + 1 };
                                            } else if (b.parameters[i].type == 'CONTATO_INFORMACAO' || b.parameters[i].contatoInformacaoId) {
                                                b.parameters[i].type = 'CONTATO_INFORMACAO';
                                                if ($scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario && $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais) {
                                                    let informacao = null;
                                                    if (b.parameters[i].contatoInformacaoId == 1) {
                                                        informacao = { valorOriginal: $scope.atendimentoSelecionado.informacoes.usuario.usuarioNome }
                                                    } else {
                                                        informacao = $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.find(ia => ia.contatoInformacaoId == b.parameters[i].contatoInformacaoId);
                                                    }

                                                    if (informacao) {
                                                        b.parameters[i].text = informacao.valorOriginal;
                                                    }
                                                }
                                            }
                                        }
                                    } else if (b.type == 'QUICK_REPLY') {
                                        if (!b.parameters) { b.parameters = [] }

                                        if (!b.parameters[0]) {
                                            b.parameters[0] = { type: 'TEXTO', text: b.text };
                                        }
                                    }
                                })
                            } else if (component.format == 'IMAGE' || component.format == 'DOCUMENT' || component.format == 'VIDEO') {
                                if (component.parameters && component.parameters.length > 0) {
                                    component.parameters[0].type = component.format;
                                    component.parameters[0].parameter = 1;
                                    component.parameters[0].componentType = component.type;
                                }
                            } else {
                                qtParameters = $scope.getStringParameters(component.text);

                                for (let i = 0; i < qtParameters; i++) {
                                    if (!component.parameters[i]) {
                                        component.parameters[i] = { type: 'TEXTO', text: '', parameter: i + 1 };
                                    } else if (component.parameters[i].type == 'CONTATO_INFORMACAO' || component.parameters[i].contatoInformacaoId) {
                                        component.parameters[i].type = 'CONTATO_INFORMACAO';
                                        if ($scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario) {
                                            let informacao = null;
                                            if (component.parameters[i].contatoInformacaoId == 1) {
                                                informacao = { valorOriginal: $scope.atendimentoSelecionado.informacoes.usuario.usuarioNome }
                                            } else if ($scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais) {
                                                informacao = $scope.atendimentoSelecionado.informacoes.usuario.informacoesAdicionais.find(ia => ia.contatoInformacaoId == component.parameters[i].contatoInformacaoId);
                                            }

                                            if (informacao) {
                                                component.parameters[i].text = informacao.valorOriginal;
                                            }
                                        }
                                    }
                                }
                            }
                        })
                    }
                }

                $scope.visualizarTemplate = (template, configuracaoGeral) => {
                    $scope.previaTemplate = template;

                    if (configuracaoGeral) {
                        $scope.previaTemplateGeral = template;
                    }

                    let isHeaderCustomizable = false;
                    let isBodyCustomizable = false;
                    let isButtonsCustomizable = false;

                    $scope.previaTemplate.components.forEach(component => {
                        if (component.type == 'HEADER') {
                            $scope.previaTemplate.headerType = component.format;
                            let isMediaHeader = component.format == 'IMAGE'
                                || component.format == 'VIDEO'
                                || component.format == 'DOCUMENT';

                            isHeaderCustomizable = ((component.format == 'TEXT' && $scope.getStringParameters(component.text) > 0) || isMediaHeader) || isHeaderCustomizable;

                            if (isMediaHeader && component.parameters && component.parameters.length > 0) {
                                var paramUrl = component.parameters[0].text;
                                if (paramUrl && paramUrl.indexOf('scontent.whatsapp.net') !== -1) {
                                    component.parameters[0].text = '';
                                    $scope.updateFileInput(null);
                                } else {
                                    $scope.selectHeaderFile(component, paramUrl);
                                }
                            } else {
                                $scope.updateFileInput(null);
                            }
                        }

                        isBodyCustomizable = (component.type == 'BODY' && $scope.getStringParameters(component.text) > 0) || isBodyCustomizable;

                        if (component.type == 'BUTTONS') {
                            let urlPreenchidaAutomaticamente = $scope.previaTemplate.webchatConversationCompativel === true;

                            component.buttons.forEach(button => {
                                let urlCustomizavel = button.type == 'URL' && !urlPreenchidaAutomaticamente && $scope.getStringParameters(button.url) > 0;

                                isButtonsCustomizable = button.type == 'QUICK_REPLY' || urlCustomizavel || isButtonsCustomizable
                            });
                        }

                    })

                    $scope.previaTemplate.isCustomizable = isHeaderCustomizable || isBodyCustomizable || isButtonsCustomizable;
                    $scope.previaTemplate.isHeaderCustomizable = isHeaderCustomizable;
                    $scope.previaTemplate.isBodyCustomizable = isBodyCustomizable;
                    $scope.previaTemplate.isButtonsCustomizable = isButtonsCustomizable;

                    updateComponentsAfterRequest();
                }

                $scope.getStringParameters = (text) => {
                    if (text) {
                        var matches = text.match(/{{[0-9]+}}/gm);
                        return matches ? matches.length : 0;
                    }
                    return 0;
                }

                $scope.renderComponentText = (component) => {
                    let text = component.text || "";

                    if (component.parameters) {
                        component.parameters.forEach(p => {
                            if (p.text) {
                                text = text.replace(`{{${p.parameter}}}`, p.text);
                            }
                        });
                    }

                    return $scope.tratarTexto(text);
                }

                $scope.processarComponentes = (components) => {
                    if (components && components.length > 0) {
                        components.forEach(component => {
                            $scope.processarParametros(component.parameters);
                        })
                    }
                }

                $scope.processarParametros = (parameters) => {
                    if (parameters && parameters.length > 0) {
                        parameters.forEach((parameterConfig, i) => {
                            parameterConfig.parameter = i + 1;
                        })
                    }
                }

                $scope.uploadFile = (file) => {
                    let component = null;

                    file = file ? file[0] : null;

                    $scope.previaTemplate.components.forEach(c => {
                        if (c.type == 'HEADER' && (c.format == 'IMAGE' || c.format == 'VIDEO' || c.format == 'DOCUMENT')) {
                            component = c;
                        }
                    })

                    if (file) {
                        if (component.format == 'DOCUMENT') {
                            if (!file.type.match("pdf")) {
                                $scope.updateFileInput(null)
                                return swal("Ops!", "Apenas arquivos PDF são aceitos para esse tipo de customização", "error");
                            }
                        }

                        if (component.format == 'IMAGE') {
                            if (!file.type.match("image/jpeg|image/png")) {
                                $scope.updateFileInput(null)
                                return swal("Ops!", "Apenas arquivos de imagem (JPG ou PNG) são aceitos para esse tipo de customização", "error");
                            }
                        }

                        if (component.format == 'VIDEO') {
                            if (!file.type.match("video/mp4|video/3gpp")) {
                                $scope.updateFileInput(null)
                                return swal("Ops!", "Apenas arquivos de vídeo (MP4 ou 3GP) são aceitos para esse tipo de customização", "error");
                            }
                        }

                        var reader = new FileReader();
                        reader.readAsDataURL(file);
                        reader.onload = function () {
                            FileService.insertBase64(reader.result, file.name).then(function (response) {
                                $scope.selectHeaderFile(component, response.data.url);
                            });
                        };
                    } else {
                        $scope.selectHeaderFile(component, null);
                    }
                }

                $scope.selectHeaderFile = (component, url) => {
                    if (component) {
                        if (!component.parameters) {
                            component.parameters = [];
                        }

                        if (component.parameters[0]) {
                            component.parameters[0].text = url;
                        } else {
                            component.parameters = [{ parameter: 1, text: url, type: component.format, componentType: component.type }];
                        }
                    }

                    if ($scope.previaTemplate) {
                        $scope.previaTemplate.headerImageUrl = url;
                    }

                    $scope.updateFileInput(url);
                }

                $scope.updateFileInput = (url) => {
                    if (url) {
                        $(`#image-input span.fileinput-new`).hide();
                        $(`#image-input span.fileinput-exists`).show();
                        $(`#image-input a.fileinput-exists`).show();
                    } else {
                        $(`#image-input span.fileinput-new`).show();
                        $(`#image-input span.fileinput-exists`).hide();
                        $(`#image-input a.fileinput-exists`).hide();
                    }
                };

                $scope.onEnviarMensagemTemplate = () => {
                    $scope.novaMensagem.template = angular.copy($scope.previaTemplate);

                    let error = false;

                    $scope.novaMensagem.template.components.forEach(component => {
                        if (error) { return; }

                        if (component.type == 'HEADER') {
                            let isMediaHeader = component.format == 'IMAGE'
                                || component.format == 'VIDEO'
                                || component.format == 'DOCUMENT';

                            let isHeaderCustomizable = ((component.format == 'TEXT' && $scope.getStringParameters(component.text) > 0) || isMediaHeader);

                            if (isHeaderCustomizable && $scope.getComponentParametersCount(component) != 1) {
                                error = true;
                                return swal("Ops!", "Todos os parâmetros do cabeçalho são obrigatórios", "error");
                            }
                        }

                        if (component.type == 'BODY' && $scope.getStringParameters(component.text) > 0 && ($scope.getComponentParametersCount(component) != $scope.getStringParameters(component.text))) {
                            error = true;
                            return swal("Ops!", "Todos os parâmetros do corpo são obrigatórios", "error");
                        }

                        if (component.type == 'BUTTONS') {
                            let urlPreenchidaAutomaticamente = $scope.novaMensagem.template.webchatConversationCompativel === true;

                            component.buttons.forEach(button => {
                                let urlCustomizavel = button.type == 'URL' && !urlPreenchidaAutomaticamente && $scope.getStringParameters(button.url) > 0;

                                if ((button.type == 'QUICK_REPLY' || urlCustomizavel) && $scope.getComponentParametersCount(button) != 1) {
                                    error = true;
                                    return swal("Ops!", "Todos os parâmetros dos botões são obrigatórios", "error");
                                }
                            });
                        }

                        if (component.text) {
                            component.text = $scope.renderComponentText(component);
                        }
                    });

                    if (!error) {
                        $scope.enviarMensagem('TEMPLATE');
                    }
                };

                $scope.getComponentParametersCount = (component) => {
                    let count = 0;

                    if (component.parameters && component.parameters.length > 0) {
                        count = component.parameters.filter(p => p.text).length;
                    }

                    return count;
                }

            }
        });

        $scope.modalEditarTemplates.rendered.then(function () {
            var container = angular.element('.template-list-container');
            if (container.length) {
                container.on('scroll', function () {
                    var el = this;
                    if (el.scrollHeight - el.scrollTop - el.clientHeight < 100) {
                        $scope.$apply(function () {
                            $scope.loadMoreTemplates();
                        });
                    }
                });
            }

            angular.element("#image-input")
                .on('change.bs.fileinput',
                    (event, data) => {
                        $scope.uploadFile(data);
                    });

            angular.element("#image-input")
                .on('clear.bs.fileinput',
                    (event) => {
                        $scope.uploadFile(null);
                    });
        });

    };

    $scope.modalAberto = false;

    $scope.onCloseModalEditarTemplates = () => {
        $scope.previaTemplate = null;
        $scope.previaTemplateGeral = null;

        if ($scope.modalEditarTemplates) {
            $scope.modalAberto = false;
            $scope.modalEditarTemplates.close();
        }
    }

    $scope.prepareTemplateData = (templateMessages) => {
        templateMessages.forEach(tm => {
            if (tm.tipoMensagem == 'TEMPLATE') {
                try {
                    tm.json = JSON.parse(tm.mensagem);
                    tm.json.components.forEach(component => {
                        if (component.format == 'IMAGE' || component.format == 'DOCUMENT' || component.format == 'VIDEO') {
                            if (component.parameters && component.parameters.length > 0) {
                                component.parameters[0].url = component.parameters[0].text ? `url(${component.parameters[0].text})` : null;
                            }
                        }
                    })
                } catch (ex) {
                    tm.tipoMensagem = 'TEXTO';
                }
            } else if (tm.tipoMensagem == 'CONTATOS') {
                if (tm.mensagem) {
                    try {
                        tm.json = JSON.parse(tm.mensagem);
                    } catch (ex) {
                        tm.tipoMensagem = 'TEXTO';
                    }
                }
            } else {
                try {
                    tm.json = JSON.parse(tm.mensagem);
                } catch (ex) { }
            }
        })
    }

    $scope.showComponentParameter = (component) => {
        let v = "";

        if (component.type == 'PHONE_NUMBER') {
            v = component.phoneNumber;
        } else if (component.type == 'URL') {
            v = angular.copy(component.url);
            if (component.parameters && component.parameters[0]) {
                v = v.replace(`{{1}}`, component.parameters[0].text)
            }
        } else if (component.type == 'QUICK_REPLY') {
            v = component.parameters[0].text
        }

        swal("O valor do texto é: ", v, "info");
    }

    $scope.showButtonList = (section) => {
        let v = "";

        section.forEach(s => {
            s.rows.forEach(r => {
                v += r.title + " \n ";
            })
        })

        swal("Os menus disponíveis são: ", v, "info");
    }

    $scope.responderMensagem = (message) => {
        $scope.messageToReply = message;
        $(".content-footer textarea").focus();
        $scope.onKeyPressMensagem();
    }

    $scope.iniciarModoApagarMensagem = (mensagem) => {
        $scope.modelDeleteMessages = true;
        $scope.mensagensParaDeletar = [mensagem];
        $scope.quantidadeSelecionadaDelete = 1;
        $('#msg-' + mensagem.id).addClass("msg-selected");
        $scope.$applyAsync();
    };

    $scope.cancelarApagarMensagens = () => {
        $scope.mensagensParaDeletar.forEach(m => $('#msg-' + m.id).removeClass("msg-selected"));
        $scope.modelDeleteMessages = false;
        $scope.mensagensParaDeletar = [];
        $scope.quantidadeSelecionadaDelete = 0;
    };

    $scope.confirmarApagarMensagens = () => {
        if (!$scope.mensagensParaDeletar.length) return;

        const atendimentoIds = [...new Set($scope.mensagensParaDeletar.map(m => m.painelAtendimentoId || 0))];

        if (atendimentoIds.length > 1) {
            swal($translate.instant("ATENCAO"), $translate.instant("DELETAR-MENSAGENS-ATENDIMENTOS-DIFERENTES"), "warning");
            return;
        }

        const atendimentoId = atendimentoIds[0];

        swal(
            {
                title: $translate.instant("ATENCAO"),
                text: $translate.instant("CONFIRMAR-APAGAR-MENSAGEM"),
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: $translate.instant("SIM"),
                cancelButtonText: $translate.instant("CANCELAR"),
                closeOnConfirm: false,
                closeOnCancel: true,
            },
            function (isConfirm) {
                if (isConfirm) {
                    const ids = $scope.mensagensParaDeletar.map(m => m.id);
                    AtendimentoService.deletarMensagens(atendimentoId, ids).then(function () {
                        $scope.mensagensParaDeletar.forEach(m => {
                            m.status = 'DELETED';
                            m.statusDate = new Date();
                            $('#msg-' + m.id).removeClass("msg-selected");
                        });
                        $scope.modelDeleteMessages = false;
                        $scope.mensagensParaDeletar = [];
                        $scope.quantidadeSelecionadaDelete = 0;
                        swal($translate.instant("SUCESSO"), $translate.instant("MENSAGEM-APAGADA-SUCESSO"), "success", 2000);
                    }).catch(function () {
                        swal($translate.instant("ERRO"), $translate.instant("ERRO-APAGAR-MENSAGEM"), "error");
                    });
                }
            }
        );
    };

    // Picker de reação do atendente (somente WhatsApp API oficial)
    $scope.emojiListControlReaction = {
        activeTab: 0,
        emojis: [],
        recentEmojis: [],
        mensagem: null
    };

    $scope.selectReactionEmojiTab = (index) => {
        if (!$scope.emojiList || !$scope.emojiList.length) {
            return;
        }

        index = index < 0
            ? 0
            : index > $scope.emojiList.length - 1
                ? $scope.emojiList.length - 1
                : index;

        $scope.emojiListControlReaction.activeTab = index;
        $scope.emojiListControlReaction.emojis = $scope.emojiList[index].emojis;
    };

    // Chamado pelo on-toggle do uib-dropdown quando o picker abre/fecha
    $scope.onToggleReactionPicker = (mensagem, open) => {
        if (!open) {
            return;
        }

        $scope.emojiListControlReaction.mensagem = mensagem;
        $scope.emojiListControlReaction.recentEmojis = $localStorage.recentEmojis || [];

        if (!$scope.emojiList || !$scope.emojiList.length) {
            const data = $resource("data/emoji.json").get();
            data.$promise.then(res => {
                const grouped = res.emojis.reduce((groups, item) => ({
                    ...groups,
                    [item.category]: [...(groups[item.category] || []), item]
                }), {});

                $scope.emojiList = [];
                Object.keys(grouped).forEach(c => {
                    $scope.emojiList.push({ name: c, icon: grouped[c][0].emoji, emojis: grouped[c] });
                });

                $scope.selectReactionEmojiTab($scope.emojiListControlReaction.activeTab || 0);
            });
        } else {
            $scope.selectReactionEmojiTab($scope.emojiListControlReaction.activeTab || 0);
        }
    };

    $scope.onSelecionarEmojiReacao = (emoji) => {
        const mensagem = $scope.emojiListControlReaction.mensagem;

        if (!mensagem) {
            return;
        }

        $scope.onReagirMensagem(mensagem, emoji);

        if (!$localStorage.recentEmojis) {
            $localStorage.recentEmojis = [];
        }

        if ($localStorage.recentEmojis.some(a => a == emoji)) {
            $localStorage.recentEmojis.splice($localStorage.recentEmojis.findIndex(a => a == emoji), 1);
        }

        $localStorage.recentEmojis = [emoji, ...$localStorage.recentEmojis];

        if ($localStorage.recentEmojis.length > 40) {
            $localStorage.recentEmojis = $localStorage.recentEmojis.slice(0, 50);
        }

        $scope.emojiListControlReaction.recentEmojis = $localStorage.recentEmojis;

        // Fecha o picker após reagir
        mensagem.reactPickerOpen = false;
        $scope.emojiListControlReaction.mensagem = null;
    };

    $scope.onReagirMensagem = (mensagem, emoji) => {
        if (!mensagem) {
            return;
        }

        const refUid = mensagem.originalUid ? mensagem.originalUid : mensagem.uid;

        if (!refUid) {
            swal($translate.instant("ATENCAO"), $translate.instant("ERRO-REAGIR-MENSAGEM"), "warning");
            return;
        }

        const atendimentoId = $scope.atendimentoSelecionado.id;

        if (!mensagem.complemento) {
            mensagem.complemento = {};
        }

        // Toggle: clicar na reação já aplicada remove a reação (envia emoji vazio)
        const reacaoAnterior = mensagem.complemento.lastReaction;
        const emojiEnviar = reacaoAnterior === emoji ? "" : emoji;

        // Atualização otimista; o socket UPDATE_ITEM confirma lastReaction/historyReactions
        mensagem.complemento.lastReaction = emojiEnviar;

        const registro = [{
            tipo: "REACTION",
            mensagem: emojiEnviar,
            refUid: refUid
        }];

        AtendimentoService.enviarMensagemAtendente(atendimentoId, registro).catch(function () {
            mensagem.complemento.lastReaction = reacaoAnterior;
            swal($translate.instant("ERRO"), $translate.instant("ERRO-REAGIR-MENSAGEM"), "error");
        });
    };

    $scope.cancelarResponderMensagem = () => {
        $scope.messageToReply = null;
        $scope.onKeyPressMensagem();
    }

    $scope.onMostrarModalCompartilharContato = () => {
        $scope.filtroContatos = '';
        $scope.agenda.filtroContatosModal = '';
        $scope.refreshAgenda();
        $scope.contatosACompartilharList = [];
        $scope.contatosACompartilhar = {}
        $scope.modalCompartilharContato = $uibModal.open({
            animation: true,
            backdrop: 'static',
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/atendimentos/modal-compartilhar-contato.html?t=' + Date.now(),
            scope: $scope,
            size: 'md',
        });
    }

    // ---------------- Envio de localização ----------------

    $scope.onMostrarModalEscolhaLocalizacao = (departamentoId) => {
        $scope.localizacaoFiltro = { nome: '' };
        $scope.localizacoesList = [];

        LocalizacaoService.getByDepartamento(departamentoId).then((response) => {
            $scope.localizacoesList = response.data || [];
        });

        $scope.modalEscolhaLocalizacao = $uibModal.open({
            animation: true,
            backdrop: 'static',
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/atendimentos/modal-escolha-localizacao.html?t=' + Date.now(),
            scope: $scope,
            size: 'md',
        });
    }

    $scope.onFecharModalEscolhaLocalizacao = () => {
        if ($scope.modalEscolhaLocalizacao) {
            $scope.modalEscolhaLocalizacao.close();
        }
    }

    $scope.onEnviarLocalizacao = (localizacao) => {
        if (!localizacao || !localizacao.latitude || !localizacao.longitude) {
            return;
        }

        let isWhatsappOficial = ($scope.atendimentoSelecionado.informacoes.usuario.whatsappOficial);
        let mapsUrl = "https://maps.google.com/?q=" + localizacao.latitude + "," + localizacao.longitude;

        $scope.novaMensagem.mensagem = mapsUrl;

        if (isWhatsappOficial) {
            // canal oficial: envia mensagem nativa de localização
            $scope.novaMensagem.nome = localizacao.nome;
            $scope.novaMensagem.endereco = localizacao.endereco;
            $scope.enviarMensagem('LOCATION');
        } else {
            // demais canais WhatsApp: envia como link do Google Maps (texto)
            $scope.enviarMensagem();
        }

        $scope.onFecharModalEscolhaLocalizacao();
    }

    $scope.selectAllContact = (contatoId) => {
        $scope.getSelectedAgenda().filter((i) => i.id == contatoId)[0].contatos.forEach(e => {
            $scope.contatosACompartilhar[contatoId][e.id] = $scope.contatosACompartilhar[contatoId][0]
        });
    }

    $scope.selectContact = (contatoId, campoId) => {
        if (!$scope.contatosACompartilhar[contatoId][campoId]) {
            if ($scope.contatosACompartilhar[contatoId][0]) {
                $scope.contatosACompartilhar[contatoId][0] = false;
            }
        } else {
            let anyUnselected = false;

            $scope.getSelectedAgenda().filter((i) => i.id == contatoId)[0].contatos.forEach(e => {
                if (!$scope.contatosACompartilhar[contatoId][e.id]) {
                    anyUnselected = true;
                }
            });

            if (!anyUnselected) {
                $scope.contatosACompartilhar[contatoId][0] = true;
            }
        }
    }

    $scope.onCompartilharContatos = () => {
        let isWhatsappOficial = ($scope.atendimentoSelecionado.informacoes.usuario.whatsappOficial);

        $scope.contatosACompartilharList = [];
        Object.entries($scope.contatosACompartilhar).forEach(entry => {
            let contato = $scope.getSelectedAgenda().find(c => c.id == entry[0]);
            if (contato && entry[1]) {
                let contatoCompartilhado = {
                    name: {
                        formattedName: contato.nome,
                        firstName: contato.nome
                    }
                }

                if (contato.contatos && contato.contatos.length > 0) {
                    contato.contatos.forEach(e => {
                        if (entry[1][e.id]) {
                            switch (e.tipo) {
                                case 'TELEFONE':
                                    let formattedPhone = e.contato.replaceAll("+", "").replaceAll(" ", "").replaceAll("-", "").replaceAll("(", "").replaceAll(")", "");
                                    if (!contatoCompartilhado.phones) contatoCompartilhado.phones = [];
                                    contatoCompartilhado.phones = [...contatoCompartilhado.phones, { phone: formattedPhone, waId: formattedPhone, type: e.observacao }];
                                    break;

                                case 'EMAIL':
                                    if (!contatoCompartilhado.emails) contatoCompartilhado.emails = [];
                                    contatoCompartilhado.emails = [...contatoCompartilhado.emails, { email: e.contato, type: e.observacao }];
                                    break;

                                case 'EMPRESA':
                                    if (!contatoCompartilhado.org) contatoCompartilhado.org = {};
                                    let company = e.contato;
                                    contatoCompartilhado.org = { ...contatoCompartilhado.org, company };
                                    break;

                                case 'SITE':
                                    if (!contatoCompartilhado.urls) contatoCompartilhado.urls = [];
                                    contatoCompartilhado.urls = [...contatoCompartilhado.urls, { url: e.contato, type: e.observacao }];
                                    break;

                                case 'ENDERECO':
                                    if (!contatoCompartilhado.addresses) contatoCompartilhado.addresses = [];
                                    contatoCompartilhado.addresses = [...contatoCompartilhado.addresses, { street: e.contato, type: e.observacao }];
                                    break;

                                case 'DATA_ANIVERSARIO':
                                    contatoCompartilhado.birthday = e.contato;
                                    break;
                            }
                        }
                    })
                }

                $scope.contatosACompartilharList.push(contatoCompartilhado);
            }
        })

        if ($scope.contatosACompartilharList.length > 0) {
            $scope.novaMensagem.contacts = $scope.contatosACompartilharList;

            if (isWhatsappOficial) {
                $scope.enviarMensagem('CONTATOS');
            } else {
                $scope.MontarMensagemContatos();
                $scope.enviarMensagem();
            }

            $scope.contatosACompartilhar = [];
            $scope.onFecharModalNovoRegistroAgenda();
        } else {
            swal("Atenção", "Escolha ao menos um contato para ,compartilhar", "info");
        }
    }

    $scope.MontarMensagemContatos = () => {
        let msgsContatos = [];
        $scope.novaMensagem.contacts.forEach(contact => {
            let msg = '*' + contact.name.formattedName + '*\n';

            contact.phones?.forEach(item => { msg += ' ' + item.phone + '\n' });
            contact.emails?.forEach(item => { msg += ' ' + item.email + '\n' });
            contact.org?.forEach(item => { msg += ' ' + item.org + '\n' });
            contact.urls?.forEach(item => { msg += ' ' + item.url + '\n' });
            contact.addresses?.forEach(item => { msg += ' ' + item.street + '\n' });

            if (contact.birthday) {
                msg += ' ' + contact.birthday;
            }

            msgsContatos.push(msg);
        });

        $scope.novaMensagem.mensagem = msgsContatos.join('\n');
    }

