    $scope.recuperarMensagemInfo = (mensagem) => {
        const json = JSON.parse(mensagem.mensagem);
        let message = "";

        if (json.message == "AGENT_JOIN" || json.message == "AGENT_EXIT" || json.message == "AGENT_SELF_EXIT" || json.message == "AGENT_CHANGE_ADMIN") {
            message = json.parameters.map(param => `<b>${param}</b> ${$translate.instant(json.message)}`).join('<br>');
        }

        return message;
    }

