    $scope.onSelectContact = (registro) => {
        if (registro && registro.contatos && registro.contatos.length > 0) {
            const canal = $scope.novoAtendimentoNovoContato.canal.canal;
            const tipo = canal == 'EMAIL' ? 'EMAIL' : 'TELEFONE';
            const contatoAgenda = registro.contatos.find(c => c.tipo == tipo);

            const nome = registro.nome;
            const contato = contatoAgenda ? contatoAgenda.contato : registro.contatos[0].contato;

            $scope.novoAtendimentoNovoContato.nome = nome;
            $scope.novoAtendimentoNovoContato.telefone = contato;
            $scope.itl.setNumber(contato)

            $scope.onModalAgendaCancel();
        } else {
            const nome = registro.contactName ? registro.contactName : registro.nome;
            const contato = registro.contactNumber ? registro.contactNumber : registro.telefone;
            $scope.novoAtendimentoNovoContato.nome = nome;
            $scope.novoAtendimentoNovoContato.telefone = contato;
            $scope.itl.setNumber(contato)

            $scope.onModalAgendaCancel();
        }
    };

