    $scope.adminFilterAttendance = (departamento, atendimentoTipo, atendente) => {
        if (atendimentoTipo) {
            switch (atendimentoTipo) {
                case 'TICKET_ACTIVE':
                    $scope.abaAtendimentos = 'ATIVOS';
                    break;
                case 'TICKET_ACTIVE_NEW_MESSAGE':
                    $scope.abaAtendimentos = 'NOVAS_MENSAGENS';
                    break;
                case 'TICKET_PENDING':
                    $scope.abaAtendimentos = 'PENDENTES';
                    break;
            }
        }

        let channel = $scope.compositeFilter.channelAdmin;

        $scope.compositeFilter = {};

        $scope.compositeFilter.channelAdmin = channel;

        if (atendente) $scope.compositeFilter.atendenteId = atendente.id;

        if (departamento) $scope.compositeFilter.departments = [{ id: departamento.id, name: departamento.name }];

        $scope.onCompositeFilter();
    }

