    $scope.getMemberGrupoFoto = function (mensagem) {

        //GRUPO
        if ($scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario && $scope.atendimentoSelecionado.informacoes.usuario.grupoInfo && $scope.atendimentoSelecionado.informacoes.usuario.grupoInfo.participantes) {
            var participante = $scope.atendimentoSelecionado.informacoes.usuario.grupoInfo.participantes.find(p => p.id == mensagem.numero)

            if (participante && participante.foto && participante.foto.url) {
                return participante.foto.url;
            }
        }

        //ATENDENTE
        if (mensagem.atendenteId && $scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.participantes) {
            var participante = $scope.atendimentoSelecionado.informacoes.participantes.find(p => p.id == mensagem.atendenteId)

            if (participante && participante.url) {
                return participante.url;
            }
        }

        return 'https://v2.mz-cdn.com/21ba3b59c8a0b27783fc3267b5b6a820/no-user.png';
    }

    $scope.getMemberGroupColor = function (mensagem, nome) {
        if ($scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario && $scope.atendimentoSelecionado.informacoes.usuario.grupoInfo && mensagem.tipo === 'USUARIO' && nome) {
            return $scope.getColorFromString(nome);
        }

        return '';
    }

    $scope.getMemberName = function (mensagem) {

        //verificando se é um grupo
        if ($scope.atendimentoSelecionado.informacoes && $scope.atendimentoSelecionado.informacoes.usuario && $scope.atendimentoSelecionado.informacoes.usuario.grupoInfo && mensagem.tipo === 'USUARIO') {

            //verificando se o nome é igual o número (por algum motivo o bot não mandou o nome)
            if (mensagem.nome == mensagem.numero) {

                //verificando se o número está entre os membros do grupo atual
                var participante = $scope.atendimentoSelecionado.informacoes.usuario.grupoInfo.participantes.find(p => p.id == mensagem.numero)

                if (participante && participante.nome) {
                    return participante.nome;
                }
            }

        }

        return mensagem.nome ? mensagem.nome : 'Contato';
    }

    $scope.getColorFromString = function (text) {
        if (!text) {
            return '';
        }

        let sum = 0;
        let n = text;

        for (let index in n) {
            sum += n.charCodeAt(index);
        }

        return $scope.colors[(sum % $scope.colors.length)];
    }

