    $scope.carregarAudioBase64 = function (fileUrl) {
        $http.get(fileUrl, { responseType: 'arraybuffer' }).then(function (response) {
            const blob = new Blob([response.data], { type: 'audio/ogg' });
            const reader = new FileReader();

            reader.onloadend = function () {
                $scope.mensagem.audioBase64 = reader.result;
                $scope.$apply();
            };

            reader.readAsDataURL(blob);
        });
    };

