    $scope.menuVisible = false;
    $scope.menuPosition = { x: 0, y: 0 };
    $scope.selectedText = "";

    $scope.menuTargetsJadi = {};

    $scope.checkSelection = function (event, message, isInputChat) {
        if (!$scope.permissions.permissionIAs) {
            return
        }

        $scope.mensagemSelecionadaJadi = message;

        $scope.selectedText = window.getSelection().toString().trim();

        if ($scope.selectedText.length === 0) {
            return;
        }

        event.preventDefault();

        if (Array.isArray($scope.menuTargetsJadi.menuTextSelection)) {
            $scope.menuTargetsJadi.menuTextSelection.forEach(function (btn) {
                btn.openSub = false;
            });
        }

        $scope.menuPosition.x = event.pageX;
        $scope.menuPosition.y = event.pageY;
        $scope.menuVisible = true;
        $scope.isInputChat = isInputChat;
    };

    $scope.closeSelectText = () => {
        $scope.menuVisible = false;
        $scope.selectedText = "";
    }

    $scope.openJadi = function (text, isReference, id, nome) {
        if (!$scope.permissions.permissionIAs) {
            return;
        }

        if ($scope.atendimentoSelecionado.id < 1) {
            return
        }

        const mensagem = (text !== undefined && text !== null && text !== "") ? text : $scope.selectedText;

        if (mensagem) {
            $scope.menuVisible = false;

            if (isReference) {
                let messageToReply = {
                    id: id,
                    nome: nome || $scope.mensagemSelecionadaJadi.nome,
                    tipoMensagem: "TEXTO",
                    mensagem: mensagem
                };

                $rootScope.$broadcast('jadiEvent', {
                    open: true,
                    message: "",
                    chatId: $scope.atendimentoSelecionado.id,
                    messageToReply
                });
            } else {
                $rootScope.$broadcast('jadiEvent', {
                    open: true,
                    message: mensagem,
                    chatId: $scope.atendimentoSelecionado.id
                });
            }

            if (!text) {
                $scope.selectedText = "";
                if ($scope.isInputChat) {
                    $scope.getTextareaNovaMensagem().css('height', "30px");
                    $('.content-center').css('height', "");
                    $('.content-footer').css('height', "");
                    $scope.novaMensagem = {};
                }
            }
        }
    };

    $scope.openJadiChat = function (sendText) {
        if (!$scope.permissions.permissionIAs) {
            return
        }

        if (sendText) {
            $rootScope.$broadcast('jadiEvent', { open: true, message: $scope.novaMensagem.mensagem, chatId: $scope.atendimentoSelecionado.id });

            $scope.getTextareaNovaMensagem().css('height', "30px");
            $('.content-center').css('height', "");
            $('.content-footer').css('height', "");

            $scope.novaMensagem = {};
        } else {
            $rootScope.$broadcast('jadiEvent', { open: true, message: "", chatId: $scope.atendimentoSelecionado.id });
        }
    };

