    $scope.dataProductsInfo = function (json) {
        let jsonObject = JSON.parse(json);
        return jsonObject;
    };

    $scope.getTotalValue = function (json) {
        let jsonObject = $scope.dataProductsInfo(json);

        if (!jsonObject || !Array.isArray(jsonObject.product_items)) {
            return 0;
        }

        let totalValue = 0;

        jsonObject.product_items.forEach(function (product) {
            totalValue += product.item_price * product.quantity;
        });

        return totalValue;
    };

    $scope.getTotalQuantity = function (json) {
        let jsonObject = $scope.dataProductsInfo(json);

        if (!jsonObject || !Array.isArray(jsonObject.product_items)) {
            return 0;
        }

        let totalQuantity = 0;

        jsonObject.product_items.forEach(function (product) {
            totalQuantity += product.quantity;
        });

        return totalQuantity;
    };

    $scope.getCurrency = function (json) {
        let jsonObject = $scope.dataProductsInfo(json);

        if (!jsonObject || !Array.isArray(jsonObject.product_items)) {
            return 0;
        }

        let currency = "BRL";

        currency = jsonObject.product_items[0].currency;
        return currency;
    };

