    $scope.adicionarCarteiraContatos = () => {
        AtendimentoService.adicionarCarteiraContatos($scope.atendimentoSelecionado.id).then(resp => {
            swal("Carteira de Contatos", "Contato adicionado com sucesso!", "success");
            $scope.atendimentoSelecionado.informacoes.carteiraContatos.minhaCarteira = true;
        });
    };

