materialAdmin.controller('LocalizacaoListaController', function ($scope, $state, $translate, $uibModal, LocalizacaoService, DepartamentoService) {

    $scope.registroAtual = {};
    $scope.todasLocalizacoes = [];
    $scope.departamentos = [];
    $scope.filtro = { status: 'TODOS', departamentoId: '' };

    $scope.onInit = function () {
        DepartamentoService.getAtivos().then(function (response) {
            $scope.departamentos = response.data || [];
            updateComponentsAfterRequest();
        });

        LocalizacaoService.getTodos().then(function (response) {
            $scope.todasLocalizacoes = response.data || [];
            $scope.aplicarFiltros();
            updateComponentsAfterRequest();
        });
    };

    $scope.aplicarFiltros = function () {
        var status = $scope.filtro.status;
        var departamentoId = $scope.filtro.departamentoId;

        var filtradas = ($scope.todasLocalizacoes || []).filter(function (loc) {
            var ativo = (loc.ativo === true || loc.ativo === 'true');

            if (status === 'ATIVOS' && !ativo) {
                return false;
            }

            if (status === 'INATIVOS' && ativo) {
                return false;
            }

            if (departamentoId) {
                var vinculada = (loc.departamentos || []).some(function (d) {
                    return d.id == departamentoId;
                });

                if (!vinculada) {
                    return false;
                }
            }

            return true;
        });

        $scope.totalFiltrado = filtradas.length;
        $scope.registros = listToMatrix(filtradas, 3);

        updateComponentsAfterRequest();
    };

    $scope.onMostarModalRegistro = function () {
        $scope.registroAtual = {};

        $scope.modalRegistro = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/localizacoes/modal-novo-registro.html',
            scope: $scope
        });
    };

    $scope.onModalEnviar = function () {
        if (!$scope.registroAtual.nome) {
            swal("Ops!", $translate.instant('NOME'), "error");
            return;
        }

        $scope.registroAtual.ativo = true;

        LocalizacaoService.inserir($scope.registroAtual).then(function (response) {
            $scope.onModalCancelar();
            $state.go("cadastros.localizacao_edicao", { id: response.data.id });
        });
    };

    $scope.onModalCancelar = function () {
        $scope.modalRegistro.close();
        $scope.registroAtual = {};
    };

    $scope.onRemover = function (registro) {
        localizacaoUtils.remover($translate, LocalizacaoService, registro, function () {
            $scope.onInit();
        });
    };

});

materialAdmin.controller('LocalizacaoEdicaoController', function ($scope, $translate, $state, $stateParams, $timeout, LocalizacaoService, DepartamentoService) {

    $scope.registro = {};
    $scope.departmentsBoard = [];
    $scope.selectedDepartments = [];
    $scope.departmentFilter = '';
    $scope.selectedDepartmentFilter = '';
    $scope.mapsLink = { value: '' };

    var map = null;
    var marker = null;

    var DEFAULT_CENTER = [-14.235, -51.925];
    var DEFAULT_ZOOM = 4;
    var POINT_ZOOM = 16;

    $scope.onInit = function () {
        LocalizacaoService.get($stateParams.id).then(function (response) {
            $scope.registro = response.data;

            if (!$scope.registro.departamentos) {
                $scope.registro.departamentos = [];
            }

            carregarDepartamentos();

            updateComponentsAfterRequest();

            $timeout(function () {
                initMap();
            }, 300);
        });
    };

    function carregarDepartamentos() {
        DepartamentoService.getAtivos().then(function (response) {
            var todos = (response.data || []).map(function (d) {
                return { id: d.id, name: d.nome, selected: false };
            });

            var selecionadosIds = ($scope.registro.departamentos || []).map(function (d) { return d.id; });

            $scope.selectedDepartments = todos.filter(function (d) {
                return selecionadosIds.indexOf(d.id) !== -1;
            });

            $scope.departmentsBoard = todos.filter(function (d) {
                return selecionadosIds.indexOf(d.id) === -1;
            });
        });
    }

    $scope.toggleSelection = function (department) {
        department.selected = !department.selected;
    };

    $scope.moveDepartments = function (direction) {
        if (direction === 'right') {
            moveSelected($scope.departmentsBoard, $scope.selectedDepartments);
        } else if (direction === 'left') {
            moveSelected($scope.selectedDepartments, $scope.departmentsBoard);
        } else if (direction === 'double-right') {
            moveAll($scope.departmentsBoard, $scope.selectedDepartments);
        } else if (direction === 'double-left') {
            moveAll($scope.selectedDepartments, $scope.departmentsBoard);
        }
    };

    function moveSelected(fromList, toList) {
        for (var i = fromList.length - 1; i >= 0; i--) {
            if (fromList[i].selected) {
                fromList[i].selected = false;
                toList.push(fromList[i]);
                fromList.splice(i, 1);
            }
        }
    }

    function moveAll(fromList, toList) {
        while (fromList.length) {
            fromList[0].selected = false;
            toList.push(fromList.shift());
        }
    }

    function initMap() {
        if (typeof L === 'undefined') {
            return;
        }

        if (L.Icon && L.Icon.Default) {
            L.Icon.Default.imagePath = 'vendors/leaflet/images/';
        }

        var lat = parseFloat($scope.registro.latitude);
        var lng = parseFloat($scope.registro.longitude);
        var temPonto = !isNaN(lat) && !isNaN(lng);

        map = L.map('localizacao-map').setView(
            temPonto ? [lat, lng] : DEFAULT_CENTER,
            temPonto ? POINT_ZOOM : DEFAULT_ZOOM
        );

        L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            maxZoom: 19,
            attribution: '&copy; OpenStreetMap'
        }).addTo(map);

        if (temPonto) {
            criarMarcador(lat, lng);
        }

        map.on('click', function (e) {
            setPonto(e.latlng.lat, e.latlng.lng);
        });

        $timeout(function () {
            map.invalidateSize();
        }, 200);
    }

    function criarMarcador(lat, lng) {
        marker = L.marker([lat, lng], { draggable: true }).addTo(map);

        marker.on('dragend', function () {
            var pos = marker.getLatLng();
            setPonto(pos.lat, pos.lng, false);
        });
    }

    function setPonto(lat, lng, moverMapa) {
        var latStr = lat.toFixed(7);
        var lngStr = lng.toFixed(7);

        $scope.$applyAsync(function () {
            $scope.registro.latitude = latStr;
            $scope.registro.longitude = lngStr;
        });

        if (!marker) {
            criarMarcador(lat, lng);
        } else {
            marker.setLatLng([lat, lng]);
        }

        if (moverMapa !== false && map) {
            map.setView([lat, lng], Math.max(map.getZoom(), POINT_ZOOM));
        }
    }

    $scope.onCoordChange = function () {
        var lat = parseFloat($scope.registro.latitude);
        var lng = parseFloat($scope.registro.longitude);

        if (isNaN(lat) || isNaN(lng) || !map) {
            return;
        }

        setPonto(lat, lng);
    };

    $scope.onMapsLinkChange = function () {
        var coords = localizacaoUtils.parseCoords($scope.mapsLink.value);

        if (!coords) {
            return;
        }

        $scope.registro.latitude = coords[0];
        $scope.registro.longitude = coords[1];
        $scope.mapsLink.value = '';

        setPonto(parseFloat(coords[0]), parseFloat(coords[1]));
    };

    $scope.onSalvar = function () {
        if (!$scope.registro.nome) {
            swal("Ops!", $translate.instant('NOME'), "error");
            return;
        }

        if (!$scope.registro.latitude || !$scope.registro.longitude) {
            swal("Ops!", $translate.instant('CLIQUE-MAPA-SELECIONAR'), "error");
            return;
        }

        $scope.registro.departamentos = ($scope.selectedDepartments || []).map(function (d) {
            return { id: d.id, nome: d.name };
        });

        LocalizacaoService.atualizar($scope.registro).then(function () {
            swal({
                title: $translate.instant('PRONTO') + "!",
                text: $translate.instant('REGISTRO-ATUALIZADO'),
                type: "success",
                timer: 2000
            }, function () {
                $state.go("cadastros.localizacoes");
            });
        });
    };

    $scope.onRemover = function () {
        localizacaoUtils.remover($translate, LocalizacaoService, $scope.registro, function () {
            $state.go("cadastros.localizacoes");
        });
    };

});

