        $scope.isSupervisorChatbot = function (data) {
            let valid = $scope.jwt !== undefined
    ? $scope.jwt.usuarioPerfil === Perfil.SUPERVISOR_CHATBOT
    : false;

            if (valid && data) {

                if (!$scope.permissions) {
                    return false;
                }

                let module = $scope.permissions.permissionPages?.find(m => m.module == data.module);

                if (!module) {
                    return false;
                }

                if (!data.page && !data.pages) {
                    return true;
                }

                let pages = data.pages;

                if (data.page) {
                    pages = [data.page];
                }

                let page = module.pages.find(p => pages.includes(p.name));
                return page != undefined
            } else {
                return valid;
            }
        };

