        $scope.socketMainEvents = [];
        $scope.socketMainEventsRunning = false;

        $scope.socketMainInterval = setInterval(function () {
            if ($scope.socketMainEventsRunning) {
                SocketUtil.addLog("PENDING EVENTS: " + $scope.socketMainEvents.length);
                return;
            }

            $scope.socketMainEventsRunning = true;

            if ($scope.socketMainEvents.length) {
                var waiting;

                try {
                    waiting = $scope.socketMainEvents[0]();

                    if (!waiting) {
                        $scope.$apply();
                    }
                } catch (e) {
                    console.error('socket-interval-error', e);
                } finally {
                    if (!waiting) {
                        $scope.socketMainEvents.splice(0, 1);
                    }
                }
            }

            $scope.socketMainEventsRunning = false;
        }, 500);

        $scope.startSocket = function () {

            //mensagem de aviso

            FirebaseUtil.settings.onGetNotification($location.host().replaceAll(".", "_"), function () {
                if (!$rootScope.pendenciasFinanceiras) {
                    $scope.getConfiguracoes();
                }
            });

            //notificações

            SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/users/' + $scope.jwt.usuarioUuid + '/notifications', (data) => {
                SocketUtil.addLog('CLIENTS.USERS.NOTIFICATIONS: ' + JSON.stringify(data));

                let socketEvent = () => {
                    if (data.eventType === "ADD_ITEM") {
                        return $scope.addNotification(data);
                    } else if (data.eventType === "REMOVE_ITEM") {
                        return $scope.removeNotification(data);
                    } else if (data.eventType === "REMOVE_ALL") {
                        return $scope.removeAllNotification();
                    } else {
                        return
                    }
                }

                $scope.socketMainEvents.push(socketEvent);
            });

            SocketUtil.startListener('clients/' + $scope.jwt.clienteUuid + '/users/' + $scope.jwt.usuarioUuid + '/calls', (data) => {
                SocketUtil.addLog('CLIENTS.USERS.CALLS: ' + JSON.stringify(data));

                let socketEvent = () => {
                    WaCallWebRTCService.processEvent(data);
                }

                $scope.socketMainEvents.push(socketEvent);
            });
        }

        $scope.addNotification = function (data) {
            $scope.permissions = $scope.permissions || {};
            $scope.userNotifications = $scope.userNotifications || [];

            $scope.permissions.totalNotifications = ($scope.permissions.totalNotifications || 0) + 1;
            $scope.$apply();

            var newNotification = data.notification;

            var existingNotificationIndex = $scope.userNotifications.findIndex(function (notification) {
                return notification.id === newNotification.id;
            });

            if (existingNotificationIndex > -1) {
                $scope.userNotifications[existingNotificationIndex] = newNotification;
            } else {
                $scope.userNotifications.push(newNotification);
            }

            if (newNotification.crmTaskId) {
                $scope.openInTask(newNotification.crmTaskId);
            }

            if (newNotification.type == "SOLICITACAO_PARTICIPACAO") {
                $scope.openInSolicitation(newNotification);
            }

            // $scope.dadosNotificacao = newNotification;

            // $scope.modalNotificationInfo = $uibModal.open({
            //     animation: true,
            //     ariaLabelledBy: 'modal-title-top',
            //     ariaDescribedBy: 'modal-body-top',
            //     templateUrl: 'views/crm/modal-info-notification.html',
            //     scope: $scope,
            //     size: 'lg'
            // })
        };

        $scope.removeNotification = function (data) {
            if ($scope.permissions.totalNotifications > 0) {
                $scope.permissions.totalNotifications--;
            }

            if ($scope.userNotifications.length) {
                const notificationIndex = $scope.userNotifications.findIndex(function (notification) {
                    return notification.id == data.notification.id;
                });

                if (notificationIndex > -1) {
                    $scope.userNotifications.splice(notificationIndex, 1);
                }
            }
        };

        $scope.removeAllNotification = function () {
            if ($scope.permissions.totalNotifications > 0) {
                $scope.permissions.totalNotifications = 0;
            }

            $scope.userNotifications = [];
        };



/* =====================================================
   INICIALIZAÇÃO DO PAINEL N3BOT
   JWT armazenado em cookie HttpOnly
===================================================== */

var materialAdminCtrl = this;
materialAdminCtrl.headerEnabled = false;

function redirecionarParaLogin() {
    SocketUtil.disconnect();

    $localStorage.deliveryMerchant = undefined;
    $localStorage.token = undefined;
    $localStorage.n3bot_token = undefined;
    $localStorage.usuario = undefined;

    $scope.jwt = undefined;
    $scope.permissions = {};

    materialAdminCtrl.headerEnabled = false;

    $window.location.replace("login.html");
}

function obterEmpresaId(usuario) {
    if (!usuario) {
        return null;
    }

    var empresa = usuario.empresa;

    return $localStorage.empresaId ||
        usuario.empresaId ||
        usuario.empresa_id ||
        usuario.idEmpresa ||
        (typeof empresa === "string" ? empresa : null) ||
        (empresa && typeof empresa === "object"
            ? empresa.id || empresa.empresaId || empresa.codigo
            : null) ||
        null;
}

function carregarPainel(usuario, empresaId) {
    usuario.empresaId = empresaId;

    $scope.jwt = usuario;

    $localStorage.usuario = usuario;
    $localStorage.empresaId = empresaId;

    if (
        !usuario.empresa ||
        typeof usuario.empresa !== "object"
    ) {
        $localStorage.empresa = {
            id: empresaId
        };
    } else {
        $localStorage.empresa = usuario.empresa;
    }

    materialAdminCtrl.headerEnabled = true;

    TutorialVideoService.getAll()
        .then(function (response) {
            var tutoriais = [];

            angular.forEach(response.data || [], function (modulo) {
                tutoriais = tutoriais.concat(
                    modulo.tutoriais || []
                );
            });

            $scope.tutoriais = tutoriais;
        })
        .catch(function (error) {
            console.error("Erro ao carregar tutoriais:", error);
        });

    if ($scope.isMegaZap() && $scope.isGestor()) {
        SalesInvoiceService.getExpiredFromMegaZap()
            .then(function (response) {
                $scope.expiredInvoices =
                    response.data && response.data.summary;

                if (
                    $scope.expiredInvoices &&
                    $scope.expiredInvoices.count > 0
                ) {
                    $scope.modalExpired = $uibModal.open({
                        animation: true,
                        ariaLabelledBy: "modal-title-top",
                        ariaDescribedBy: "modal-body-top",
                        templateUrl:
                            "template/modal-expired-invoices.html",
                        scope: $scope,
                        windowClass: "app-modal-news"
                    });
                }
            })
            .catch(function (error) {
                console.error("Erro ao carregar faturas:", error);
            });
    }

    $scope.getConfiguracoes();

    if (usuario.clienteUuid && usuario.usuarioUuid) {
        $scope.startSocket();
    } else {
        console.warn(
            "WebSocket não iniciado: clienteUuid ou usuarioUuid ausente."
        );
    }
}

// O cookie HttpOnly não pode ser lido pelo JavaScript.
// Portanto, não verificar $localStorage.token.

