        $scope.getSelectedDeliveryMerchant = () => {
            if (!$scope.deliveryMerchants.length) {
                return;
            }

            if (!$localStorage.deliveryMerchant) {
                $scope.selectedMerchant = $scope.deliveryMerchants[0];
                $localStorage.deliveryMerchant = $scope.selectedMerchant.id;
                return $state.reload();
            } else {
                $scope.selectedMerchant = $scope.deliveryMerchants.find((m) => {
                    return m.id.toString() === $localStorage.deliveryMerchant.toString();
                });
            }

            DeliveryPaymentMethodService.getTranslation($localStorage.deliveryMerchant).then((response) => {
                DeliveryPaymentMethodService.paymentMethodsTranslation = response.data;

                var newsLevelDelivery = 10;

                if (!$localStorage.newsDelivery || $localStorage.newsDelivery < newsLevelDelivery) {
                    $localStorage.newsDelivery = newsLevelDelivery;

                    $scope.modalNews = $uibModal.open({
                        animation: true,
                        ariaLabelledBy: 'modal-title-top',
                        ariaDescribedBy: 'modal-body-top',
                        templateUrl: 'template/modal-news-delivery.html?t=' + new Date(),
                        scope: $scope,
                        controller: function ($scope, $uibModalInstance) {
                            $scope.close = function () {
                                $uibModalInstance.dismiss('cancel');
                            };
                        },
                        windowClass: 'app-modal-news'
                    });
                }
            });

            $scope.isMerchantPaused();
        }

        $scope.getSelectedGMClientName = function () {
            if ($localStorage.gm !== undefined) {
                const gm = JSON.parse($localStorage.gm);

                if (!gm.cucli && gm.licli && gm.licli.length > 0) {
                    gm.cucli = gm.licli[0];
                    $localStorage.gm = JSON.stringify(gm)
                }

                return gm.cucli.nome;
            }

            return false;
        };

        $scope.getSelectedDeliveryMerchantName = function () {
            return $scope.selectedMerchant ? $scope.selectedMerchant.name : "";
        };

        $scope.isPoSScreen = function () {
            return $state.current.$state.originalPath == 'delivery.pos';
        };

        $scope.getSelectedDeliveryRegisterMachine = function () {
            var name = 'Nenhum caixa aberto';

            if (!$scope.deliveryMerchants.length || !$scope.selectedMerchant) {
                return name;
            }

            var registerMachine = $localStorage.registerMachine;

            if (registerMachine) {
                if ($scope.selectedMerchant.registerMachines) {
                    $scope.selectedRegisterMachine = $scope.selectedMerchant.registerMachines.find(function (m) {
                        return m.id.toString() === registerMachine.toString();
                    });

                    if ($scope.selectedRegisterMachine) {
                        name = $scope.selectedRegisterMachine.name;
                    }
                }
            } else {
                $scope.selectedRegisterMachine = null;
            }

            return name;
        };

        $scope.selectDeliveryMerchant = function (merchant) {
            $localStorage.deliveryMerchant = merchant.id;

            if (merchant.franchiseConfiguration) {
                $state.go("delivery.customizations");
            } else {
                $state.reload();
            }
        };

        $scope.hasFranchiseConfiguration = () => {
            return $scope.deliveryMerchants.find(m => m.franchiseConfiguration);
        }

        $scope.updateOpenMerchant = function (open) {
            var merchant = angular.copy($scope.selectedMerchant);
            merchant.open = open;

            swal({
                title: "Atenção!",
                text: merchant.open ? 'Deseja realmente abrir seu estabelecimento?' : "Deseja realmente fechar seu estabelecimento?",
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: "Sim",
                cancelButtonText: "Cancelar",
                closeOnConfirm: true,
                closeOnCancel: true
            }, function (isConfirm) {
                if (isConfirm) {
                    DeliveryMerchantService.updateOpen(merchant).then(function (response) {
                        $scope.selectedMerchant.open = open;
                    });
                }
            });
        }

        $scope.showModalMerchantPause = function () {
            $scope.modalMerchantPause = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'template/modal-merchant-pause.html',
                scope: $scope
            });
        }

        $scope.isMerchantPaused = function () {
            if ($scope.merchantPausedInterval || !$scope.selectedMerchant.pauseAt) {
                return;
            }

            $scope.merchantPausedInterval = setInterval(function () {
                $scope.selectedMerchant.paused = $scope.selectedMerchant.pauseAt > new Date().getTime();
                $scope.$apply();

                if (!$scope.selectedMerchant.paused) {
                    clearInterval($scope.merchantPausedInterval);
                    $scope.merchantPausedInterval = null;
                }
            }, 1000);
        }

        $scope.updatePauseAt = function () {
            if ($scope.selectedMerchant.minutesToPause <= 0) {
                swal("Pausa", "Informe uma pausa maior que 1 minuto.", 'error');
                return;
            }

            DeliveryMerchantService.updatePauseAt($scope.selectedMerchant).then(function (response) {
                $scope.selectedMerchant.pauseAt = response.data.pauseAt;
                $scope.selectedMerchant.paused = true;

                $scope.onCloseModalMerchantPause();
                $scope.isMerchantPaused();
            });
        }

        $scope.clearPauseAt = function () {
            swal({
                title: "Atenção!",
                text: 'Deseja realmente abrir seu estabelecimento?',
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: "Sim",
                cancelButtonText: "Cancelar",
                closeOnConfirm: true,
                closeOnCancel: true
            }, function (isConfirm) {
                if (isConfirm) {
                    var merchant = angular.copy($scope.selectedMerchant);
                    merchant.minutesToPause = 0;

                    DeliveryMerchantService.updatePauseAt(merchant).then(function (response) {
                        $scope.selectedMerchant.pauseAt = null;
                        $scope.selectedMerchant.paused = false;
                    });
                }
            });
        }

        $scope.onCloseModalMerchantPause = function () {
            if ($scope.modalMerchantPause) {
                delete $scope.selectedMerchant.minutesToPause;
                $scope.modalMerchantPause.close();
            }
        };

        $scope.onCloseModalExpired = function () {
            if ($scope.modalExpired) {
                $scope.modalExpired.close();
            }
        };

