        $scope.splitArray = function (array, delimiter) {
            var newArray = array.split(delimiter);
            newArray = newArray.map(element => {
                return element.trim();
            })
            newArray = newArray.filter(function (item, index, inputArray) {
                return inputArray.indexOf(item) == index;
            });
            newArray = $filter("orderBy")(newArray)
            return newArray;
        }

        $scope.merchantHasModulePermission = function (module) {
            switch (module.name) {
                case 'Caixa':
                    if (!$scope.selectedMerchant) return false;
                    else return $scope.selectedMerchant.registerMachinePermission && (($scope.isOperador() && $scope.permissions.user && $scope.permissions.user.permissionRegisterMachine) || !$scope.isOperador());
                case 'Mesas':
                    if (!$scope.selectedMerchant) return false;
                    else return $scope.selectedMerchant.tableOrderPermission && (($scope.isOperador() && $scope.permissions.user && $scope.permissions.user.permissionTableOrder) || !$scope.isOperador());
                default:
                    return true;
            }
        };

        $scope.userHasModulePermission = function (module) {
            switch (module.name) {
                case 'Caixa':
                    if (!$scope.selectedMerchant) return false;
                    else return $scope.selectedMerchant.registerMachinePermission;
                case 'Mesas':
                    if (!$scope.selectedMerchant) return false;
                    else return $scope.selectedMerchant.tableOrderPermission;
                default:
                    return true;
            }
        };

