        $scope.getFormattedDate = function (notification) {
            const createdAt = new Date(notification.createdAt);
            const now = new Date();

            const isToday = createdAt.toDateString() === now.toDateString();
            if (isToday) {
                return createdAt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            } else {
                return createdAt.toLocaleDateString() + ' ' + createdAt.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
            }
        };

        $scope.getTimeDifference = function (notification) {
            const createdAt = new Date(notification.createdAt);
            const now = new Date();
            const diffInMs = now - createdAt;

            const diffInMinutes = Math.floor(diffInMs / (1000 * 60));
            const diffInHours = Math.floor(diffInMs / (1000 * 60 * 60));
            const diffInDays = Math.floor(diffInMs / (1000 * 60 * 60 * 24));

            if (diffInMinutes < 60) {
                return diffInMinutes + " min atrás";
            } else if (diffInHours < 24) {
                return diffInHours + " horas atrás";
            } else if (diffInDays <= 7) {
                return diffInDays + " dias atrás";
            } else if (diffInDays <= 30) {
                return "Mais de uma semana atrás";
            } else {
                return createdAt.toLocaleDateString();
            }
        };

        $scope.atendimentosAtivos = {};
