       function obterPerfilUsuario() {
    return $scope.jwt && $scope.jwt.usuarioPerfil
        ? $scope.jwt.usuarioPerfil
        : null;
}

$scope.isSupervisorRevenda = function () {
    return obterPerfilUsuario() === Perfil.SUPERVISOR_REVENDA;
};

$scope.isAcessoTotal = function () {
    return obterPerfilUsuario() === Perfil.ACESSO_TOTAL;
};

$scope.isSupervisorChatbot = function (data) {
    var valid = obterPerfilUsuario() === Perfil.SUPERVISOR_CHATBOT;

    if (!valid || !data) {
        return valid;
    }

    if (!$scope.permissions ||
        !$scope.permissions.permissionPages) {
        return false;
    }

    var module = $scope.permissions.permissionPages.find(function (m) {
        return m.module === data.module;
    });

    if (!module) {
        return false;
    }

    if (!data.page && !data.pages) {
        return true;
    }

    var pages = data.page ? [data.page] : data.pages;

    if (!module.pages || !Array.isArray(pages)) {
        return false;
    }

    return module.pages.some(function (page) {
        return pages.includes(page.name);
    });
};

$scope.isSupervisorDelivery = function () {
    return obterPerfilUsuario() === Perfil.SUPERVISOR_DELIVERY;
};

$scope.isOperador = function () {
    return obterPerfilUsuario() === Perfil.OPERADOR;
};

$scope.isGarcom = function () {
    return obterPerfilUsuario() === Perfil.GARCOM;
};

$scope.isAdministrador = function () {
    return obterPerfilUsuario() === Perfil.ADMINISTRADOR;
};

$scope.isRevendedor = function () {
    return obterPerfilUsuario() === Perfil.REVENDEDOR;
};

$scope.isParceiroIndicacao = function () {
    return obterPerfilUsuario() === Perfil.PARCEIRO_INDICACAO;
};

$scope.isAtendente = function () {
    return obterPerfilUsuario() === Perfil.ATENDENTE;
};

