$scope.onLogout = function () {
    try {
        SocketUtil.disconnect();
    } catch (e) {
        console.error('Erro ao desconectar socket:', e);
    }

    var logoutConcluido = false;

    function removerCookie(nome) {
        var dominios = [
            null,
            'n3bot.com.br',
            '.n3bot.com.br',
            'app.n3bot.com.br',
            '.app.n3bot.com.br'
        ];

        var caminhos = ['/', '/app'];

        dominios.forEach(function (dominio) {
            caminhos.forEach(function (caminho) {
                var cookie =
                    nome +
                    '=; Max-Age=0; expires=Thu, 01 Jan 1970 00:00:00 GMT' +
                    '; path=' + caminho +
                    '; SameSite=Lax';

                if (dominio) {
                    cookie += '; domain=' + dominio;
                }

                if (window.location.protocol === 'https:') {
                    cookie += '; Secure';
                }

                document.cookie = cookie;
            });
        });
    }

    function limparSessao() {
        if (logoutConcluido) return;
        logoutConcluido = true;

        try {
            if ($rootScope.exitAtendente) {
                $rootScope.exitAtendente();
            }
        } catch (e) {
            console.error('Erro ao encerrar atendimento:', e);
        }

        // Remove os dados de autenticação locais.
        [
            'token',
            'n3bot_token',
            'n3bot_refresh',
            'jwt',
            'usuario',
            'empresa',
            'empresaId',
            'deliveryMerchant',
            'registerMachine',
            'gm'
        ].forEach(function (chave) {
            try {
                delete $localStorage[chave];
            } catch (e) {}
        });

        // Limpa a sessão da aba.
        [
            'empresaId',
            'empresa',
            'token',
            'usuario',
            'n3bot_token',
            'n3bot_refresh',
            'jwt'
        ].forEach(function (chave) {
            try {
                sessionStorage.removeItem(chave);
            } catch (e) {}
        });

        // Remove cookies acessíveis ao JavaScript.
        [
            'token',
            'n3bot_token',
            'n3bot_refresh',
            'jwt',
            'empresaId'
        ].forEach(removerCookie);

        try {
            $localStorage.$apply();
        } catch (e) {
            console.warn('Não foi possível aplicar alterações:', e);
        }

        // Redireciona mesmo se alguma limpeza falhar.
        $window.location.replace('login.html');
    }

    // O logout do servidor é necessário para apagar
    // cookies HttpOnly e invalidar o refresh token.
    var logoutServidor = $http.post(
        'https://auth.n3bot.com.br/auth/logout',
        {},
        {
            withCredentials: true
        }
    );

    var atualizarStatus;

    try {
        if ($rootScope.exitAtendente) {
            atualizarStatus = UsuarioService.atualizarOnline({
                online: false,
                fcmToken: $localStorage.fcmtoken,
                logout: true
            });
        }
    } catch (e) {
        console.error('Erro ao atualizar status:', e);
    }

    // Não deixa uma falha de rede impedir o logout local.
    var tarefas = [logoutServidor];

    if (atualizarStatus && angular.isFunction(atualizarStatus.finally)) {
        tarefas.push(atualizarStatus);
    }

    $q.allSettled
        ? $q.allSettled(tarefas).finally(limparSessao)
        : $q.all(
            tarefas.map(function (tarefa) {
                return tarefa.catch(function (erro) {
                    console.error('Falha durante logout:', erro);
                    return null;
                });
            })
        ).finally(limparSessao);
};




