materialAdmin.factory('TasksService', function ($http, $setting) {

    var service = {};

    function url(endpoint) {

        var api = $setting.api || '';

        if (api.charAt(api.length - 1) === '/') {
            api = api.substring(0, api.length - 1);
        }

        if (endpoint.charAt(0) !== '/') {
            endpoint = '/' + endpoint;
        }

        return api + endpoint;
    }


    service.getAll = function (params) {

        return $http.get(
            url('/tasks'),
            {
                params: params
            }
        );
    };


    service.getById = function (id) {

        return $http.get(
            url('/tasks/' + id)
        );
    };


    service.create = function (data) {

        return $http.post(
            url('/tasks'),
            data
        );
    };


    service.update = function (id, data) {

        return $http.put(
            url('/tasks/' + id),
            data
        );
    };


    service.done = function (id, data) {

        return $http.post(
            url('/tasks/' + id + '/done'),
            data || {}
        );
    };


    service.cancel = function (id, data) {

        return $http.post(
            url('/tasks/' + id + '/cancel'),
            data || {}
        );
    };


    service.getUsers = function () {

        return $http.get(
            url('/usuarios/auth_web.json')
        );
    };


    return service;
});

materialAdmin.controller('TasksController', function (
    $scope,
    TasksService
) {

    $scope.taskData = [];

    $scope.usuarios = [];

    $scope.hasMore = false;

    $scope.page = 0;

    $scope.loading = false;

    $scope.isCalendarVisible = false;


    $scope.filtro = {
        name: '',
        status: '',
        responsibleId: '0',
        executorId: '0',
        finishedStartDate: '',
        finishedEndDate: ''
    };


    /*
     * INICIO
     */
    $scope.onInit = function () {

        $scope.page = 0;

        $scope.taskData = [];

        $scope.loadUsers();

        $scope.getAll();
    };


    /*
     * USUÁRIOS
     */
    $scope.loadUsers = function () {

        TasksService.getUsers()

            .then(function (response) {

                var data = response.data;

                if (angular.isArray(data)) {

                    $scope.usuarios = data;

                } else if (
                    data &&
                    angular.isArray(data.data)
                ) {

                    $scope.usuarios = data.data;

                } else if (
                    data &&
                    angular.isArray(data.usuarios)
                ) {

                    $scope.usuarios = data.usuarios;

                } else {

                    $scope.usuarios = [];
                }

            })

            .catch(function (error) {

                console.error(
                    'Erro ao carregar usuários',
                    error
                );

                $scope.usuarios = [];
            });
    };


    /*
     * FILTROS
     */
    function getParams() {

        var params = {
            page: $scope.page
        };


        if ($scope.filtro.name) {

            params.name =
                $scope.filtro.name;
        }


        if ($scope.filtro.status) {

            params.status =
                $scope.filtro.status;
        }


        if (
            $scope.filtro.responsibleId &&
            $scope.filtro.responsibleId !== '0'
        ) {

            params.responsibleId =
                $scope.filtro.responsibleId;
        }


        if (
            $scope.filtro.executorId &&
            $scope.filtro.executorId !== '0'
        ) {

            params.executorId =
                $scope.filtro.executorId;
        }


        if ($scope.filtro.finishedStartDate) {

            params.finishedStartDate =
                $scope.filtro.finishedStartDate;
        }


        if ($scope.filtro.finishedEndDate) {

            params.finishedEndDate =
                $scope.filtro.finishedEndDate;
        }


        return params;
    }


    /*
     * LISTAR
     */
    $scope.getAll = function () {

        if ($scope.loading) {
            return;
        }

        $scope.loading = true;


        TasksService.getAll(
            getParams()
        )

        .then(function (response) {

            var data = response.data;

            var tarefas = [];


            if (angular.isArray(data)) {

                tarefas = data;

            } else if (
                data &&
                angular.isArray(data.data)
            ) {

                tarefas = data.data;

            } else if (
                data &&
                angular.isArray(data.tasks)
            ) {

                tarefas = data.tasks;

            } else if (
                data &&
                angular.isArray(data.content)
            ) {

                tarefas = data.content;
            }


            if ($scope.page === 0) {

                $scope.taskData = tarefas;

            } else {

                $scope.taskData =
                    $scope.taskData.concat(tarefas);
            }


            if (data && data.hasMore !== undefined) {

                $scope.hasMore = data.hasMore;

            } else {

                $scope.hasMore =
                    tarefas.length > 0;
            }

        })

        .catch(function (error) {

            console.error(
                'Erro ao buscar tarefas',
                error
            );

            if ($scope.page === 0) {

                $scope.taskData = [];
            }

        })

        .finally(function () {

            $scope.loading = false;
        });
    };


    /*
     * MAIS
     */
    $scope.nextPage = function () {

        if (
            !$scope.hasMore ||
            $scope.loading
        ) {
            return;
        }


        $scope.page++;

        $scope.getAll();
    };


    /*
     * CALENDÁRIO
     */
    $scope.toggleCalendar = function () {

        $scope.isCalendarVisible =
            !$scope.isCalendarVisible;
    };


    /*
     * OBSERVAÇÃO
     */
    $scope.openObservation = function (text) {

        if (!text) {
            return;
        }

        alert(text);
    };


    /*
     * EDITAR / VISUALIZAR
     */
    $scope.onOpenModalTask = function (
        edit,
        id,
        task,
        readonly
    ) {



        /*
         * Seu modal existente entra aqui.
         */
    };


    /*
     * CONCLUIR / CANCELAR
     */
    $scope.onOpenModalTaskDone = function (
        cancel,
        id
    ) {

        if (!id) {
            return;
        }


        if (cancel) {

            TasksService.cancel(id)

                .then(function () {

                    $scope.reload();

                })

                .catch(function (error) {

                    console.error(
                        'Erro ao cancelar tarefa',
                        error
                    );
                });

        } else {

            TasksService.done(id)

                .then(function () {

                    $scope.reload();

                })

                .catch(function (error) {

                    console.error(
                        'Erro ao concluir tarefa',
                        error
                    );
                });
        }
    };


    /*
     * RECARREGAR
     */
    $scope.reload = function () {

        $scope.page = 0;

        $scope.taskData = [];

        $scope.getAll();
    };

});
