materialAdmin.controller('MegaZapInvoiceListController', function ($scope, $window, $filter, $httpParamSerializer, $localStorage, SalesCustomerService, SalesInvoiceService, RevendaService) {

    $scope.filtro = {};
    $scope.filtro.offset = 0;
    $scope.filtro.hasBankSlip = 'true';

    $scope.showMore = true;

    $scope.onInit = function () {
        $scope.getInvoices();
    };

    $scope.getCustomers = function (text) {
        var params = {
            text: text,
            type: "CONSUMER"
        };

        return SalesCustomerService.getActivesToOptions(params).then(function (response) {
            return response.data.map(function (item) {
                return item;
            });
        });
    };

    $scope.downloadNfse = function (registro) {
        var params = "t=" + $localStorage.token.substr("Bearer ".length);
        $window.open("api/sales/invoices/" + registro.uuid + "/nfse/download?" + params);
    };

    $scope.getInvoices = function (offset) {
        if (!offset) {
            $scope.filtro.offset = 0;
        } else {
            $scope.filtro.offset += offset;
        }

        if ($scope.filtro.customerReseller) {
            $scope.filtro.customerResellerId = $scope.filtro.customerReseller.id;
        } else {
            delete $scope.filtro.customerResellerId;
        }

        SalesInvoiceService.getAllFromMegaZap($scope.filtro).then(function (response) {
            updateComponentsAfterRequest();

            if (!offset) {
                $scope.registros = [];
            }

            if (response.data.data) {
                $scope.registros = $scope.registros.concat(response.data.data);
            }

            $scope.summary = response.data.summary;

            $scope.showMore = response.data.data && response.data.data.length > 0;
        });
    };

    $scope.openBankSlip = function (registro) {
        var url = `https://app.mzworkspace.com/cobranca.html?id=${registro.iuguId}`;
        window.open(url);
    };

    $scope.download = function () {
        var params = $httpParamSerializer($scope.filtro);
        params += "&t=" + $localStorage.token.substr("Bearer ".length);

        $window.open("api/sales/invoices/megazap/download?" + params);
    };

});

