    // ========================================
    // RESET DE SENHA
    // ========================================

    $scope.onInitResetPassword = function () {
        var paramToken = $scope.obterParametro('token');

        if (!paramToken) {
            $window.location.href = 'index.html#';
            return;
        }

        RevendaService.getCustomizacaoPorDominio({
            dominio: $location.host()
        }).then(function (response) {
            $scope.customizacao = response.data;
            document.title = response.data.nome;
        });

        UsuarioService.validateToken(paramToken).then(function (response) {
            $scope.registro.token = paramToken;
            $scope.registro.usuarios = response.data || [];
            $scope.newUser = false;

            if ($scope.registro.usuarios.length === 1) {
                $scope.newUser =
                    $scope.registro.usuarios[0].isNew;
            }

            if ($scope.newUser) {
                $scope.showUsuarios = false;
                $scope.showPassword = true;
            } else if ($scope.registro.usuarios.length > 1) {
                $scope.showUsuarios = true;
                $scope.showPassword = false;
            } else {
                $scope.showUsuarios = false;
                $scope.showPassword = true;
            }
        });

        if (!$localStorage.lang ||
            ['pt-BR', 'en-US', 'zh-CN', 'es-ES']
                .indexOf($localStorage.lang) === -1) {

            $translate.use('pt-BR');
            $locale.id = 'pt-BR';
            $localStorage.lang = 'pt-BR';
        } else {
            $translate.use($localStorage.lang);
            $locale.id = $localStorage.lang;
        }

        $scope.changeViewPassword = function (viewPassword, input) {
            var campo;

            if (input === 1) {
                $scope.viewPassword = viewPassword;
                campo = $('#password');
            } else if (input === 2) {
                $scope.viewPasswordConfirm = viewPassword;
                campo = $('#confirm-password');
            }

            if (campo) {
                campo.attr(
                    'type',
                    viewPassword ? 'text' : 'password'
                );
            }
        };
    };

    $scope.showPasswordMode = function () {
        if ($scope.hasUserSelected()) {
            $scope.showUsuarios = false;

            setTimeout(function () {
                $('#password').focus();
            }, 300);
        }
    };

    $scope.showUsers = function () {
        $scope.showUsuarios = true;
    };

    $scope.hasUserSelected = function () {
        return !!$scope.registro.usuarios &&
            $scope.registro.usuarios.some(function (item) {
                return item.online === true;
            });
    };

    $scope.getSelectedUsers = function () {
        return ($scope.registro.usuarios || []).filter(function (item) {
            return item.online === true;
        });
    };

    $scope.isValidPassword = function () {
        return !!$scope.registro.senha &&
            !!$scope.registro.confirmacaoSenha &&
            $scope.registro.senha ===
                $scope.registro.confirmacaoSenha;
    };

    $scope.resetPasswordByToken = function () {
        if ($scope.registro.usuarios.length === 1) {
            $scope.registro.usuarios[0].online = true;
        } else if (!$scope.hasUserSelected()) {
            swal({
                title: $translate.instant('ATENCAO') + '!',
                text: $translate.instant('SELECAO-USUARIO-RESET'),
                type: 'warning'
            });
            return;
        }

        UsuarioService.resetPasswordByToken(
            $scope.registro
        ).then(function () {
            var mensagem = $scope.newUser
                ? 'SENHA-REDEFINIDA'
                : 'SENHA-CRIADA';

            swal({
                title: $translate.instant('PRONTO') + '!',
                text: $translate.instant(mensagem),
                type: 'success',
                timer: 2000
            }, function () {
                $localStorage.token = undefined;
                $window.location.href = 'login.html';
            });
        });
    };

    $scope.trocarIdioma = function (lang) {
        $localStorage.lang = lang;
        $locale.id = lang;
        $translate.use(lang);
    };

    $scope.obterParametro = function (nome) {
        var regex = new RegExp('[?&]' + nome + '=([^&#]*)', 'i');
        var resultados = regex.exec($window.location.href);

        if (!resultados) {
            return null;
        }

        return decodeURIComponent(
            resultados[1].replace(/\+/g, ' ')
        );
    };

