$scope.getUserInfo = function (callback) {
    UsuarioService.get()
        .then(function (response) {
            var dados = response.data || {};
            var usuario = dados.usuario || dados;

            $scope.$evalAsync(function () {
                // Mantém todos os dados do registro.
                $scope.registro = angular.copy(usuario);

                // Normaliza os campos do perfil.
                $scope.registro.nome = usuario.nome || '';
                $scope.registro.login = usuario.login || '';
                $scope.registro.perfil =
                    usuario.perfil || usuario.usuarioPerfil || '';

                $scope.registro.emailAtendente =
                    usuario.emailAtendente || usuario.email || '';

                $scope.registro.emailComunicacao =
                    usuario.emailComunicacao || '';

$scope.registro.imagem = usuario.imagem || '';

$scope.imagemPerfilPreview = null;
$scope.imagemPerfilArquivo = null;
$scope.imagemBase64 = null;
$scope.imagemName = null;
$scope.saveImage = false;
$scope.removerImagemPendente = false;

                // Atualiza o campo de arquivo.
                var input = document.getElementById('imagem-input-gestor');

                if (input) {
                    input.value = '';
                }

                if (typeof callback === 'function') {
                    callback();
                }
            });
        })
        .catch(function (error) {
            console.error(
                'Erro ao carregar os dados do perfil:',
                error
            );

            $scope.$evalAsync(function () {
                if (!$scope.registro) {
                    $scope.registro = {};
                }
            });
        });
};



