materialAdmin.controller('CrmDashboardGeneralController', function ($scope, $translate, BoardService, AtendenteService, DashboardGeneralService) {
    $scope.downloadPDF = function () {
        const container = document.querySelector('.container-fluid');
        const originalStyles = container.getAttribute('style');
        container.setAttribute('style', 'background-color: white;');

        html2canvas(container, {
            scale: 2,
            useCORS: true
        }).then(canvas => {
            container.setAttribute('style', originalStyles);

            const { jsPDF } = window.jspdf;
            const pdf = new jsPDF('p', 'mm', 'a4');
            const imgData = canvas.toDataURL('image/png');
            pdf.addImage(imgData, 'PNG', 10, 10, 190, 0);
            pdf.save('dashboard-geral.pdf');
        });
    };

    $scope.filter = {
        crmBoardId: '0',
        confUsuarioId: '0',
        dateFromAux: moment().startOf('day').set('date', 1).toDate(),
        dateUntilAux: moment().endOf('day').toDate(),
        crmCardAcceptStatus: 'WIN',
        crmCardPriceType: 'ALL'
    };

    $scope.onInit = function () {

        //recuperando os boards
        BoardService.getSimples().then(function (resp) {
            $scope.boards = resp.data;

            if ($scope.boards.length) {
                $scope.filter.crmBoardId = $scope.boards[0].id.toString();

                $scope.getData();
            }

        });

    }

    $scope.getData = function () {

        //recuperando os atendentes
        if (!$scope.isAtendente()) {
            BoardService.getUsersById($scope.filter.crmBoardId).then(function (resp) {
                $scope.users = resp.data;
            });
        }

        $scope.filter.dateFrom = validateAndFormatDate($scope.filter.dateFromAux);
        $scope.filter.dateUntil = validateAndFormatDate($scope.filter.dateUntilAux);

        //PIPELINE
        DashboardGeneralService.getPipeline($scope.filter).then(function (resp) {
            $scope.pipeline = resp.data;
        });

        //QUANTITY KPI
        DashboardGeneralService.getQuantityKpi($scope.filter).then(function (resp) {
            $scope.quantityKpi = resp.data;
        });

        //QUANTITY PER DAY
        DashboardGeneralService.getQuantityPerDay($scope.filter).then(function (resp) {
            $scope.quantityPerDay = resp.data;
            $scope.drawQuantityPerDay();
        });

        //PRICE DATA

        //$scope.getPriceData();

    };

    $scope.getPriceData = function () {

        //PRICE KPI
        DashboardGeneralService.getPriceKpi($scope.filter).then(function (resp) {
            $scope.priceKpi = resp.data;
        });

        //PRICE PER DAY
        DashboardGeneralService.getPricePerDay($scope.filter).then(function (resp) {
            $scope.pricePerDay = resp.data;
            $scope.drawPricePerDay();
        });

    };

    $scope.drawQuantityPerDay = function () {

        const ctx = document.getElementById('quantityPerDay');
        var statusList = ['CREATED', 'WIN', 'LOST', 'CLOSED'];
        var statusColors = ['rgb(5, 150, 205)', 'rgb(5, 205, 113)', 'rgb(205, 5, 5)', 'rgb(110, 110, 110)'];
        var statusBackgroundColors = ['rgb(5, 150, 205, 0.2)', 'rgb(5, 205, 113, 0.2)', 'rgb(205, 5, 5, 0.2)', 'rgb(110, 110, 110, 0.2)'];

        //calculando a quantidade de dias
        let days = moment($scope.filter.dateUntilAux).diff($scope.filter.dateFromAux, 'days');
        let dateValue = moment($scope.filter.dateFromAux);

        //definindo as labels
        let labels = [];

        for (var i = 0; i <= days; i++) {
            labels.push(dateValue.format('DD/MM/YYYY'));
            dateValue.add(1, 'days');
        }

        //montando o dataset
        let datasets = [];

        $.each(statusList, function (i, status) {
            let values = [];

            var statusData = $scope.quantityPerDay.find(s => s.status == status);
            var statusDates = statusData ? statusData.dates : undefined;

            $.each(labels, function (i, label) {
                let dateDate = statusDates && statusDates.find(d => d.date == label);

                if (dateDate && dateDate.countCards) {
                    values.push(dateDate.countCards);
                } else {
                    values.push(0);
                }
            });

            datasets.push({
                label: $translate.instant(status),
                data: values,
                fill: true,
                backgroundColor: statusBackgroundColors[i],
                borderColor: statusColors[i],
                tension: 0.3,
                borderWidth: 2
            });

        });

        const config = {
            type: 'line',
            data: {
                labels: labels,
                datasets: datasets,
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                }
            }
        };

        if ($scope.chatQuantityPerDay) {
            $scope.chatQuantityPerDay.destroy();
        }

        $scope.chatQuantityPerDay = new Chart(ctx, config);

    };

    $scope.drawPricePerDay = function () {

        const ctx = document.getElementById('pricePerDay');

        var statusList = ['PENDING', 'WIN', 'LOST'];
        var statusIndex = statusList.findIndex(s => s == $scope.filter.crmCardAcceptStatus);

        var statusColors = ['rgb(5, 150, 205)', 'rgb(5, 205, 113)', 'rgb(205, 5, 5)'];
        var statusBackgroundColors = ['rgb(5, 150, 205, 0.2)', 'rgb(5, 205, 113, 0.2)', 'rgb(205, 5, 5, 0.2)'];

        //calculando a quantidade de dias
        let days = moment($scope.filter.dateUntilAux).diff($scope.filter.dateFromAux, 'days');
        let dateValue = moment($scope.filter.dateFromAux);

        //definindo as labels
        let labels = [];

        for (var i = 0; i <= days; i++) {
            labels.push(dateValue.format('DD/MM/YYYY'));
            dateValue.add(1, 'days');
        }

        //montando o dataset
        let values = [];

        $.each(labels, function (i, label) {
            let dateDate = $scope.pricePerDay.find(d => d.date == label);

            if (dateDate && dateDate.totalPrice) {
                values.push(dateDate.totalPrice);
            } else {
                values.push(0.0);
            }
        });

        let datasets = [{
            label: $translate.instant($scope.filter.crmCardAcceptStatus),
            data: values,
            fill: true,
            backgroundColor: statusBackgroundColors[statusIndex],
            borderColor: statusColors[statusIndex],
            tension: 0.3,
            borderWidth: 2
        }];

        const config = {
            type: 'line',
            data: {
                labels: labels,
                datasets: datasets,
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true
                    }
                },
                plugins: {
                    tooltip: {
                        callbacks: {
                            label: function (context) {
                                return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(context.parsed.y);
                            }
                        }
                    }
                }
            }
        };

        if ($scope.chatPricePerDay) {
            $scope.chatPricePerDay.destroy();
        }

        $scope.chatPricePerDay = new Chart(ctx, config);

    };

});

