    $scope.onCancelarModalBancoArquivo = function () {
        if ($scope.modalBancoArquivo) {
            $scope.modalBancoArquivo.close();
            $scope.resetBancoArquivo();
        }
    };
    $scope.onCancelarModalUploadOrigem = function () {
        if ($scope.modalUploadOrigem) {
            $scope.modalUploadOrigem.close();
        }
    };

    $scope.getIdPastaAtualBancoArquivo = () => {
        if ($scope.bancoArquivo.breadcrumb.length > 0) {
            return $scope.bancoArquivo.breadcrumb[$scope.bancoArquivo.breadcrumb.length - 1].id;
        } else {
            return null;
        }
    }
    $scope.getPastaAtualBancoArquivo = () => {
        if ($scope.bancoArquivo.breadcrumb.length > 0) {
            return $scope.bancoArquivo.breadcrumb[$scope.bancoArquivo.breadcrumb.length - 1];
        } else {
            return null;
        }
    }

    $scope.clickBreadCrumbBancoArquivo = (idxPasta) => {
        if (idxPasta === -1) {
            $scope.bancoArquivo.breadcrumb = [];
        } else {
            $scope.bancoArquivo.breadcrumb = $scope.bancoArquivo.breadcrumb.filter((i, idx) => idx <= idxPasta);
        }

        $scope.getBancoArquivos(false);
    }

    $scope.limit = 20;

    $scope.getBancoArquivos = function (pagination) {

        if (!$scope.canManageKnowledgeBases()) {
            return;
        }

        $scope.bancoArquivo.loading = true;
        if (pagination) {
            $scope.bancoArquivo.filtro.offset += 20;
        } else {
            $scope.bancoArquivo.registros = [];
            $scope.bancoArquivo.filtro.offset = 0;
            $scope.bancoArquivo.showMore = false;
        }

        let filtro = Object.assign($scope.bancoArquivo.filtro, {});

        let pastaAtual = $scope.getIdPastaAtualBancoArquivo();
        if (pastaAtual !== null) {
            filtro.folderId = pastaAtual;
        } else {
            delete filtro.folderId;
        }


        BancoArquivoService.getAll(filtro).then(function (response) {
            $scope.bancoArquivo.registros = $scope.bancoArquivo.registros.concat(response.data);
            $scope.bancoArquivo.showMore = response.data.length === $scope.limit;
            $scope.bancoArquivo.loading = false;

            updateComponentsAfterRequest();
        });
    };

    $scope.toogleBancoArquivoSelecao = (registro) => {

        if (registro.type === "FOLDER") {
            $scope.bancoArquivo.filtro.nome = '';
            $scope.bancoArquivo.breadcrumb.push(registro);
            $scope.getBancoArquivos(false);
        } else {
            let find = $scope.bancoArquivo.arquivosSelecionados.find(i => i.id === registro.id);
            if (find) {
                $scope.bancoArquivo.arquivosSelecionados = $scope.bancoArquivo.arquivosSelecionados.filter(i => i.id != registro.id);
            } else {
                $scope.bancoArquivo.arquivosSelecionados.push(registro);
            }
        }

    }

    $scope.bancoArquivoSelecionado = (registro) => {
        return $scope.bancoArquivo.arquivosSelecionados.find(i => i.id === registro.id) ? true : false;
    }

    $scope.escolherBancoArquivo = async () => {
        const arquivos = $scope.bancoArquivo.arquivosSelecionados;

        const converterParaBase64 = async (url) => {
            const response = await fetch(url);
            const blob = await response.blob();

            if (!$scope.mimeTypesSuportados.includes(blob.type)) {
                swal("Ops!", `Tipo MIME não suportado: ${blob.type}`, "error");
                throw new Error(`Tipo MIME não suportado: ${blob.type}`);
            }

            return new Promise((resolve, reject) => {
                const reader = new FileReader();
                reader.onloadend = () => resolve(reader.result);
                reader.onerror = reject;
                reader.readAsDataURL(blob);
            });
        };

        $scope.assistant.knowledgeBases = $scope.assistant.knowledgeBases || [];

        for (const item of arquivos) {
            try {
                const base64 = await converterParaBase64(item.fileUrl);
                let kb = {
                    title: item.fileName,
                    url: item.fileUrl,
                    value: base64,
                    type: 'FILE',
                    action: 'INSERT'
                };
                $scope.assistant.knowledgeBases.push(kb);
            } catch (error) {
                console.warn(`Arquivo ignorado: ${item.fileName}. Motivo: ${error.message}`);
            }
        }

        $scope.bancoArquivo.arquivosSelecionados = [];
        $scope.onCancelarModalBancoArquivo();
        $scope.modalSelectTypeKB.close();

        if (!$scope.$$phase) {
            $scope.$apply();
        }
    };

    $scope.getBackgroundImageUrlBancoArquivo = (registro) => {
        switch (registro.type) {
            case "IMAGEM":
                return "url('" + registro.fileUrl + "')";
            default:
                return "none";
        }
    }

    $scope.resetBancoArquivo = () => {
        $scope.bancoArquivo = {
            filtro: {
                nome: "",
                offset: 0,
                origem: "TODOS"
            },
            breadcrumb: [],
            registros: [],
            showMore: false,
            loading: false,
            arquivosSelecionados: []
        }
        if ($localStorage.bancoArquivoModo) {
            $scope.bancoArquivo.modoExibicao = $localStorage.bancoArquivoModo;
        } else {
            $scope.bancoArquivo.modoExibicao = "GRADE"
        }
    }

    $scope.alterarModoExibicao = (modo) => {
        $scope.bancoArquivo.modoExibicao = modo;
        $localStorage.bancoArquivoModo = modo;
    }

    $scope.hasAnyInstructionSelected = function () {
        if (!$scope.selectedTemplateData || !$scope.selectedTemplateData.instructions) {
            return false;
        }

        return $scope.selectedTemplateData.instructions.some(function (instruction) {
            return instruction.selected;
        });
    };

    $scope.textLimit = 200;
    $scope.showFullText = false;

    $scope.getLimitedText = function (instruction) {
        if (instruction.showFullText || !instruction.value) {
            return instruction.value;
        }
        return instruction.value.length > $scope.textLimit
            ? instruction.value.substring(0, $scope.textLimit) + '...'
            : instruction.value;
    };

    $scope.shouldShowToggle = function (text) {
        return text && text.length > $scope.textLimit;
    };

    $scope.toggleReadMore = function (instruction) {
        instruction.showFullText = !instruction.showFullText;
    };

    $scope.getMessageErro = (item) => {
        if (item) {
            try {
                const obj = JSON.parse(item);
                return obj.api_mz_message || "";
            } catch (e) {
                console.error("Erro ao fazer parse do item:", e);
                return "";
            }
        } else {
            return
        }
    };

    $scope.textLimitAlt = 200;

    $scope.expandedTexts = {};

    $scope.treatThetext = (text, id) => {
        if (!text) return '';

        let fullText = text.replace(/\n/g, '<br>');
        let isExpanded = $scope.expandedTexts[id];

        if (isExpanded || text.length <= $scope.textLimit) {
            return fullText;
        }

        let shortText = text.substring(0, $scope.textLimit).replace(/\n/g, '<br>') + '...';
        return shortText;
    };

    $scope.toggleReadMoreAlt = (id) => {
        $scope.expandedTexts[id] = !$scope.expandedTexts[id];
    };

    $scope.getCustomFields = function (instruction) {
        if (!$scope.canManageTicket()) {
            return;
        }

        let filter = {
            clienteId: $stateParams.clientId
        };

        try {
            ContatoInformacaoService.getTodos(filter).then(function (response) {
                $scope.fields = response.data;
                $scope.fields = $scope.fields.filter(field =>
                    !$scope.instruction.fields.some(f => f.contatoInformacaoId === field.id)
                );
            });
        } catch (error) {
        }

    };

    $scope.selectedTab = {
        activeTab: 'geral'
    };

    $scope.newIntegration = {
        nome: "",
        descricao: "",
        contatoInformacaoId: "",
        required: false
    }

    $scope.onAddField = function () {
        if (
            !$scope.newIntegration.contatoInformacaoId ||
            $scope.newIntegration.contatoInformacaoId < 1
        ) {
            return;
        }

        if ($scope.newIntegration.editing) {
            const field = $scope.instruction.fields.find(function (field) {
                return String(field.contatoInformacaoId) === String($scope.newIntegration.contatoInformacaoId);
            });

            if (field) {
                field.contatoInformacaoId = $scope.newIntegration.contatoInformacaoId;
                field.alias = $scope.newIntegration.alias;
                field.description = String($scope.newIntegration.descricao);
                field.required = $scope.newIntegration.required;
            }
        } else {
            let alreadyExists = $scope.instruction.fields.some(function (field) {
                return String(field.contatoInformacaoId) === String($scope.newIntegration.contatoInformacaoId);
            });

            if (alreadyExists) {
                swal("Ops!", "Esse campo já foi adicionado.", "error");
                return;
            }

            let newField = angular.copy($scope.newIntegration);

            let descricao = 0 + Number(newField.descricao.length);

            if ((newField.contatoInformacaoId > 0 && descricao == 0)) {
                swal("Ops!", "Por favor, preencha todos os campos obrigatórios.", "error");
                return;
            }

            let fieldSelect = $scope.getFieldById(Number(newField.contatoInformacaoId));

            let newIntegration = {
                nome: fieldSelect.nome,
                alias: newField.alias,
                description: newField.descricao,
                contatoInformacaoId: newField.contatoInformacaoId,
                required: newField.required
            };

            $scope.instruction.fields.push(newIntegration);
        }

        $scope.fields = $scope.fields.filter(field => String(field.id) != String($scope.newIntegration.contatoInformacaoId));

        $scope.newIntegration = {
            nome: "",
            descricao: "",
            contatoInformacaoId: "",
            required: false,
            editing: false
        }
    };

    $scope.onDeleteField = function (field) {
        const index = $scope.instruction.fields.indexOf(field);
        if (index > -1) {
            $scope.instruction.fields.splice(index, 1);
            $scope.getCustomFields();
            updateComponentsAfterRequest();
        }
    };

    $scope.onEditField = function (field) {
        $scope.fields.push({ id: String(field.contatoInformacaoId), nome: field.nome });

        $scope.newIntegration.contatoInformacaoId = String(field.contatoInformacaoId);
        $scope.newIntegration.alias = field.alias;
        $scope.newIntegration.descricao = field.description;
        $scope.newIntegration.required = field.required;
        $scope.newIntegration.editing = true;
    };

    $scope.getFieldById = function (id) {
        for (var i = 0; i < $scope.fields.length; i++) {
            if ($scope.fields[i].id === id) {
                return $scope.fields[i];
            }
        }
        return null;
    };

    $scope.openModalIntegration = function (instruction) {
        $scope.isEditInstruction = false;
        $scope.originalInstruction = null;
        $scope.selectedField = null;
        $scope.isRequired = false;

        $scope.newIntegration = {
            nome: "",
            descricao: "",
            contatoInformacaoId: "",
            required: false
        }

        $scope.selectedTab = {
            activeTab: 'geral'
        };

        $scope.getCustomFields(instruction);

        if (instruction?.title) {
            $scope.isEditInstruction = true;
            $scope.originalInstruction = instruction;
        }

        $scope.instruction = angular.copy(instruction) || {
            title: "",
            instruction: "",
            url: "",
            mzAuth: "",
            fields: []
        };

        $scope.modalInstruction = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/ai_integrations/assistant/modal-integration.html?t=' + Date.now(),
            scope: $scope,
            windowClass: 'custom-modal',
            controller: function () {
                updateComponentsAfterRequest();
            },
        });
    };

    $scope.onIntegration = () => {
        if (!$scope.instruction || !$scope.instruction.title || !$scope.instruction.instruction) {
            swal("Ops!", "Por favor, preencha todos os campos obrigatórios.", "error");
            return;
        }

        $scope.instruction.integrationName = $scope.instruction.title.replace(/\s+/g, '');

        $scope.instruction.fields = $scope.instruction.fields.map(field => ({
            nome: field.nome,
            alias: field.alias,
            description: field.description,
            contatoInformacaoId: Number(field.contatoInformacaoId),
            required: field.required
        }));

        if ($scope.isEditInstruction) {
            const index = $scope.assistant.integrations.findIndex(instr =>
                angular.equals(instr, $scope.originalInstruction)
            );

            if (index !== -1) {
                $scope.assistant.integrations[index] = angular.copy($scope.instruction);
            }
        } else {
            $scope.assistant.integrations.push($scope.instruction);
        }

        $scope.instruction = {
            title: "",
            instruction: "",
            url: "",
            mzAuth: "",
            fields: []
        };

        $scope.modalInstruction.close();
    };

    $scope.onRedirectDepartment = () => {
        if (!$scope.instruction || !$scope.instruction.title || !$scope.instruction.instruction) {
            swal("Ops!", "Por favor, preencha todos os campos obrigatórios", "error");
            return;
        }

        $scope.instruction.fields = $scope.instruction.fields.map(field => ({
            nome: field.nome,
            alias: field.alias,
            description: field.description,
            contatoInformacaoId: Number(field.contatoInformacaoId),
            required: field.required
        }));

        $scope.instruction.departaments = $scope.selectedDepartments.map(department => ({
            id: department.id,
            name: department.name
        }));

        if ($scope.instruction.departaments.length < 1) {
            swal("Ops!", "Selecione pelo menos um departamento!", "error");
            return;
        }

        if ($scope.isEditInstruction) {
            const index = $scope.assistant.tickets.findIndex(instr =>
                angular.equals(instr, $scope.originalInstruction)
            );

            if (index !== -1) {
                $scope.instruction.requestAgents = ($scope.instruction.requestAgents.toLowerCase() === 'true');
                $scope.assistant.tickets[index] = angular.copy($scope.instruction);
            }
        } else {
            $scope.assistant.tickets.push($scope.instruction);
        }

        $scope.instruction = {
            title: "",
            instruction: "",
            requestAgents: false,
            departaments: [],
            fields: []
        };

        $scope.modalInstruction.close();
    };

    $scope.backStap = (isRedirect) => {
        if (isRedirect) {
            if ($scope.selectedTab.activeTab === 'segmentacao') {
                $scope.selectedTab.activeTab = 'instrucao'
            } else if ($scope.selectedTab.activeTab === 'instrucao') {
                $scope.selectedTab.activeTab = 'departamento'
            } else if ($scope.selectedTab.activeTab === 'departamento') {
                $scope.selectedTab.activeTab = 'geral'
            } else if ($scope.selectedTab.activeTab = 'geral') {
                return
            }
        } else {
            if ($scope.selectedTab.activeTab === 'segmentacao') {
                $scope.selectedTab.activeTab = 'instrucao'
            } else if ($scope.selectedTab.activeTab === 'instrucao') {
                $scope.selectedTab.activeTab = 'geral'
            } else if ($scope.selectedTab.activeTab = 'geral') {
                return
            }
        }
    }

    $scope.nextStap = (isRedirect) => {
        if (isRedirect) {
            if ($scope.selectedTab.activeTab === 'geral') {
                $scope.selectedTab.activeTab = 'instrucao';
            } else if ($scope.selectedTab.activeTab === 'instrucao') {
                $scope.selectedTab.activeTab = 'departamento';
            } else if ($scope.selectedTab.activeTab === 'departamento') {
                $scope.selectedTab.activeTab = 'segmentacao';
            } else if ($scope.selectedTab.activeTab === 'segmentacao') {
                $scope.onRedirectDepartment();
            }
        } else {
            if ($scope.selectedTab.activeTab === 'geral') {
                $scope.selectedTab.activeTab = 'instrucao'
            } else if ($scope.selectedTab.activeTab === 'instrucao') {
                $scope.selectedTab.activeTab = 'segmentacao'
            } else if ($scope.selectedTab.activeTab = 'segmentacao') {
                $scope.onIntegration();
            }
        }
    }

    $scope.validReadMore = (length) => {
        if (Number(length) > 199) {
            return true;
        } else {
            return false;
        }
    }

    $scope.deleteTicket = (registro) => {
        const index = $scope.assistant.tickets.indexOf(registro);
        if (index !== -1) {
            $scope.assistant.tickets.splice(index, 1);
        }
    };

    $scope.deleteIntegration = (integration) => {
        const index = $scope.assistant.integrations.indexOf(integration);
        if (index !== -1) {
            $scope.assistant.integrations.splice(index, 1);
        }
    };

