    $scope.departamentos = [];
    $scope.departmentsBoard = [];
    $scope.initialDepartments = [];
    $scope.selectedDepartments = [];

    $scope.updateDepartments = function () {
        if ($scope.departmentsBoard && $scope.instruction.departaments) {
            $scope.departmentsBoard = angular.copy($scope.departamentos) || [];

            $scope.selectedDepartments = [];

            $scope.departmentsBoard.forEach(department => {
                const isSelected = $scope.instruction.departaments.some(d => d.id === department.id);
                if (isSelected) {
                    $scope.selectedDepartments.push(department);
                }
            });

            $scope.departmentsBoard = $scope.departmentsBoard.filter(department =>
                !$scope.selectedDepartments.some(d => d.id === department.id)
            );
        }
    };

    $scope.recuperarDepartamentos = function () {
        $scope.departamentos = [];
        DepartamentoService.getAtivos($stateParams.clientId).then(function (response) {
            $scope.departamentos = response.data.map(department => ({
                id: department.id,
                name: department.nome,
                selected: false
            }));

            $scope.departmentsBoard = angular.copy($scope.departamentos) || [];

            let allDepartmentsUsed = $scope.assistant.tickets.flatMap(ticket => ticket.departaments || []);
            $scope.departmentsBoard = $scope.departmentsBoard.filter(department =>
                !allDepartmentsUsed.some(d => d.id === department.id)
            );
        }).catch(function (error) {
            console.error('Error fetching departments:', error);
        });
    };

    $scope.toggleSelection = function (department) {
        department.selected = !department.selected;
    };

    $scope.moveDepartments = function (direction) {
        if (direction === 'right') {
            moveSelected($scope.departmentsBoard, $scope.selectedDepartments);
        } else if (direction === 'left') {
            moveSelected($scope.selectedDepartments, $scope.departmentsBoard);
        } else if (direction === 'double-right') {
            moveAll($scope.departmentsBoard, $scope.selectedDepartments);
        } else if (direction === 'double-left') {
            moveAll($scope.selectedDepartments, $scope.departmentsBoard);
        }
    };

    function moveSelected(fromList, toList) {
        for (let i = fromList.length - 1; i >= 0; i--) {
            if (fromList[i].selected) {
                fromList[i].selected = false;
                toList.push(fromList[i]);
                fromList.splice(i, 1);
            }
        }
    }

    function moveAll(fromList, toList) {
        while (fromList.length) {
            fromList[0].selected = false;
            toList.push(fromList.shift());
        }
    }

