    $scope.abrirLogsAtendimento = function (atendimento) {
        $scope.atendimentoSelecionado = atendimento;

        if (!$scope.isAtendente()) {
            $scope.atendente = { isOwner: true };
        } else {
            $scope.atendente = { isOwner: false }
        }

        AtendimentoService.getAtendimentoAtendente($scope.atendimentoSelecionado.protocolo).then(function (response) {
            $scope.atendimentoSelecionado.informacoes = response.data;

            if ($scope.isAtendente()) {
                $scope.atendente.isOwner = false;
            }

            if ($scope.atendimentoSelecionado.informacoes.participantes && $scope.atendimentoSelecionado.informacoes.participantes.length > 0) {
                $scope.atendimentoSelecionado.informacoes.participantes = $scope.atendimentoSelecionado.informacoes.participantes.map(p => ({ ...p, url: p.url ? p.url : "img/sem-foto.png" }))

                if ($scope.atendimentoSelecionado.status != 'FINALIZADO') {
                    if ($scope.isAtendente()) {
                        $scope.atendente.isOwner = $scope.atendimentoSelecionado.informacoes.participantes.find(p => p.id == $scope.atendente.id && p.tipo == 'OWNER') != null;
                    }
                }
            }

            $scope.tab1 = {};
            $scope.tab1.active = true;
            $scope.tab2 = {};
            $scope.tab3 = {};
            $scope.tab4 = {};
            $scope.tab5 = {};

            $scope.modalMensagens = $uibModal.open({
                animation: true,
                ariaLabelledBy: 'modal-title-top',
                ariaDescribedBy: 'modal-body-top',
                templateUrl: 'views/megazap/relatorios/atendimentos/modal-informations.html?t=' + Date.now(),
                scope: $scope,
                size: 'lg'
            });

            $scope.modalMensagens.opened.then(function () {
                $scope.recuperarCampoSegmentacaoIntegracaoEdicao();
                updateComponentsAfterRequest();
            });
        });
    };

