    $scope.selecionarArquivoCampoInformacao = function (campo) {
        $scope.campoSegmentacaoArquivoSelecionado = campo;
        setTimeout(function () {
            $('#inputCampoSegmentacao' + campo.contatoInformacaoId).trigger('click');
        })
    };

    $scope.atualizarArquivoCampoInformacao = function (files) {
        if (!files || !files.length) {
            return;
        }

        let reader = new FileReader();
        let file = files[0];

        reader.readAsDataURL(file);
        reader.onload = function () {
            FileService.insertBase64(reader.result, file.name).then(f => {
                $scope.campoSegmentacaoArquivoSelecionado.valorOriginal = f.data.url;
                $scope.campoSegmentacaoArquivoSelecionado.valorUrl = f.data.url;

                $scope.atualizarContato($scope.campoSegmentacaoArquivoSelecionado);
            });
        };
    }

    $scope.removerArquivoContatoInformacao = function (campo) {
        $('#inputCampoSegmentacao' + campo.contatoInformacaoId)[0].value = '';
        delete campo.valorOriginal;
        delete campo.valorUrl;
        $scope.atualizarContato(campo);
    }

