    $scope.onFinalizarAtendimento = function (id) {
        var data = {
            id: id,
            fromReport: true
        };

        AtendimentoService.finalizarAtendimento(data).then(function () {
            $scope.getAtendimentos();
        });
    };


    $scope.onBloquearContato = function (data) {
        $scope.registroBlacklist = {
            novoCanal: 0,
            status: data.status,
            contactName: data.nome,
            contactId: data.numero,
            canais: []
        }

        RelatorioService.getAtendimentoChat(data.protocolo).then(response => {

            let canal = $scope.canaisBlacklist.find(c => c.botId == response.data.usuario.botId);

            $scope.registroBlacklist.canais.push({
                id: 0,
                tipo: canal.canal,
                nome: canal.canal + ' - ' + canal.numero,
                canalId: canal.id,
                botId: canal.botId
            });

            $scope.registroBlacklist.protocolo = data.protocolo;

            $scope.modalNovoRegistroBlacklist = $uibModal.open({
                animation: true,
                size: "lg",
                ariaLabelledBy: "modal-title-top",
                ariaDescribedBy: "modal-body-top",
                keyboard: false,
                templateUrl:
                    "views/megazap/blacklist/modal-novo-edicao.html?t=" + Date.now(),
                scope: $scope,
                controller: function () {
                    updateComponentsAfterRequest();
                },
            });
        });
    };

    $scope.recuperarCanais = function () {
        CanalService.getAll().then(function (response) {
            $scope.canaisBlacklist = response.data;
        });
    };

    $scope.onAddCanalBlacklist = () => {
        if ($scope.registroBlacklist.canais.some(c => c.canalId == $scope.registroBlacklist.novoCanal)) {
            $scope.registroBlacklist.novoCanal = null;
            return;
        }

        let canal = $scope.canaisBlacklist.find(c => c.id == $scope.registroBlacklist.novoCanal);

        $scope.registroBlacklist.canais.push({
            id: 0,
            tipo: canal.canal,
            nome: canal.canal + ' - ' + canal.numero,
            canalId: canal.id,
            protocolo: canal.protocolo,
            botId: canal.botId
        });

        $scope.registroBlacklist.novoCanal = null;
    };

    $scope.existemRegistrosAtivosBlacklist = (registros) => {
        return registros && registros.length > 0 && registros.filter(r => !r.deleted).length > 0;
    };

    $scope.onRemoverCanalBlacklist = (canal) => {
        if (canal.id > 0) {
            canal.deleted = true;
        } else {
            $scope.registroBlacklist.canais.splice($scope.registroBlacklist.canais.indexOf(canal), 1);
        }
    };

    $scope.onModalSalvarBlacklist = () => {
        let data = angular.copy($scope.registroBlacklist);
        data.botIds = data.canais.map(c => c.botId);

        const doSave = () => {
            if (!$scope.validarFormularioBlacklist()) {
                return;
            }

            BlacklistService.post(data).then(() => {
                $scope.getAll();
                $scope.onModalCancelarBlacklist();
            });
        }

        if (data.status == 'ATIVO') {
            swal({
                title: $translate.instant('ATENCAO') + "!",
                text: "Bloquear esse contato finalizará o atendimento. Deseja continuar?",
                type: "warning",
                showCancelButton: true,
                confirmButtonColor: "#DD6B55",
                confirmButtonText: $translate.instant('SIM'),
                cancelButtonText: $translate.instant('CANCELAR'),
                closeOnConfirm: true,
                closeOnCancel: true
            }, function (isConfirm) {
                if (isConfirm) {
                    doSave()
                }
            });
        } else {
            doSave()
        }
    };

    $scope.validarFormularioBlacklist = () => {

        if (!$scope.registroBlacklist.contactName || $scope.registroBlacklist.contactName.trim() == '') {
            swal({
                title: $translate.instant("ATENCAO") + "!",
                text: $translate.instant("BLACKLIST-PREENCHA-NOME"),
                type: "error",
                timer: 5000,
                function() { },
            });

            return false;
        }

        if (!$scope.registroBlacklist.contactId || $scope.registroBlacklist.contactId.trim() == "") {
            swal({
                title: $translate.instant("ATENCAO") + "!",
                text: $translate.instant("BLACKLIST-PREENCHA-CONTATO"),
                type: "error",
                timer: 5000,
                function() { },
            });

            return false;
        }

        return true;
    };

    $scope.onModalCancelarBlacklist = () => {
        if ($scope.modalNovoRegistroBlacklist) {
            $scope.modalNovoRegistroBlacklist.close();
        }

        $scope.registroBlacklist = {};
    };

    $scope.mostrarModalFinalizarAtendimentosIndividual = (id) => {

        //INDIVIDUAL

        let registro = $scope.registros.filter(a => a.protocolo == id)[0];
        let departamentoMotivos = $scope.departamentosMotivosFinalizacao.find(d => d.id == registro.departamentoId);

        $scope.controleFinalizarAtendimentos = {
            atendimentosIds: [id],
            departamentos: [
                {
                    id: registro.departamentoId,
                    nome: registro.departamento,
                    motivos: departamentoMotivos ? departamentoMotivos.motivos : null
                }
            ]
        }

        $scope.mostrarModalFinalizarAtendimentos();
    }

    $scope.mostrarModalFinalizarAtendimentosEmMassa = () => {

        if ($scope.registrosSelecionados.acaoEmRegistrosFiltrados) {

            //FILTRADOS

            if ($scope.filtro.departamentoId > 0) {

                let departamentoMotivos = $scope.departamentosMotivosFinalizacao.find(d => d.id == $scope.filtro.departamentoId);

                $scope.controleFinalizarAtendimentos = [
                    {
                        id: $scope.filtro.departamentoId,
                        nome: $scope.departamentos.find(d => d.id == $scope.filtro.departamentoId).nome,
                        motivos: departamentoMotivos ? departamentoMotivos.motivos : null
                    }
                ]

                $scope.mostrarModalFinalizarAtendimentos();

            } else {

                $scope.buildCamposSegmentacaoFiltro();

                RelatorioService.getDepartamentos($scope.filtro).then((resp) => {

                    let departamentos = [];

                    $.each(resp.data, (i, departamentoId) => {

                        let departamentoMotivos = $scope.departamentosMotivosFinalizacao.find(d => d.id == departamentoId);

                        departamentos.push(
                            {
                                id: departamentoId,
                                nome: $scope.departamentos.find(d => d.id == departamentoId).nome,
                                motivos: departamentoMotivos ? departamentoMotivos.motivos : null
                            }
                        )
                    });

                    $scope.controleFinalizarAtendimentos = {
                        departamentos: departamentos
                    }

                    $scope.mostrarModalFinalizarAtendimentos();
                });

            }

        } else {

            //SELECIONADOS

            let atendimentosIds = [];
            let departamentos = [];

            Object.entries($scope.registrosSelecionados).filter(r => r[0] != 'todos' && r[1]).forEach(r => {
                if ($scope.registros[r[0]] && $scope.registros[r[0]].departamentoId && $scope.registros[r[0]].protocolo) {
                    let registro = $scope.registros[r[0]];

                    if (!departamentos.find(d => d.id == registro.departamentoId)) {

                        let departamentoMotivos = $scope.departamentosMotivosFinalizacao.find(d => d.id == registro.departamentoId);

                        departamentos.push(
                            {
                                id: registro.departamentoId,
                                nome: registro.departamento,
                                motivos: departamentoMotivos ? departamentoMotivos.motivos : null
                            }
                        );
                    }

                    atendimentosIds.push(registro.protocolo);
                }
            });

            $scope.controleFinalizarAtendimentos = {
                atendimentosIds: atendimentosIds,
                departamentos: departamentos
            }

            $scope.mostrarModalFinalizarAtendimentos();
        }
    }

    $scope.mostrarModalFinalizarAtendimentos = () => {
        $scope.modalFinalizarAtendimentos = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/relatorios/atendimentos/modal-finalizar-atendimentos.html?t=' + Date.now(),
            scope: $scope,
            size: 'lg'
        });
    }

    $scope.finalizarAtendimentos = () => {
        var data = {};

        if ($scope.registrosSelecionados.acaoEmRegistrosFiltrados) {
            data = angular.copy($scope.filtro)
            data.offset = 0;
            data.considerarFiltros = true;
        } else {
            data.atendimentosId = $scope.controleFinalizarAtendimentos.atendimentosIds;
        }

        if ($scope.controleFinalizarAtendimentos.departamentos) {
            data.controleFinalizacao = [];

            $.each($scope.controleFinalizarAtendimentos.departamentos, (i, d) => {
                if (data.controleFinalizacao) {
                    data.controleFinalizacao.push({
                        departamentoId: d.id,
                        motivoId: d.motivo ? d.motivo.id : 0,
                        enviarMensagens: d.enviarMensagens
                    });
                }
            });
        }

        let FirebaseMassFinalizationQueue = FirebaseUtil.helpdeskTicketMassive.onUpdateMassFinalizationQueue($scope.jwt.clienteId, $scope.jwt.usuarioId, (val) => {
            $scope.transferQuantity = val;
        })

        $scope.firebase.listeners.push(FirebaseMassFinalizationQueue);
        $scope.onModalCancelar();

        $scope.modalLoading = $uibModal.open({
            animation: true,
            ariaLabelledBy: 'modal-title-top',
            ariaDescribedBy: 'modal-body-top',
            templateUrl: 'views/megazap/relatorios/modal-contador.html?t=' + Date.now(),
            size: 'sm',
            scope: $scope,
            windowClass: 'app-modal-center',
            keyboard: false
        });

        AtendimentoService.finalizarAtendimentoEmMassa(data).then(function () {
            $scope.fecharModalFinalizarAtendimentos();
            $scope.getAtendimentos();

            $scope.modalLoading.close();

            setTimeout(() => {
                $scope.transfering = false;
                $scope.transferQuantity = $translate.instant('CARREGANDO') + "...";
                $scope.firebase.listeners[0].off();
            }, 1000);
        }, () => {
            $scope.modalLoading.close();
            $scope.transfering = false;
            $scope.transferQuantity = $translate.instant('CARREGANDO') + "...";
        });
    }

    $scope.fecharModalFinalizarAtendimentos = () => {
        delete $scope.controleFinalizarAtendimentos;
        $scope.modalFinalizarAtendimentos.close();
    }

    $scope.onModalCancelar = function () {
        if ($scope.modalTransferencia) {
            $scope.modalTransferencia.close();
        }

        if ($scope.modalDepartamentos) {
            $scope.modalDepartamentos.close();
        }

        $scope.emMassa = false;
    };

