    $scope.onSelecionarTodosFiltrados = () => {
        $scope.registrosSelecionados = { todos: true, acaoEmRegistrosFiltrados: true }
        $scope.registros.forEach((r, i) => {
            $scope.registrosSelecionados[i] = true;
        })
    }

    $scope.onDeselecionarTodosFiltrados = () => {
        $scope.registrosSelecionados.todos = false;
        $scope.registrosSelecionados.acaoEmRegistrosFiltrados = false;
    }

    $scope.onToggleSelecionarTodos = () => {
        if ($scope.registrosSelecionados.todos) {
            $scope.registrosSelecionados = { todos: true, acaoEmRegistrosFiltrados: false }
            $scope.registros.forEach((r, i) => {
                $scope.registrosSelecionados[i] = true;
            })
        } else {
            $scope.registrosSelecionados = { todos: false, acaoEmRegistrosFiltrados: false }
        }
    }

    $scope.totalSelecionado = () => {
        const len = Object.entries($scope.registrosSelecionados).filter(r => r[0] != 'todos' && r[1]).length;

        return len > 0 ? len : 0;
    }

    $scope.selecionadosFinalizados = () => {
        let todosFinalizados = true;
        Object.entries($scope.registrosSelecionados)
            .filter(r => r[0] != 'todos' && r[1])
            .forEach(r => {
                const registro = $scope.registros[r[0]]
                if (registro && registro.status != 'FINALIZADO') {
                    todosFinalizados = false;
                }
            })
        return todosFinalizados;
    }

    $scope.selecionadosNaoFinalizados = () => {
        let todosNaoFinalizados = true;
        Object.entries($scope.registrosSelecionados)
            .filter(r => r[0] != 'todos' && r[1])
            .forEach(r => {
                const registro = $scope.registros[r[0]]
                if (registro && registro.status == 'FINALIZADO') {
                    todosNaoFinalizados = false;
                }
            })
        return todosNaoFinalizados;
    }
    // $scope.onCallWebhook = (protocolo) =>{
    //      WebhookService.callWebhoook(protocolo).then(function (response) {
