materialAdmin.controller('RelatorioWaCallsController', function ($scope, $uibModal, ClienteService, RelatorioService) {

  $scope.showMore = false;
  $scope.registros = [];

  $scope.filter = {};
  $scope.filter.status = 'ALL';

  $scope.onInit = function () {
    ClienteService.getTelefones().then(function (response) {
      $scope.telefones = response.data;
    });

    $scope.getAll();
  };

  $scope.getAll = function (pagination) {
    if (pagination) {
      $scope.filter.offset += 50;
    } else {
      $scope.registros = [];
      $scope.filter.offset = 0;
      $scope.showMore = true;
    }

    RelatorioService.getWaCalls($scope.filter).then(function (response) {
      $scope.registros = $scope.registros.concat(response.data);
      $scope.showMore = response.data.length > 0;
    });
  };

  $scope.formatDuration = (totalSegundos) => {
    return formatCallDuration(totalSegundos);
  }

  $scope.showWaCallDetails = function (registro) {
    RelatorioService.getWaCallDetails(registro.id).then(function (response) {
      $scope.waCallSelected = response.data;

      $scope.modalCallDetails = $uibModal.open({
        animation: true,
        ariaLabelledBy: 'modal-title-top',
        ariaDescribedBy: 'modal-body-top',
        templateUrl: 'views/wa-call/modal-call-details.html',
        scope: $scope,
        size: 'lg'
      });
    });
  };

  $scope.onCloseModalCallDetails = function () {
    $scope.modalCallDetails.close();
  };

});;
